(window.GIM_TS=window.GIM_TS||{})["Chullin.3"]={"from":72,"a":[["\u0003גועה,\u0004 או \u0003הטילה ריעי,\u0004 או \u0003כשכשה באזנה\u0004 בשעת שחיטה — \u0003הרי זה פירכוס,\u0004 ושחיטתה מתירתה. \u0003אמר להו\u0004 \u0005[להם]\u0006 שמואל: \u0003אצטריכא ליה\u0004 \u0005[הוצרך לו]\u0006 \u0003לאבא\u0004 (לרב) \u0003לאזוזי אוני\u0004 \u0005[להזיז את האזניים]\u0006 כדי שייקרא הדבר פירכוס? \u0003שאני אומר: כל\u0004 דבר שהבהמה עושה בשעת השחיטה \u0003שאינו דברים שהמיתה עושה\u0004 — הרי זה סימן חיים.","ושואלים: \u0003מאי נינהו\u0004 \u0005[מה הם]\u0006 ה\u0003דברים שהמיתה עושה? אמר רב ענן, לדידי מפרשא לי מיניה דמר\u0004 \u0005[לי נתפרש\u0006 הדבר \u0005ממנו מהחכם]\u0006 \u0003שמואל\u0004 עצמו: \u0003היתה ידה כפופה ופשטתה\u0004 — הרי זה \u0003דבר שהמיתה עושה,\u0004 אם היתה ידה \u0003פשוטה וכפפה\u0004 אותה — הרי זה \u0003דברים שאין המיתה עושה,\u0004 והוא פירכוס.","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה משמיע לנו]\u0006 בזאת? הרי כבר \u0003תנינא\u0004 \u0005[שנינו\u0006 דבר זה במשנתנו\u0005]:\u0006 \u0003בהמה דקה שפשטה ידה ולא החזירה\u0004 — \u0003פסולה, שאינה אלא הוצאת נפש;\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003החזירה\u0004 את ידה — \u0003כשרה!\u0004","ומשיבים: \u0003אי ממתניתין\u0004 \u0005[אם ממשנתנו\u0006 בלבד\u0005],\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003דוקא דכייפה ופשטה והדר כייפה לה\u0004 \u0005[שכפפה ופשטה אותה וחזרה וכפפה אותה]\u0006 הריהי כשרה, \u0003אבל פשוטה\u0004 מתחילה \u0003וכפפתה\u0004 — \u0003לא\u0004 נחשב הדבר לסימן חיות, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שמואל שזה לבדו מספיק.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי רב לעיל ממה ששנינו בברייתא: \u0003ר' יוסי אומר, היה ר' מאיר אומר:\u0004 אם \u0003גועה בשעת שחיטה\u0004 — \u0003אין זה פירכוס, ר' אלעזר בר' יוסי אומר משמו\u0004 של ר' יוסי: \u0003אפילו הטילה ריעי\u0004 או \u0003כשכשה בזנבה\u0004 — \u0003אין זה פירכוס.\u0004 אם כן, \u0003קשיא\u0004 \u0005[קשה]\u0006 מענין \u0003גועה\u0004 על \u0003גועה,\u0004 שאמר רב שהוא פירכוס, וכן \u0003קשיא\u0004 \u0005[קשה]\u0006 מהטלת \u0003ריעי\u0004 על הטלת \u0003ריעי!\u0004","ומשיבים: מענין \u0003גועה\u0004 על ענין \u0003גועה לא קשיא\u0004 \u0005[לא קשה]:\u0006 \u0003הא דעבי קלה\u0004 \u0005[זה שעבה,\u0006 חזק \u0005קולה],\u0006 הרי זה סימן חיות, שיש בה כח, \u0003הא דעמי קלה\u0004 \u0005[זה שעמום קולה],\u0006 אין זה סימן חיות. וכן מענין \u0003ריעי\u0004 על ענין \u0003ריעי נמי\u0004 \u0005[גם כן]\u0006 \u0003לא קשיא\u0004 \u0005[לא קשה]:\u0006 \u0003כאן בשותתת\u0004 ריעי אין זה סימן חיות, \u0003כאן במתרזת\u0004 בכוח — הרי זה סימן חיות.","ועוד בהגדרת הפירכוס, \u0003אמר רב חסדא:\u0004 שמעתי מרבותי ש\u0003פירכוס שאמרו\u0004 שהוא סימן חיים. ומתירים בגללו את המסוכנת, הוא זה שאירע \u0003בסוף\u0004 ה\u0003שחיטה.\u0004 והוסיף רב חסדא, \u0003מאי\u0004 \u0005[\u0006ו\u0005מה פירוש]\u0006 \u0003בסוף שחיטה?\u0004 לא בסוף שחיטה ממש, אלא אפילו \u0003באמצע שחיטה, לאפוקי\u0004 \u0005[להוציא]\u0006 אם פרכסה רק ב\u0003תחלת שחיטה,\u0004 ש\u0003לא\u0004 מתירים אותה בגללו, מפני שסימן הוא שלא נותרה בה חיות עד גמר השחיטה.","\u0003אמר רב חסדא: מנא אמינא לה\u0004 \u0005[מנין אני אומר זאת]?\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנתנו\u0005]:\u0006 \u0003בהמה דקה שפשטה ידה\u0004 בשעת שחיטה \u0003ולא החזירה\u0004 — \u0003פסולה,\u0004 שאין זה אלא סימן ליציאת הנפש. ונברר: \u0003אימת\u0004 \u0005[מתי]\u0006 היה הדבר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003בסוף שחיטה, כל היכי תיחי ותיזיל\u0004 \u0005[כל כך היא צריכה להמשיך ולחיות]\u0006 לאחר שחיטה, עד שתחזיר ידה? \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003באמצע שחיטה?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 אין מכאן ראיה, \u0003לעולם\u0004 אפשר לפרש שמדובר \u0003בסוף\u0004 ה\u0003שחיטה,\u0004 ובכל זאת פסולה, \u0003שאני אומר: כל שאינה עושה כן\u0004 שמחזירה את ידה \u0003בסוף שחיטה\u0004 — \u0003בידוע שנשמתה נטולה הימנה\u0004 (ממנה) עוד \u0003קודם לכן.\u0004","\u0003רב נחמן בר יצחק אמר: פירכוס שאמרו\u0004 שהוא סימן חיים — אפילו היה \u0003בתחלת שחיטה.\u0004","והוסיף ו\u0003אמר רב נחמן בר יצחק: מנא אמינא לה\u0004 \u0005[מנין אני אומר אותה]?\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנתנו\u0005],\u0006 \u0003אמר ר' שמעון: השוחט בלילה, ולמחר מצא כתלים מלאים דם\u0004 — \u0003כשרה,\u0004 שכן ודאי \u0003שזינקה\u0004 בשעת שחיטה, \u0003וכמדת ר' אליעזר. ואמר שמואל:\u0004 כתלים אלה אינם כתלים של הבית, אלא \u0003כותלי בית שחיטה שנינו,\u0004 כלומר, מקום השחיטה בצואר. ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שאפילו \u0003בתחלת שחיטה\u0004 סימן חיים הוא — \u0003שפיר\u0004 \u0005[יפה,\u0006 מובן הדבר\u0005],\u0006 \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שדווקא אם היה \u0003בסוף שחיטה,\u0004 מה יועיל הדבר שנמצא דם במקום השחיטה? \u0003ליחוש דלמא\u0004 \u0005[נחשוש שמא]\u0006 \u0003בתחלת שחיטה זינקה\u0004 דמה, ואחר כך כבר לא עשתה כן!","ודוחים: \u0003ודלמא שאני\u0004 \u0005[ושמא שונה]\u0006 \u0003זינוק\u0004 שהוא \u0003עדיף\u0004 מפירכוס יד או רגל, שהוא סימן חיות גדול יותר, ודי אם נעשה בתחילת השחיטה כדי להראות על חיות. אבל בפירכוס, רק אם נעשה הדבר באמצע השחיטה הרי זה סימן חיות.","ומשיבים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003עדיף\u0004 הוא? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]\u0006 \u0003ר' אליעזר אומר: דייה אם זינקה,\u0004 ומהלשון \"דייה\" משמע שזינקה הוא סימן קל יותר מזה שאמר רבן גמליאל שתפרכס ביד וברגל! ואומרים: אכן, הזינוק סימן \u0003קל\u0004 הוא יותר \u0003מ\u0004הסימן שנתן \u0003רבן גמליאל,\u0004 שהצריך פירכוס ביד וגם ברגל, \u0003ו\u0004אולם הוא \u0003עדיף מדרבנן\u0004 \u0005[מן\u0006 הסימן \u0005של חכמים]\u0006 שהוא פירכוס או ביד או ברגל, שהוא סימן חיים דווקא אם היה באמצע השחיטה, ולא בתחילתה.","\u0003אמר רבינא: אמר לי סמא בר חילקאי, אקשי בה אבוה דבר\u0004 \u0005[הקשה בה אביו של בן]\u0006 \u0003אבוברם, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהקשה \u0003אחוה דבר\u0004 \u0005[אחיו של בן]\u0006 \u0003אבוברם: ומדרבנן\u0004 \u0005[ומן\u0006 הסימן שאמרו \u0005חכמים]\u0006 \u0003מי\u0004 \u0005[האם]\u0006 זינוק \u0003עדיף? והא תנן\u0004 \u0005[והרי שנינו],\u0006 \u0003וחכמים אומרים:\u0004 אינה כשרה \u0003עד שתפרכס או ביד או ברגל.\u0004","ונברר: \u0003רבנן אהייא קיימו\u0004 \u0005[חכמים על מה הם עומדים],\u0006 לאיזו דעה הם מתייחסים? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 על זו של \u0003רבן גמליאל,\u0004 שאינו סימן חיים עד שתפרכס ביד וגם ברגל — והלוא מקילים הם ממנו, ואם כן \u0003\"כיון שפירכסה\" מיבעי ליה\u0004 \u0005[צריך היה לו לומר],\u0006 שדי בכך!","\u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שדבריהם מתייחסים לשיטת \u0003ר' אליעזר,\u0004 שאמר: דיה אם זינקה. \u0003ו\u0004מעתה, \u0003אי\u0004 \u0005[אם]\u0006 זינוק \u0003עדיף, מאי\u0004 \u0005[מהי]\u0006 לשון \u0003\"עד\u0004 שתפרכס ביד או ברגל\"? והרי \"כיון שפירכסה ביד או ברגל\" צריך היה לומר! אלא בהכרח, זינוק נחשב סימן חיות קטן יותר. ואם כן עומדת בעינה ההוכחה של רב נחמן בר יצחק, מזינוק שבתחילת השחיטה, שהוא סימן חיות, וכל שכן פירכוס.","\u0003רבא אמר: פירכוס שאמרו\u0004 שהוא סימן חיים — דווקא אם היה \u0003בסוף שחיטה. אמר רבא: מנא אמינא לה\u0004 \u0005[מנין אני אומר אותה]?\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"שור\u0004"],["\u0003או כשב\"\u0004 (ויקרא כב, כז) — הרי זה \u0003פרט לכלאים\u0004 שפסול לקרבן, \u0003\"או עז\"\u0004 — \u0003פרט לנדמה,\u0004 שדומה למין אחר של בהמה, \u0003\"כי יולד\"\u0004 — \u0003פרט ליוצא דופן,\u0004 שאינו נולד כרגיל, אלא מוציאים אותו בניתוח דופן הרחם, \u0003\"שבעת ימים\"\u0004 — \u0003פרט למחוסר זמן,\u0004 שלא מלאו לו שבעה ימים, \u0003\"תחת אמו\"\u0004 — \u0003פרט ליתום.\u0004","ונברר: \u0003האי יתום היכי דמי\u0004 \u0005[יתום זה\u0006 שמיעט הכתוב \u0005כיצד הוא]?\u0006 \u0003אילימא דילידתיה אמיה והדר מתה\u0004 \u0005[אם תאמר שילדה אותו אמו ואחר כך מתה],\u0006 וכי \u0003לעולם תיחי ותיזיל\u0004 \u0005[תחיה ותלך]?\u0006 \u0003אלא\u0004 תאמר ש\u0003מתה והדר ילידתיה\u0004 \u0005[ואחר כך ילדה אותו],\u0006 ואולם \u0003זה\u0004 \u0003מ\u0004מה שנאמר \u0003\"כי יולד\" נפקא\u0004 \u0005[יוצא],\u0006 שהרי לאחר מיתה אין הבהמה יולדת, אלא מוציאים את הולד בניתוח!","\u0003אלא פשיטא\u0004 \u0005[פשוט],\u0006 שמדובר שהאם מתה בגמר הלידה, כך ש\u0003זה\u0004 (האם) \u0003פירש למיתה\u0004 \u0003וזה\u0004 (הולד) \u0003פירש לחיים,\u0004 והוא הקרוי יתום, שנפסל לקרבן. ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 כי \u0003בעינן חיותא\u0004 \u0005[צריכים אנו\u0006 שתהא \u0005חיות]\u0006 באם \u0003בסוף\u0004 ה\u0003לידה\u0004 — \u0003היינו דאיצטריך קרא למעוטי\u0004 \u0005[זהו שהוצרך הפסוק למעט]\u0006 יתום, שנשלמה לידתו בחיי אמו, לומר שכיון שבחייו אינו תחת אמו — נפסל להקרבה. \u0003אלא אי אמרת לא בעינן חיותא\u0004 \u0005[אם אומר אתה שלא צריך\u0006 שתהיה \u0005חיות]\u0006 באם \u0003בסוף\u0004 ה\u0003לידה,\u0004 נמצא שהכתוב ממעט ולד שנולד לאחר שמתה אמו, ואם כן \u0003למה ליה\u0004 מיעוט זה? \u0003מ\"כי יולד\" נפקא\u0004 \u0005[יוצא הדבר]!\u0006 אלא מכאן שכל דבר שצריך שתהא בו חיות — צריך שתהיה בסופו. והוא הדין לשחיטת בהמה מסוכנת, שאינה כשרה אלא אם היתה בה חיות ופירכסה בסוף השחיטה.","שנינו במשנתנו שבהמה דקה שפשטה ידה בשעת השחיטה ולא החזירה פסולה, שאינה אלא הוצאת נפש. \u0003אמר רבא: הלכתא\u0004 \u0005[ההלכה]\u0006 בענין זה היא \u0003כי הא מתניתא\u0004 \u0005[כמו ברייתא זו]:\u0006 \u0003בהמה דקה שפשטה ידה\u0004 בשעת שחיטה \u0003ולא החזירה\u0004 — \u0003פסולה.\u0004","\u0003במה דברים אמורים? ביד,\u0004 ברגל הקדמית, \u0003אבל ברגל\u0004 האחורית, \u0003בין פשטה ולא כפפה, בין כפפה ולא פשטה\u0004 — הרי היא \u0003כשרה.\u0004 וכן \u0003במה דברים אמורים? ב\u0004בהמה \u0003דקה, אבל ב\u0004בהמה \u0003גסה, בין ביד בין ברגל, בין פשטה ולא כפפה, בין כפפה ולא פשטה\u0004 — \u0003כשרה,\u0004 שהוא סימן חיות, ולא סימן של יציאת נפש. \u0003ועוף, אפילו לא רפרף אלא גפו\u0004 (כנפו), \u0003ולא כשכש אלא זנבו\u0004 — \u0003הרי זה\u0004 נחשב \u0003פירכוס\u0004 וסימן חיים.","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה משמיע לנו\u0006 רבא \u0005בכך]?\u0006 הלוא \u0003כולהו תננהי\u0004 \u0005[\u0006את \u0005כולם שנינו]\u0006 במשנה: \u0003בהמה דקה שפשטה ידה ולא החזירה\u0004 — \u0003פסולה, שאינה אלא הוצאת נפש.\u0004 ונדייק: \u0003יד\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003רגל\u0004 — \u0003לא;\u0004 בהמה \u0003דקה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003גסה\u0004 — \u0003לא!\u0004 ומשיבים: \u0003עוף איצטריכא ליה\u0004 \u0005[הוצרך לו],\u0006 \u0003דלא תנן\u0004 \u0005[שלא שנינו]\u0006 דבר זה במשנה, ושנינו בברייתא.","ישראל \u0003השוחט לנכרי\u0004 את בהמתו של הנכרי — \u0003שחיטתו כשרה, ור' אליעזר פוסל. אמר ר' אליעזר: אפילו שחטה\u0004 על מנת \u0003לאכול\u0004 (להאכיל) \u0003לנכרי מחצר כבד\u0004 (הסרעפת) \u0003שלה\u0004 בלבד — \u0003פסולה, שסתם מחשבת נכרי לעבודה זרה,\u0004 ובהמה שנשחטה לשם עבודה זרה אסורה בהנאה, כדין תקרובת עבודה זרה.","\u0003אמר ר' יוסי:\u0004 אין מחשבת הבעלים הנכרי משנה לענין זה. ו\u0003קל וחומר הדברים, ומה במקום שהמחשבה פוסלת\u0004 את השחיטה, כלומר, \u0003במוקדשין,\u0004 שמחשבה פסולה בזמן השחיטה, כגון להקריב את הקרבן לאחר זמנו, פוסלת את הקרבן — \u0003אין הכל הולך אלא אחר\u0004 מחשבת \u0003העובד,\u0004 הכהן השוחט, שמחשבתו פוסלת, ולא מחשבת הבעלים, \u0003מקום שאין מחשבה פוסלת,\u0004 כלומר, \u0003בחולין\u0004 — \u0003אינו דין שלא יהא הכל הולך אלא אחר השוחט\u0004 ולא אחר מחשבת הבעלים? ולכן כאשר השוחט ישראל — אין מחשבת הבעלים \u0003הנכרי לעבודה זרה פוסלת את השחיטה.\u0004","בביאור המחלוקת במשנתנו בין התנא הראשון לבין ר' אליעזר, מסבירים: \u0003הני תנאי אית להו\u0004 \u0005[תנאים אלה יש להם,\u0006 שניהם מקבלים את דבריו\u0005]\u0006 של \u0003ר' אליעזר בר' יוסי\u0004 ביחס לשחיטת קדשים. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' אליעזר בר' יוסי: שמעתי ש\u0004גם \u0003הבעלים מפגלין\u0004 (פוסלים את הקרבן כשחשבו בו מחשבת פסול), ולא רק הכהן העובד. והוא הדין למחשבת עבודה זרה בשחיטת בהמת חולין, שמחשבת הבעלים פוסלת אותה.","\u0003מיהו\u0004 \u0005[אולם]\u0006 \u0003תנא קמא סבר\u0004 \u0005[התנא הראשון סבור]:\u0006 רק \u0003אי שמעיניה דחשיב\u0004 \u0005[אם שמענו אותו\u0006 את הגוי \u0005שהוא מחשב]\u0006 לשם עבודה זרה — \u0003אין\u0004 \u0005[כן],\u0006 הרי זה פוסל, אבל \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 שמענו — \u0003לא,\u0004 שלדעתו, \u0003סתם מחשבת נכרי לעבודה זרה לא אמרינן\u0004 \u0005[אין אנו אומרים].\u0006 \u0003ור' אליעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003אף על גב דלא שמעיניה דחשיב\u0004 \u0005[אף על פי שלא שמענו אותו שהוא מחשב]\u0006 לשם עבודה זרה — פסול, ש\u0003סתם מחשבת נכרי לעבודה זרה אמרינן\u0004 \u0005[אומרים אנו].\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' יוסי למימר\u0004 \u0005[לומר]:\u0006 \u0003אף על גב דשמעיניה דחשיב\u0004 \u0005[אף על פי ששמענו אותו שהוא מחשב]\u0006 ומתכוון לכך במפורש, אין מחשבתו קובעת, שהרי אפילו בקדשים \u0003זה מחשב וזה עובד לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 שפוסל, אלא הכל הולך אחר מחשבת העובד.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת: \u0003בדשמעיניה דחשיב פליגי\u0004 \u0005[ב\u0006מקרה \u0005ששמענו אותו,\u0006 את הגוי, \u0005שהוא מחשב\u0006 לשם עבודה זרה \u0005חלוקים הם],\u0006 \u0003תנא קמא סבר\u0004 \u0005[התנא הראשון סבור]:\u0006 \u0003כי אמרינן\u0004 \u0005[כאשר אומרים אנו]\u0006 \u0003זה מחשב וזה עובד\u0004 פסול — \u0003הני מילי\u0004 \u0005[דברים אלו אמורים]\u0006 \u0003בפנים,\u0004 כלומר, בקרבנות, וכדברי ר' אליעזר בר' יוסי, \u0003אבל בחוץ,\u0004 במחשבת עבודה זרה בשחיטת חולין — \u0003לא,\u0004 שכן הלכות שחיטת \u0003חוץ מ\u0004שחיטת \u0003פנים\u0004"],["\u0003לא ילפינן\u0004 \u0005[אין אנו למדים].\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' אליעזר למימר\u0004 \u0005[לומר]:\u0006 \u0003ילפינן\u0004 \u0005[למדים אנו]\u0006 \u0003חוץ מפנים\u0004 שהבעלים פוסל, \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' יוסי למימר\u0004 \u0005[לומר]:\u0006 \u0003אפילו בפנים נמי\u0004 \u0005[גם כן]\u0006 \u0003זה מחשב וזה עובד לא אמרינן\u0004 \u0005[אין אנו אומרים].\u0006","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה הקשורה למשנתנו: \u0003השוחט את הבהמה\u0004 על מנת \u0003לזרוק דמה לעבודה זרה,\u0004 או על מנת \u0003להקטיר חלבה לעבודה זרה\u0004 — \u0003ר' יוחנן אמר:\u0004 השחיטה \u0003פסולה\u0004 על ידי כך, והבהמה אסורה בהנאה. \u0003ר' שמעון בן לקיש אמר: מותרת.\u0004","ומסבירים את השיטות: \u0003ר' יוחנן אמר פסולה,\u0004 כי לדעתו בעבודת הקרבנות \u0003מחשבין מעבודה לעבודה,\u0004 כלומר, העוסק בעבודה אחת, ומחשב באותה שעה מחשבת \u0003פסול בעבודה שניה —\u0004 הרי זה פוסל, \u0003וילפינן\u0004 \u0005[ולמדים אנו]\u0006 \u0003חוץ מפנים,\u0004 שכשם שדין זה קיים לגבי קרבנות — כך הוא לגבי איסור הקרבה לעבודה זרה.","\u0003ריש לקיש אמר מותרת,\u0004 כי לדעתו \u0003אין מחשבין\u0004 בקדשים \u0003מעבודה לעבודה, ולא גמרינן\u0004 \u0005[ו\u0006גם \u0005אין אנו למדים]\u0006 \u0003חוץ מפנים.\u0004","\u0003ואזדו לטעמייהו\u0004 \u0005[ו\u0006הם \u0005הולכים לשיטותיהם],\u0006 \u0003דאתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו ביחס לעבודת הקרבנות בפנים: \u0003שחטה\u0004 את החטאת \u0003לשמה\u0004 על מנת \u0003לזרוק דמה שלא לשמה\u0004 — \u0003ר' יוחנן אמר: פסולה, ר' שמעון בן לקיש אמר: כשרה.\u0004","ומסבירים: \u0003ר' יוחנן אמר פסולה,\u0004 כי \u0003מחשבין מעבודה לעבודה, ו\u0004טעם הדבר — מפני ש\u0003גמרינן\u0004 \u0005[לומדים אנו]\u0006 דין מחשבה שלא לשמה בחטאת \u0003מ\u0004דין \u0003מחשבת פיגול,\u0004 שהשוחט קרבן על מנת לזרוק דמו לאחר זמנו, עושה אותו פיגול. ואילו \u0003ר' שמעון בן לקיש אמר כשרה,\u0004 שלשיטתו, בפסול מחשבת שלא לשמה \u0003אין מחשבין מעבודה לעבודה, ו\u0004טעמו — מפני ש\u0003לא גמרינן\u0004 \u0005[אין אנו למדים]\u0006 \u0003ממחשבת פיגול\u0004 למחשבת פסול אחרת.","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שתיאמר המחלוקת ביניהם בשני הנושאים, מפני \u0003דאי איתמר בהא\u0004 \u0005[שאם היתה נאמרת\u0006 המחלוקת רק \u0005בזו],\u0006 בשוחט בהמה לזרוק דמה לעבודה זרה, היינו אומרים: \u0003בהא קאמר\u0004 \u0005[בזו אומר]\u0006 \u0003ר' שמעון בן לקיש\u0004 שאין מחשבים מעבודה לעבודה, \u0003משום\u0004 ש\u0003חוץ מפנים לא ילפינן\u0004 \u0005[אין אנו למדים],\u0006 \u0003אבל פנים מפנים אימא מודי ליה\u0004 \u0005[אמור שמודה לו]\u0006 \u0003לר' יוחנן,\u0004 שלמדים מחשבת פסול שלא לשמה ממחשבת פיגול, ולכן השוחט חטאת לשמה על מנת לזרוק דמה שלא לשמה — פסלה.","ולהיפך, \u0003ואי אתמר בהך\u0004 \u0005[ואם היתה נאמרת\u0006 המחלוקת \u0005בההיא],\u0006 בענין שוחט חטאת לזרוק דמה שלא לשמה, הייתי אומר: \u0003בההיא קאמר\u0004 \u0005[אומר]\u0006 \u0003ר' יוחנן\u0004 שהיא פסולה, משום שלמדים מחשבת פנים ממחשבת פנים, \u0003אבל בהא\u0004 \u0005[בזו]\u0006 בעבודה זרה — \u0003אימא מודי ליה\u0004 \u0005[אמור שמודה לו]\u0006 \u0003לר' שמעון בן לקיש,\u0004 שאין למדים חוץ מפנים, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שתי המחלוקות.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב ששת\u0004 על ר' יוחנן ועל ריש לקיש, ממה ששנינו במשנתנו בענין השוחט עבור גוי, וכוונת הגוי בשעת השחיטה לעבודה זרה, \u0003אמר ר' יוסי: קל וחומר הדברים, ומה במקום שמחשבה פוסלת,\u0004 כלומר, \u0003במוקדשין\u0004 — \u0003אין הכל הולך אלא אחר העובד,\u0004 ומחשבת הבעלים אינה פוסלת, \u0003מקום שאין\u0004 ה\u0003מחשבה פוסלת,\u0004 כלומר, \u0003בחולין\u0004 (בשוחט לעבודה זרה) — \u0003אינו דין שלא יהא הכל הולך אלא אחר\u0004 מחשבת \u0003השוחט?\u0004","ונברר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אין מחשבה פוסלת בחולין? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003דלא פסלה\u0004 \u0005[שאינה פוסלת]\u0006 \u0003כלל, אלא\u0004 לפי זה, \u0003זביחה\u0004 ל\u0003עבודה זרה דמיתסרא\u0004 \u0005[שהיא אסורה]\u0006 בהנאה משום תקרובת עבודה זרה, \u0003היכי משכחת לה\u0004 \u0005[היכן אתה מוצא אותה]?\u0006","\u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שהכוונה היא שאין המחשבה \u0003מעבודה לעבודה\u0004 אוסרת בעבודה זרה, שהשוחט בהמה על מנת לזרוק דמה לעבודה זרה אינו אוסר אותה, אלא רק כשמתכוון בשחיטה עצמה לשם עבודה זרה. \u0003ו\u0004לפי זה \u0003הכי קאמר\u0004 \u0005[כך\u0006 ר' יוסי \u0005אומר]:\u0006 \u0003ומה במקום שמחשבה פוסלת במוקדשין,\u0004 כלומר, \u0003מעבודה לעבודה\u0004 — בכל זאת \u0003אין הכל הולך אלא אחר העובד,\u0004 ואין מחשבת הבעלים פוסלת, \u0003מקום שאין מחשבה פוסלת,\u0004 כלומר, \u0003בחולין,\u0004 שאין המחשבה \u0003מעבודה לעבודה\u0004 אוסרת בעבודה זרה, \u0003אלא\u0004 רק \u0003באותה עבודה\u0004 עצמה — \u0003אינו דין שלא יהא הכל הולך אלא אחר השוחט?\u0004","ואם כן, מה שנאמר שמחשבים מעבודה לעבודה ב\u0003פנים קשיא\u0004 \u0005[קשה]\u0006 \u0003לר' שמעון בן לקיש,\u0004 ומה שנאמר שאין מחשבה פוסלת מעבודה לעבודה ב\u0003חוץ קשיא\u0004 \u0005[קשה]\u0006 \u0003לר' יוחנן!\u0004","והוסיף רב ששת: \u0003בשלמא\u0004 \u0005[נניח]\u0006 מה שמחשבים מעבודה לעבודה ב\u0003פנים, לר' שמעון בן לקיש לא קשיא\u0004 \u0005[אינו קשה],\u0006 שיש לומר: \u0003הא מקמי דשמעה\u0004 \u0005[זו לפני ששמעה]\u0006 את משנתנו \u0003מר' יוחנן\u0004 רבו, \u0003הא לבתר דשמעה\u0004 \u0005[זו לאחר ששמעה]\u0006 \u0003מר' יוחנן,\u0004 ולמסקנה אינו חולק אלא במחשב מעבודה לעבודה בעבודה זרה. \u0003אלא\u0004 מה שלמדנו מכאן שאין מחשבים מעבודה לעבודה ב\u0003חוץ קשיא\u0004 \u0005[קשה]\u0006 \u0003לר' יוחנן!\u0004","ואומרים: \u0003הוא מותיב לה והוא מפרק לה\u0004 \u0005[הוא,\u0006 רב ששת, \u0005מקשה אותה והוא גם היה מתרץ אותה]:\u0006 מה שנאמר במשנה שמחשבה פוסלת בפנים ואינה פוסלת בחוץ — לא במחשבה מעבודה לעבודה נאמר, אלא הכוונה היא שהמחשבה פוסלת בפנים כשחישב מחשבת פסול (כגון לאכול לאחר זמנו) \u0003ב\u0004עשיית כל אחת מ\u0003ארבע עבודות\u0004 הזבח, מה שאין כן בעבודה זרה. \u0003והכי קאמר\u0004 \u0005[וכך הוא אומר]:\u0006 \u0003ומה במקום שמחשבה פוסלת\u0004 כלומר, \u0003במוקדשין ב\u0004כל \u0003ארבע עבודות\u0004 הנעשות בהם: שחיטה, קבלה, הולכה וזריקת הדם — \u0003אין הכל הולך אלא אחר\u0004 מחשבת \u0003העובד,\u0004"],["\u0003מקום שאין מחשבה פוסלת,\u0004 כלומר, \u0003בחולין,\u0004 שאין המחשבה פוסלת \u0003אלא בשתי עבודות,\u0004 בשחיטה ובזריקה בלבד — \u0003אינו דין שלא יהא הכל הולך אלא אחר השוחט?\u0004","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן: השוחט את הבהמה\u0004 במחשבה \u0003לזרוק דמה לעבודה זרה\u0004 או \u0003להקטיר חלבה לעבודה זרה\u0004 — \u0003הרי אלו זבחי מתים.\u0004 ומוסיפה הברייתא: אם \u0003שחטה\u0004 תחילה סתם \u0003ואחר כך חישב עליה\u0004 לזרוק דמה או להקטיר חלבה לעבודה זרה — \u0003זה היה מעשה בקיסרי ולא אמרו בה\u0004 חכמים \u0003לא איסור ולא היתר.\u0004","ובטעם הדבר, \u0003אמר רב חסדא: לא אמרו בה איסור\u0004 — \u0003משום כבודן דרבנן\u0004 \u0005[של חכמים]\u0006 במשנתנו, שלדעתם אין אומרים סתם מחשבת נכרי לעבודה זרה, ולכן שחיטתו שנעשתה בסתם — כשרה. ו\u0003לא\u0004 אמרו בה \u0003היתר\u0004 — \u0003משום כבודו\u0004 של \u0003ר' אליעזר,\u0004 שהוא סבור שסתם מחשבת נכרי לעבודה זרה.","ומקשים: \u0003ממאי\u0004 \u0005[ממה]\u0006 אתה מסיק מסקנה \u0003זו?\u0004 \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי רבנן התם\u0004 \u0005[אומרים חכמים שם]\u0006 במשנה, \u0003אלא\u0004 במקרה \u0003דלא שמענא דחשיב\u0004 \u0005[שלא שמענו\u0006 אותו \u0005ש\u0006הוא \u0005מחשב\u0006 כלל\u0005]\u0006 לשם עבודה זרה, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003דשמענא דחשיב\u0004 \u0005[ששמענו\u0006 אותו \u0005ש\u0006הוא \u0005מחשב]\u0006 לזרוק את דמה ולהקטיר את חלבה — \u0003הוכיח סופו על תחלתו\u0004 שלכך התכוון גם בשעת השחיטה!","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לדחות מצד אחר: \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אומר]\u0006 \u0003ר' אליעזר התם\u0004 \u0005[שם]\u0006 שהשחיטה אסורה \u0003אלא\u0004 ל\u0003גבי נכרי,\u0004 ומשום ש\u0003סתם מחשבת נכרי לעבודה זרה, אבל\u0004 לגבי \u0003ישראל,\u0004 שאין סתם מחשבתו לעבודה זרה, אינו אומר כן, ולשיטתו \u0003הוכיח סופו על תחלתו לא אמרינן\u0004 \u0005[אין אנו אומרים]!\u0006","\u0003אלא אמר רב שיזבי: לא אמרו בה היתר\u0004 — \u0003משום כבודו\u0004 של \u0003רבן שמעון בן גמליאל,\u0004 הסבור שככלל אומרים אנו ש\"הוכיח סופו על תחילתו\". ושואלים: \u0003הי\u0004 \u0005[לאיזה]\u0006 מדברי \u0003רבן שמעון בן גמליאל\u0004 הוא מתכוון?","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 לשיטת \u0003רבן שמעון בן גמליאל\u0004 של \u0003גיטין, דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 אדם העומד למות ואמר לאנשים \"כתבו גט לאשתי\" — יכתבו ויתנו, למרות שלא ציווה במפורש שיתנו, מפני שבוודאי היתה כוונתו לכך. אבל \u0003הבריא שאמר \"כתבו גט לאשתי\",\u0004 הואיל ולא ציוה במפורש לתיתו לה — כותבים אבל אין נותנים לה, שאנו מניחים שרק \u0003רצה לשחק בה,\u0004 ולא עשה אותם שליחים לכך.","\u0003ומעשה בבריא שאמר \"כתבו גט לאשתי\"\u0004 וכתבו, \u0003ו\u0004אחר כך \u0003עלה לגג ונפל ומת, אמר רבן שמעון בן גמליאל: אם מעצמו נפל,\u0004 שהתאבד — \u0003הרי זה גט,\u0004 ויתנוהו לה, מפני שמוכח שמפני שהתכוון למות ציוה לכתוב את הגט לאשתו, \u0003ואם הרוח דחתו\u0004 (הפילה אותו) ועל ידי כך","\u0003מת —\u0004 \u0003אינו גט. והוינן\u0004 \u0005[והיינו עוסקים,\u0006 מתקשים\u0005]\u0006 \u0003בה:\u0004 וכי מביאים \u0003מעשה לסתור\u0004 את הדברים שנאמרו קודם? שהרי מתחילה נאמר סתם שאומרים אנו שרצה לשחק בה, ולא חילקו בדבר!","והסברנו כי \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה המשנה וכך היא שנויה]:\u0006 \u0003אם הוכיח סופו על תחלתו,\u0004 שידע או חשש שהוא עומד למות — \u0003הרי זה גט, ומעשה נמי\u0004 \u0005[גם כן]\u0006 \u0003בבריא שאמר \"כתבו גט לאשתי\", ועלה לגג ונפל ומת,\u0004 ו\u0003אמר רבן שמעון בן גמליאל\u0004 בעניינו: \u0003אם מעצמו נפל\u0004 — \u0003הרי זה גט, ואם הרוח דחתו\u0004 — \u0003אינו גט.\u0004 לפי זה יש ללמוד גם לענייננו, שלשיטת רבן שמעון בן גמליאל, אם שחט בשתיקה ואחר כך זרק דמה לעבודה זרה — הוכיח סופו על תחילתו, ששחט לשם עבודה זרה, ולשיטה זו חששו חכמים ולא הורו בה היתר.","ודוחים: \u0003ודלמא שאני התם\u0004 \u0005[ושמא שונה שם]\u0006 לענין גט, \u0003דקאמר\u0004 \u0005[שאמר]\u0006 אותו איש מתחילה \u0003\"כתבו\u0004 גט לאשתי\", ודבר זה מורה שכוונתו היתה לכך מתחילה, מה שאין כן כאן, ששתק מתחילה!","\u0003אלא אמר רבינא:\u0004 מה שלא התירו בגלל \"הוכיח סופו על תחילתו\", הרי זה \u0003משום כבודו\u0004 של \u0003רבן שמעון בן גמליאל דהכא\u0004 \u0005[של כאן]\u0006 של ברייתא זו, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 שכיב מרע \u0003הכותב\u0004 (שכתב) \u0003נכסיו לאחרים\u0004 כמתנה \u0003והיו בהן\u0004 בתוך הנכסים \u0003עבדים, ואמר הלה\u0004 המקבל: \u0003אי אפשי\u0004 (אין רצוני) \u0003בהן\u0004 בעבדים, \u0003אם היה רבו\u0004 (אדוניו) ה\u0003שני,\u0004 המקבל, \u0003כהן\u0004 — \u0003הרי אלו\u0004 העבדים \u0003אוכלין בתרומה,\u0004 כדין עבדיו של כהן. \u0003רבן שמעון בן גמליאל אומר: כיון שאמר הלה אי אפשי בהן\u0004 — \u0003כבר זכו בהן יורשין\u0004 של הנותן.","\u0003והוינן\u0004 \u0005[והיינו עוסקים,\u0006 מתקשים\u0005]\u0006 \u0003בה:\u0004 וכי \u0003ל\u0004דעת \u0003תנא קמא\u0004 \u0005[התנא הראשון]\u0006 \u0003אפילו\u0004 אם \u0003עומד וצווח\u0004 שאינו רוצה, המתנה נקנית לו?","\u0003אמר רבה, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יוחנן: בצווח מעיקרא\u0004 \u0005[מתחילה]\u0006 בזמן שניתנה לו המתנה, שאינו רוצה בה — \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 ש\u0003לא קנה\u0004 מתנה זו; וכן \u0003בשותק\u0004 מתחילה, בזמן הנתינה, \u0003ובסוף\u0004 לאחר מעשה \u0003צווח\u0004 שאינו רוצה — \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 ש","\u0003קנה; כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה במקרה \u0003שזיכה לו\u0004 את נכסיו \u0003על ידי\u0004 אדם \u0003אחר,\u0004 כגון שנתן לאחר את שטר המתנה בפניו, \u0003ושתק\u0004 אותו האיש, \u0003ולבסוף צווח; תנא קמא סבר\u0004 \u0005[התנא הראשון סבור]:\u0006 \u0003מדשתיק\u0004 — \u0003קננהו\u0004 \u0005[מכיון ששתק\u0006 בזמן שהלה זכה עבורו — \u0005קנה אותם],\u0006 \u0003והאי דקא צווח\u0004 — \u0003מיהדר קא הדר ביה\u0004 \u0005[וזה שהוא צווח\u0006 עכשיו — \u0005חוזר הוא בו\u0006 ממה שאמר קודם\u0005],\u0006 אבל אינו יכול לשנות את הקנין על ידי חזרה זו.","\u0003ורבן שמעון בן גמליאל סבר\u0004 \u0005[סבור]:\u0006 \u0003הוכיח סופו על תחילתו,\u0004 שלא רצה בעבדים, והתכוון שלא לזכות בהם, \u0003והא דלא צווח מעיקרא\u0004 \u0005[וזה שלא צווח מתחילה],\u0006 הרי משום ש\u0003סבר\u0004 אותו אדם: \u0003כי לא אתי לידיה אמאי אצווח\u0004 \u0005[כאשר לא הגיעה המתנה לידי מדוע אצווח\u0006 עכשיו\u0005].\u0006","ושבים לעיקר המחלוקת במשנתנו. שר' יוסי אמר שהשוחט לגוי, אפילו ידוע שמחשבתו של הגוי לעבודה זרה — שחיטתו כשרה, שאין המחשבה הולכת אלא אחר השוחט ולא אחר הבעלים. \u0003אמר רב יהודה אמר שמואל: הלכה כר' יוסי.\u0004","מסופר, \u0003הנהו טייעי דאתו\u0004 \u0005[אותם ערבים שבאו]\u0006 \u0003לציקוניא, יהיב דיכרי\u0004 \u0005[נתנו אילים]\u0006 \u0003לטבחי\u0004 \u0005[לשוחטים]\u0006 \u0003ישראל\u0004 שישחטו עבורם, \u0003אמרו להו\u0004 \u0005[להם]\u0006 לטבחים: \u0003דמא ותרבא לדידן\u0004 \u0005[הדם והחלב\u0006 יהיה \u0005לנו],\u0006 לצורך פולחן עבודה זרה שלנו, \u0003משכא ובישרא לדידכו\u0004 \u0005[העור והבשר שלכם].\u0006 \u0003שלחה\u0004 \u0005[שלח]\u0006 \u0003רב טובי בר רב מתנה לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב יוסף: כי האי גוונא מאי\u0004 \u0005[כגון זה מהו]?\u0006 \u0003שלח ליה\u0004 \u0005[לו],\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יהודה אמר שמואל: הלכה כר' יוסי,\u0004 ואין הבשר נפסל על ידי מחשבתו של אחר, אפילו אם הוא הבעלים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אויא לרב אשי: ל\u0004דעת \u0003ר' אליעזר\u0004 במשנתנו, שהשוחט בהמתו של גוי שחיטתו פסולה, אם \u0003יהיב ליה זוזא\u0004 \u0005[נותן לו\u0006 הגוי \u0005דינר]\u0006 \u0003לטבח ישראל\u0004 כדי לקבל מעט מן הבשר, \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין? האם יש בכך לפסול את השחיטה כולה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חזינן\u0004 \u0005[רואים אנו]\u0006 \u0003אי איניש אלמא\u0004 \u0005[אם אדם אלים]\u0006 \u0003הוא\u0004 הגוי, \u0003דלא מצי מדחי ליה\u0004 \u0005[שאין\u0006 הישראל \u0005יכול לדחות אותו]\u0006 ולומר לו: קח את כספך בחזרה — \u0003אסור,\u0004 מפני שיש לו חלק בבהמה, והוא שוחט גם עבורו, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא,\u0004 אם אינו אדם אלים — \u0003אמר ליה\u0004 \u0005[אומר לו]\u0006 הישראל: \u0003רישיך והר\u0004 \u0005[ראשך וההר],\u0006 כלומר, הכה את ראשך בהר, אני איני שוחט עבורך.","\u0003השוחט לשם הרים, לשם גבעות, לשם ימים, לשם נהרות, לשם מדברות,\u0004 שהוא נוהג בהם כבעבודה זרה — בכל אלה \u0003שחיטתו פסולה.\u0004"],["היו \u0003שנים אוחזין בסכין ושוחטין, אחד\u0004 מהם מתכוין \u0003לשם אחד מכל אלו\u0004 הפוסלים, \u0003ואחד לשם דבר כשר\u0004 — הרי \u0003שחיטתו פסולה.\u0004","שנינו שהשוחט לשם הרים וכו' שחיטתו פסולה. ומדייקים: \u0003פסולה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 אבל \u0003זבחי מתים,\u0004 שייחשבו כדבר שנזבח לעבודה זרה, לאוסרם בהנאה — \u0003לא.\u0004 \u0003ורמינהי\u0004 \u0005[ומשליכים]\u0006 מראים סתירה ממה ששנינו בברייתא: \u0003השוחט לשום\u0004 (לשם) \u0003הרים, לשום גבעות, לשום נהרות, לשום מדברות, לשום חמה ולבנה, לשום כוכבים ומזלות,\u0004 או \u0003לשום מיכאל השר הגדול\u0004 שבשמים, או אפילו \u0003לשום שילשול\u0004 (תולעת) \u0003קטן\u0004 — \u0003הרי אלו זבחי מתים,\u0004 זבחי עבודה זרה, שאסורים בהנאה!","\u0003אמר אביי, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו ששחיטתו פסולה אבל אינו אסור כעבודה זרה, הרי זה באופן \u0003דאמר\u0004 \u0005[ש\u0006הוא \u0005אומר]\u0006 שהוא שוחט \u0003ל\u0004שם \u0003הר,\u0004 שאין ההר כשלעצמו נחשב עבודה זרה. \u0003הא\u0004 \u0005[זה]\u0006 ששנינו בברייתא שהוא זבח לעבודה זרה, הרי זה באופן \u0003דאמר לגדא דהר\u0004 \u0005[ש\u0006הוא \u0005אומר\u0006 שהוא שוחט \u0005למזלו של ההר].\u0006 ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק\u0006 הדבר \u0005גם כן]\u0006 שבברייתא מדובר במי ששוחט לשם המזל של ההר, \u0003דקתני דומיא\u0004 \u0005[שהוא שונה\u0006 שוחט לשם הרים \u0005בדומה]\u0006 ל\u0003מיכאל שר הגדול, שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהוא מתכוון למהות רוחנית ולא להר עצמו.","\u0003אמר רב הונא: היתה בהמת חבירו רבוצה לפני עבודה זרה, כיון ששחט בה\u0004 אפילו \u0003סימן אחד\u0004 — \u0003אסרה.\u0004 ומעירים: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003אמר עולא אמר ר' יוחנן: אף על פי שאמרו המשתחוה לבהמת חבירו לא אסרה\u0004 על ידי השתחויה זו, אם \u0003עשה בה\u0004 עצמה \u0003מעשה\u0004 של עבודה זרה — \u0003אסרה.\u0004 ואף כאן, הרי שחט אותה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב נחמן לרב הונא\u0004 ממה ששנינו בברייתא: \u0003השוחט\u0004 בהמה שהוקדשה לקרבן \u0003חטאת,\u0004 והיה זה \u0003בשבת, בחוץ\u0004 (מחוץ לעזרה), ו\u0003ל\u0004שם \u0003עבודה זרה,\u0004 ועשה כל אלה בשוגג — \u0003חייב שלש חטאות:\u0004 משום שחיטה בשבת, משום שחיטת קדשים בחוץ, ומשום שחיטה לעבודה זרה. \u0003ואי אמרת\u0004 \u0005[ואם אתה אומר]\u0006 \u0003כיון ששחט בה סימן אחד\u0004 מיד \u0003אסרה\u0004 משום עבודה זרה — משום \u0003שחוטי חוץ לא ליחייב\u0004 \u0005[שלא יתחייב],\u0006"],["הלוא רק \u0003מחתך בעפר הוא\u0004 נחשב, שהבהמה כבר נפסלה קודם לכן להקרבה, ואין חייבים על כך משום שוחט קדשים בחוץ! \u0003אמר רב פפא: הכא\u0004 \u0005[כאן]\u0006 בברייתא זו \u0003בחטאת העוף עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שבשחיטת סימן אחד כבר מתחייב עליה משום שחיטת חוץ, כך \u0003דכולהו בהדי הדדי קאתי\u0004 \u0005[שכולם,\u0006 כל האיסורים, \u0005בבת אחת הם באים]\u0006 בשחיטת הסימן ראשון.","ומקשים: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003רב הונא כמאן אמרה לשמעתיה\u0004 \u0005[כ\u0006דעת \u0005מי אמר את שמועתו זו]?\u0006 \u0003כ\u0004דעת \u0003עולא,\u0004 שאמר: עשה מעשה בבהמת חבירו לעבודה זרה — אסרה, \u0003ועולא\u0004 הרי \u0003מעשה כל דהו קאמר\u0004 \u0005[מעשה כל שהוא הוא אומר],\u0006 ולפי זה, בתחילת שחיטת הסימן הראשון כבר נאסרה, וכשהוא גומר את השחיטה בחוץ — מחתך בעפר הוא!","ומתרצים: \u0003אלא\u0004 יש לומר שברייתא זו עוסקת אפילו בבהמה, ו\u0003באומר\u0004 השוחט ש\u0003בגמר זביחה\u0004 (השחיטה) \u0003הוא עובדה\u0004 את העבודה זרה, ולא קודם לכן, וכך מתחייב על שלוש העבירות כאחת.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 הזכירה הברייתא \u0003חטאת? לישמעינן\u0004 \u0005[שישמיע לנו]\u0006 דין זה בכל \u0003זבח!\u0004","\u0003אלא אמר מר זוטרא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב פפא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 בחטאת העוף. ומה שהקשינו, שלשיטת רב הונא די במעשה כל שהוא לשם עבודה זרה כדי לאסור את העוף, ונמצא שכשהוא גומר את השחיטה כבר נאסרה — יש לתרץ שמדובר \u0003כגון שהיה חצי\u0004 ה\u0003קנה\u0004 של העוף \u0003פגום\u0004 עוד לפני שחיטה, \u0003והוסיף עליו\u0004 בשבת שחיטה \u0003כל שהוא\u0004 בחוץ לשם עבודה זרה, \u0003ו\u0004בכך \u0003גמרו,\u0004 ונמצא \u0003דכולהו בהדי הדדי קאתיין\u0004 \u0005[שכולם,\u0006 כל האיסורים, \u0005בבת אחת הם באים].\u0006","\u0003אמר רב פפא: אי לאו דאמר\u0004 \u0005[אם לא שאמר]\u0006 \u0003רב הונא\u0004 שדי ששחט בבהמה \u0003סימן אחד\u0004 לשם עבודה זרה כדי לאוסרה, \u0003לא הויא\u0004 \u0005[לא היתה]\u0006 הברייתא בענין \u0003חטאת תיובתיה\u0004 \u0005[קושיה עליו],\u0006 שיכולים היינו להסביר: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003מעשה\u0004 שאמר עולא שאוסר את הבהמה — \u0003מעשה רבה\u0004 \u0005[גדול],\u0006 שרק אם גמר את השחיטה לעבודה זרה, אסרה, ונמצא שבאותה שעה היה מתחייב על שלושת האיסורים כאחד, וכדברי הברייתא.","\u0003ו\u0004עוד \u0003אמר רב פפא: אי לאו דאמר\u0004 \u0005[אם לא שאמר]\u0006 \u0003רב הונא\u0004 שהשוחט \u0003בהמת חברו\u0004 לעבודה זרה אסרה, \u0003לא הויא\u0004 \u0005[לא היתה]\u0006 הברייתא בענין \u0003חטאת תיובתיה\u0004 \u0005[קושיה עליו],\u0006 שיכולים היינו להסביר: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 שאין החטאת נאסרת בתחילת השחיטה — מפני ש\u0003דידיה מצי אסר\u0004 \u0005[את\u0006 הבהמה \u0005שלו יכול לאסור],\u0006 \u0003דחבריה לא מצי אסר\u0004 \u0005[את של חבירו אינו יכול לאסור],\u0006 ובחטאת, הנהנים מבשרה הרי הם הכהנים. ואומרים: לשם מה להשמיענו דברים אלה?","\u0003פשיטא\u0004 \u0005[פשוט ש\u0006כן הוא\u0005]!\u0006 ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כיון דקני ליה\u0004 \u0005[שקנה אותה\u0006 את הבהמה\u0005]\u0006 \u0003ל\u0004שם \u0003כפרה\u0004 שלו — \u0003כדידיה דמיא\u0004 \u0005[כשלו\u0006 היא \u0005נחשבת],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאינה נחשבת כשלו ממש.","ובניגוד לרב הונא שאמר כי השוחט בהמת חבירו לעבודה זרה אסרה (\u0003סימן\u0004 לשמות האמוראים: \u0003נע\"ץ\u0004 — רב \u0003נ\u0004 חמן, רב \u0003ע\u0004 מרם, רב י \u0003צ\u0004 חק) \u0003רב נחמן ורב עמרם ורב יצחק אמרי\u0004 \u0005[אומרים]:\u0006 \u0003אין אדם אוסר דבר שאין שלו.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: \u0003השוחט חטאת בשבת בחוץ לעבודה זרה\u0004 — \u0003חייב שלש חטאות, ואוקמינן\u0004 \u0005[והעמדנו]\u0006 ברייתא זו \u0003בחטאת העוף ובחצי קנה פגום\u0004 מתחילה, והוסיף עליו כלשהו בשחיטה. ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 \u0003ב\u0004\u0003חטאת העוף הוא\u0004 שמדובר, מפני \u0003דכולהו בהדי הדדי קאתיין\u0004 \u0005[שכולם,\u0006 כל האיסורים, \u0005בבת אחת הם באים],\u0006"],["\u0003אבל זבח\u0004 קרבן מן הבהמה — \u0003לא, ואי\u0004 \u0005[ואם]\u0006 \u0003אין אדם אוסר דבר שאינו שלו, מאי אריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 צריך להעמידה דווקא ב\u0003חטאת העוף? אפילו\u0004 ב\u0003חטאת בהמה נמי\u0004 \u0005[גם כן]\u0006 יתחייב עליה משום שחוטי חוץ, משום שלא פקע שם קדשים ממנה כששחט בה סימן אחד, שהרי היא מיועדת לכהנים ואינה שלו! ומשיבים: \u0003כיון דקניא ליה\u0004 \u0005[ש\u0006היא \u0005קנויה לו]\u0006 \u0003לכפרה\u0004 שלו — \u0003כדידיה דמיא\u0004 \u0005[כשלו היא נחשבת],\u0006 ולכן הוא אוסרה.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 קושיה נוספת ממה ששנינו במשנתנו: \u0003שנים אוחזין בסכין\u0004 אחת \u0003ושוחטין, אחד לשום\u0004 (לשם) \u0003אחד מכל אלו\u0004 כגון לשם הרים וגבעות, \u0003ואחד לשום דבר כשר\u0004 — \u0003שחיטתו פסולה,\u0004 ומשמע, אפילו אם השוחט לשם אחד מכל אלו אינו הבעלים. הרי שיכול אדם לאסור דבר שאינו שלו! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003דאית ליה שותפות בגוה\u0004 \u0005[שיש לו שותפות בה],\u0006 ולכן הוא יכול לפוסלה.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת ממה ששנינו: \u0003המטמא\u0004 תרומה של חבירו הכהן, \u0003והמדמע,\u0004 מערב תרומה בפירות חולין של חבירו, \u0003והמנסך\u0004 יין של אחרים לעבודה זרה, אם עשה זאת \u0003בשוגג\u0004 — \u0003פטור\u0004 מלשלם, למרות שגרם לחבירו הפסד, שאינו יכול ליהנות מפירותיו או מן היין, אבל עשה זאת \u0003במזיד\u0004 — \u0003חייב.\u0004 משמע שאדם יכול לאסור דבר שאינו שלו! ומשיבים: \u0003הכא נמי דאית ליה שותפות בגוה\u0004 \u0005[כאן גם כן\u0006 מדובר \u0005שיש לו שותפות בה].\u0006","ומעירים: המחלוקת האם שוחט בהמת חבירו לעבודה זרה אסרה, כדעת רב הונא, או לא אסרה, וכדעת רב נחמן רב עמרם ורב יצחק, היא \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים],\u0006 ששנינו: \u0003גוי שניסך יינו של ישראל\u0004 לעבודה זרה, אפילו \u0003שלא בפני עבודה זרה\u0004 — \u0003אסרו; ר' יהודה בן בתירא ור' יהודה בן בבא מתירין אותו מפני שני דברים: אחד\u0004 — \u0003שאין\u0004 גוים \u0003מנסכין יין\u0004 לעבודה זרה \u0003אלא בפני עבודה זרה, ואחד\u0004 — \u0003ש\u0004אפילו היה מנסך לעבודה זרה \u0003יכול\u0004 הישראל \u0003לומר לו: לא כל הימנך\u0004 \u0005[לא הכל בכוחך,\u0006 אין באפשרותך\u0005]\u0006 \u0003שתאסר ייני לאונסי.\u0004","\u0003ורב נחמן ורב עמרם ורב יצחק\u0004 הסבורים שאדם אינו יכול לאסור דבר שאינו שלו, הם \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003אדם אוסר דבר שאינו שלו\u0004 — \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 דווקא ב\u0003גוי, אבל ישראל\u0004 ששוחט בהמת חבירו לעבודה זרה, אנו מניחים שרק \u0003לצעוריה קא מיכוין\u0004 \u0005[לצער אותו\u0006 את חבירו \u0005הוא מתכוין],\u0006 ואין כוונתו לעבוד עבודה זרה, ולכן אינו אוסרה.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 סתירה לדבר ממה ששנינו במשנתנו: \u0003שנים אוחזין בסכין ושוחטין, אחד לשום\u0004 (לשם) \u0003אחד מכל אלו ואחד לשום דבר כשר\u0004 — \u0003שחיטתו פסולה,\u0004 וכאן הרי מדובר בישראל! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003בישראל משומד לעבודה זרה,\u0004 שכשהוא אומר כן כוונתו בוודאי לעבודה זרה. ועוד מציעים,","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: \u0003המטמא והמדמע והמנסך\u0004 יינו של חבירו, \u0003בשוגג\u0004 — \u0003פטור, במזיד\u0004 — \u0003חייב,\u0004 הרי שישראל המנסך יינו של חבירו אוסרו! ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בישראל משומד.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי:\u0004 ישראל שלא היה משומד לעבודה זרה, שאמר שהוא שוחט לשם עבודה זרה, אם \u0003התרו בו\u0004 שדבר זה אסור מן התורה וחייבים עליו מיתה, \u0003וקבל עליו התראה,\u0004 שאמר: על דעת כן אני עושה, \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]\u0006 כששחט בהמת חבירו לעבודה זרה, האם אוסר אותה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אם \u0003התיר עצמו למיתה קאמרת\u0004 \u0005[אומר אתה]?\u0006 \u0003אין לך משומד גדול מזה.\u0004","\u0003אין שוחטין\u0004 בהמת חולין \u0003לא לתוך ימים, ולא לתוך נהרות, ולא לתוך כלים,\u0004 שכל אלה נראים כאילו נוהג כמנהג עבודה זרה. \u0003אבל שוחט הוא לתוך עוגה\u0004 (חפירה עגולה) \u0003של מים. ובספינה\u0004 יכול לשחוט \u0003על גבי כלים,\u0004 שניכר שמטרתו היא כדי שלא ללכלך את הספינה. \u0003אין שוחטין ל\u0004תוך \u0003גומא\u0004 (חפירה קטנה) \u0003כל עיקר, אבל עושה גומא בתוך ביתו בשביל שיכנס הדם לתוכה. ובשוק לא יעשה כן,\u0004 כדי \u0003שלא\u0004"],["\u0003יחקה את המינין,\u0004 כדי שלא לעשות כמעשיהם.","שנינו במשנתנו: \u0003אין שוחטין לא לתוך\u0004 ימים וכו', אבל שוחט הוא לתוך עוגה של מים. ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003לתוך ימים\u0004 ש\u0003לא\u0004 ישחט — מפני \u0003דאמרי\u0004 \u0005[שאומרים]\u0006 אנשים: \u0003לשרא דימא קא שחיט\u0004 \u0005[לשר הים הוא שוחט],\u0006 והרי אם שוחט \u0003לתוך עוגה של מים נמי אמרי\u0004 \u0005[גם כן אומרים]:\u0006 \u0003לבבואה\u0004 שלו שנראית במים \u0003קא שחיט\u0004 \u0005[הוא שוחט],\u0006 וגם הוא כעין עבודה זרה! \u0003אמר רבא: ב\u0004מים \u0003עכורים שנו,\u0004 שאין נראית שם בבואה.","עוד שנינו: \u0003אין שוחטין לגומא\u0004 כל עיקר, אבל עושה גומא בתוך ביתו בשביל שייכנס הדם לתוכה. ומקשים: כיצד שונה התנא שעושה גומא בתוך ביתו? \u0003והא אמרת\u0004 \u0005[והרי אמרת]\u0006 מתחילה: \u0003אין שוחטין לגומא כלל! אמר אביי: רישא\u0004 \u0005[בתחילה],\u0006 ששנינו שאין שוחטים כל עיקר, מדובר \u0003בגומא שבשוק,\u0004 ששם אין שוחטים כלל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא, והא מדקתני סיפא\u0004 \u0005[והרי ממה שהוא שונה בסוף]:\u0006 \u0003ובשוק לא יעשה כן, מכלל\u0004 הדברים אתה למד \u0003דרישא לאו בשוק עסקינן\u0004 \u0005[שבתחילה לא בשוק אנו עוסקים]!\u0006","\u0003אלא אמר רבא, הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003אין שוחטין לגומא כל עיקר. והרוצה לנקר\u0004 (לנקות) את \u0003חצרו,\u0004 שלא תהא מלוכלכת בדם, \u0003כיצד הוא עושה? עושה מקום\u0004 חריץ או מדרון \u0003חוץ לגומא ושוחט\u0004 שם, \u0003ודם שותת ויורד לגומא. ובשוק לא יעשה כן,\u0004 אפילו בדרך זו, כדי \u0003שלא יחקה את המינין.\u0004","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבא: היה מהלך\u0004 (שט) \u0003בספינה ואין לו מקום בספינה לשחוט\u0004 — מחזיק את הבהמה כשראשה חוץ לספינה, ו\u0003מוציא ידו חוץ לספינה ושוחט, ו\u0004ה\u0003דם שותת ויורד על דופני הספינה,\u0004 ומשם לים, אבל לא ישחוט לתוך הים. \u0003ואין שוחט לגומא כל עיקר.\u0004","\u0003והרוצה לנקר\u0004 את \u0003חצרו כיצד הוא עושה? עושה מקום\u0004 מדרון או חריץ \u0003חוץ לגומא ושוחט, ודם שותת ויורד לגומא. ובשוק לא יעשה כן, משום שנאמר: \"ובחוקותיהם לא תלכו\"\u0004 (ויקרא יח, ג), \u0003ואם עשה כן\u0004 — \u0003צריך בדיקה אחריו,\u0004 שמא מין הוא.","\u0003השוחט\u0004 בהמת חולין ואומר שהוא שוחט אותה \u0003לשם עולה,\u0004 או \u0003לשם זבחים\u0004 (שלמים), או \u0003לשם אשם תלוי,\u0004 או \u0003לשם פסח, לשם תודה\u0004 — בכל אלה \u0003שחיטתו פסולה,\u0004 מפני שנראה כמקדיש ושוחט קדשים בחוץ, \u0003ור' שמעון מכשיר.\u0004","היו \u0003שנים אוחזין בסכין ושוחטין, אחד\u0004 מהם \u0003לשום\u0004 (לשם) \u0003אחד מכל אלו\u0004 הדברים הפוסלים, \u0003ואחד לשום דבר כשר\u0004 — \u0003שחיטתו פסולה.\u0004 \u0003השוחט\u0004 בהמת חולין \u0003לשם חטאת,\u0004 או \u0003לשם אשם ודאי,\u0004 או \u0003לשם בכור,\u0004 או \u0003לשם מעשר\u0004 בהמה, או \u0003לשם תמורה\u0004 שהם קרבים חובה, ואין חשש שהקדישם סתם — \u0003שחיטתו כשרה.\u0004","\u0003זה הכלל: כל דבר שנידר ונידב\u0004 (שאפשר להקדיש אותו על ידי נדר או בנדבה) — \u0003השוחט לשמו אסור,\u0004 שנראה הדבר כמקדישו ושוחטו בחוץ, \u0003ושאינו נידר ונידב\u0004 אלא הוא מוטל עליו כחובה, אם אין לו חובה כזו — הרי \u0003השוחט לשמו כשר.\u0004","שנינו במשנה: \u0003השוחט לשם עולה\u0004 וכו' לשם אשם תלוי, לשם פסח — שחיטתו פסולה, מפני שהם באים בנדר או נדבה. ותוהים: \u0003אשם תלוי\u0004 האם \u0003בר נידר ונידב הוא?\u0004 הלא קרבן חובה הוא, במקום שיש ספק האם הוא חייב חטאת! \u0003אמר ר' יוחנן: הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003רבי אליעזר היא,\u0004 ש\u0003אמר: מתנדב אדם אשם תלוי בכל יום,\u0004 מחשש שמא עבר עבירה. ועוד תוהים: וכי קרבן","\u0003פסח בר נידב ונידר הוא?\u0004 הלוא \u0003זמנא קביעא ליה\u0004 \u0005[זמן קבוע לו]\u0006 בערב הפסח, ואין אדם יכול להביא קרבן פסח אלא בזמנו! \u0003אמר ר' אושעיא: שאני\u0004 \u0005[שונה]\u0006 \u0003פסח, הואיל והפרשתו\u0004 יכולה להיות \u0003כל השנה כולה.\u0004","\u0003אמר ר' ינאי: לא שנו\u0004 שהשוחט לשם קרבן שחיטתו פסולה \u0003אלא\u0004 כששוחט \u0003תמימים, אבל\u0004 אם שוחט \u0003בעלי מומין\u0004 — \u0003מידע ידיע\u0004 \u0005[ידוע הדבר]\u0006 שהוא בעל מום, ובוודאי אין חשש שלשם קרבן התכוון. \u0003ור' יוחנן אמר: אפילו בעלי מומין נמי\u0004 \u0005[גם כן],\u0006 \u0003זימנין דרמי ליה מידי אמומא ולא ידיע\u0004 \u0005[פעמים שמוטל דבר מה על המום,\u0006 ומכסה אותו, \u0005ואינו ידוע\u0006 לכל\u0005],\u0006 וסבורים שבהמה תמימה היא.","עוד שנינו: \u0003השוחט לשם חטאת\u0004 וכו' שחיטתו כשרה, שאין אדם יכול לנדור חטאת, ואין לחשוש למראית עין. \u0003אמר ר' יוחנן: לא שנו\u0004 שבכגון זה שחיטתו כשרה \u0003אלא\u0004 במי \u0003שאינו מחוייב חטאת, אבל\u0004 מי שידוע שהוא \u0003מחוייב חטאת\u0004 — שחיטתו פסולה, \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003לשום\u0004 (לשם) \u0003חטאתו הוא עושה,\u0004 מקדיש ושוחט בחוץ. ותוהים: \u0003והא\u0004 \u0005[והרי]\u0006 במשנה \u0003לא קאמר\u0004 \u0005[אינו אומר]\u0006 \u0003\"לשם חטאתי\",\u0004 אלא \"לשם חטאת\" סתם, ובזה אין לחשוש! \u0003אמר ר' אבהו:\u0004 ר' יוחנן מדבר \u0003ב\u0004מי ש\u0003אומר \"לשם חטאתי\".\u0004","עוד שנינו במשנה שהשוחט \u0003לשם תמורה\u0004 שחיטתו כשרה. \u0003אמר ר' אלעזר: לא שנו\u0004 ששחיטתו כשרה \u0003אלא\u0004 באופן \u0003שאין לו\u0004 כבר \u0003זבח\u0004 מוקדש \u0003בתוך ביתו, אבל יש לו זבח בתוך ביתו\u0004 — שחיטתו פסולה, \u0003אימא אמורי אמיר ביה\u0004 \u0005[אמור שהוא ממיר בו].\u0006 \u0005ומקשים:\u0006 \u0003והא לא קאמר\u0004 \u0005[והרי\u0006 במשנה \u0005אינו אומר]\u0006 \u0003\"לשם תמורת זבחי\",\u0004 אלא \"לשם תמורה\"! \u0003אמר ר' אבהו:\u0004 ר' אלעזר עוסק \u0003ב\u0004מי ש\u0003אומר\u0004 במפורש \u0003\"לשם תמורת זבחי\".\u0004","שנינו במשנה \u0003זה הכלל:\u0004 כל דבר שנידר ונידב השוחט לשמו אסור. ושואלים: \u0003לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]\u0006 הובא הכלל? שהרי לכאורה מנינו הכל! ומשיבים: \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003עולת נזיר, דמהו דתימא\u0004 \u0005[שמהו שתאמר]:\u0006 אין לחשוש כאן, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא נדר\u0004 קודם לכן נזירות, ואם כן אינו חייב בעולה כזו! לכן אומרת המשנה שיש לחשוש, \u0003אימר\u0004 שמא \u0003נדר בצינעא\u0004 בחשאי, ולא ידוע שנדר בנזיר.","\u0003ו\u0004מה ששנינו ב\"זה הכלל\": כל \u0003שאינו נידר ונידב\u0004 השוחט לשמו כשר — בא \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003עולת יולדת,\u0004 שהשוחט לשם עולת יולדת שחיטתו כשרה, והואיל וקרבן זה הוא קרבן חובה, ואינו נידר או נידב.","\u0003אמר ר' אלעזר: לא שנו אלא שאין לו אשה,\u0004 ולכן ברור שהוא אינו חייב בכך, ואין מקום לטעות, \u0003אבל יש לו אשה\u0004 — שחיטתו פסולה, \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003לשמה הוא עושה.\u0004 ושואלים: \u0003והא לא קאמר\u0004 \u0005[והרי אינו אומר]\u0006 \u0003\"לשם עולת אשתי\"! אמר ר' אבהו:\u0004 ר' אלעזר עוסק \u0003ב\u0004מי ש\u0003אומר\u0004 במפורש \u0003\"לשם עולת אשתי\".\u0004","ומקשים: במקרה זה, \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שיש לחשוש שהוא עושה לשם עולת אשתו!"],["\u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003אם איתא דילדה\u0004 — \u0003קלא הוה ליה\u0004 \u0005[אם יש,\u0006 אם אמנם \u0005ילדה — קול היה לה]\u0006 והיו יודעים על כך, ואם כן אין לחשוש שהוא נודר לשם קרבן, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ר' אלעזר שיש לחשוש לכך, שכן \u0003אימר אפולי אפיל\u0004 \u0005[אמור שהפילה]\u0006 ולכן לא היה לדבר קול.","","\u0003אלו\u0004 הן ה\u0003טרפות בבהמה\u0004 האוסרות אותה באכילה גם אם נשחטה כראוי: \u0003נקובת הוושט,\u0004 שיש נקב מפולש בדופן הוושט, \u0003ופסוקת הגרגרת,\u0004 שנחתכה הגרגרת (הקנה), \u0003ניקב קרום של מוח, ניקב הלב\u0004 והגיע הנקב עד \u0003לבית חללו\u0004 לחלל הלב, \u0003נשברה\u0004 עמוד \u0003השדרה ונפסק\u0004 (נחתך) \u0003החוט שלה\u0004 העובר בתוכה, \u0003ניטל הכבד ולא נשתייר הימנו\u0004 (ממנו) \u0003כלום,\u0004","\u0003הריאה שניקבה או שחסרה, ר' שמעון אומר:\u0004 אינה טריפה \u0003עד שתינקב לבית\u0004 (מקום) \u0003הסמפונות,\u0004 לסמפון הגדול הנכנס לריאה. \u0003ניקבה הקבה,\u0004 או \u0003ניקבה המרה,\u0004 או \u0003ניקבו הדקין\u0004 (המעיים), וכן \u0003הכרס הפנימית שניקבה, או שנקרע רוב\u0004 הכרס \u0003החיצונה. ר' יהודה אומר:\u0004 בבהמה \u0003הגדולה\u0004 אם נקרעה הכרס החיצונה בשיעור \u0003טפח\u0004 הרי זו טריפה, \u0003ו\u0004בבהמה \u0003הקטנה\u0004 הרי זה \u0003ברובה. המסס ובית הכוסות,\u0004 שתים מקיבות הבהמה המחוברות זו לזו, \u0003שניקבו לחוץ\u0004 לחלל הבטן, ולא שניקבו זה לזה.","וכן בהמה ש\u0003נפלה מן הגג,\u0004 וכן בהמה ש\u0003נשתברו רוב צלעותיה,\u0004 \u0003ודרוסת הזאב,\u0004 שזאב נעץ בה את ציפורניו. \u0003ר' יהודה אומר: דרוסת הזאב\u0004 היא טריפה רק \u0003ב\u0004בהמה \u0003דקה,\u0004 כגון כבשים ועיזים, ולא בבהמה גסה, כגון פרה, \u0003ודרוסת ארי\u0004 היא טריפה גם \u0003בגסה, דרוסת הנץ\u0004 היא \u0003בעוף הדק\u0004 (בעופות קטנים), \u0003ודרוסת הגס,\u0004 שהוא כעין נץ אבל גדול יותר — \u0003בעוף הגס\u0004 (הגדול). \u0003זה הכלל\u0004 לגבי כל הלכות טריפות: \u0003כל\u0004 שנחבלה באופן \u0003שאין כמוה חיה\u0004 כלומר, שאינה יכולה לחיות כך למשך זמן — הרי זו \u0003טרפה\u0004 שאסרה התורה באכילה. \u0003אמר ר' שמעון בן לקיש: רמז לטרפה מן התורה מנין?\u0004 ותמהים: \u0003מנין?!\u0004 מה צורך לחפש רמז לדבר? והרי נאמר במפורש: \u0003\"ובשר בשדה טרפה לא תאכלו\"\u0004 (שמות כב, ל)! \u0003אלא רמז לטרפה שאינה חיה מן התורה מנין?\u0004 שהרי ממה \u0003דקתני סיפא\u0004 \u0005[שהוא שונה בסוף\u0006 המשנה\u0005],\u0006 \u0003זה הכלל: כל שאין כמוה חיה\u0004 — \u0003טרפה, מכלל\u0004 הדברים אתה למד ש\u0003טרפה אינה חיה,\u0004 \u0003ומנא לן\u0004 \u0005[ו\u0006אם כן \u0005מנין לנו]\u0006 ראיה לדבר זה מן התורה?","","\u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וזאת החיה אשר תאכלו\u0004 מכל הבהמה אשר על הארץ\" (ויקרא יא, ב), לומר: בהמה שהיא \u0003חיה\u0004 כלומר, זו שיש בה חיים — \u0003אכול,\u0004 זו \u0003שאינה חיה,\u0004 שאין סופה לחיות — \u0003לא תיכול\u0004 \u0005[אל תאכל],\u0006 \u0003מכלל\u0004 הדברים אתה למד ש\u0003טרפה לא חיה.\u0004","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 ש\u0003טרפה\u0004 שאסרה התורה \u0003חיה\u0004 כלומר, ייתכן שתחיה, והוא חולק על הכלל שבמשנתנו, \u0003מנא ליה\u0004 \u0005[מנין לו],\u0006 כיצד הוא לומד מן הכתוב? ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו הדבר]\u0006 גם כן \u0003מ\u0004מה שנאמר \u0003\"זאת החיה אשר תאכלו\u0004 מכל הבהמה\", ולשיטתו המלה \"זאת\" באה למעט: \u0003זאת החיה אכול,\u0004 אבל \u0003חיה אחרת,\u0004 שהיא טריפה — \u0003לא תיכול, מכלל\u0004 הדברים אתה למד ש\u0003טרפה חיה.\u0004","ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 האומר שטריפה אינה חיה\u0005]\u0006 \u0003האי\u0004 \u0005[אותה\u0006 מילה\u0005]\u0006 \u0003\"זאת\" מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בה]?\u0006 ומשיבים: \u0003מיבעי ליה לכדתנא דבי\u0004 \u0005[נצרך לו לכמו ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל, דתנא דבי\u0004 \u0005[ששנה בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 הנאמר בכתוב \u0003\"זאת החיה אשר תאכלו\" מלמד שתפס הקדוש ברוך הוא מכל מין ומין\u0004 מבעלי החיים \u0003והראה לו למשה, ואמר לו: זאת אכול וזאת לא תיכול,\u0004 ולכן נאמר \"זאת\", שהראה לו חיות אלה ואחרות בפועל.","ושואלים: \u0003ואידך נמי\u0004 \u0005[והאחר גם כן]\u0006 \u0003מבעי ליה\u0004 \u0005[נצרך לו\u0006 הכתוב\u0005]\u0006 \u0003לכדתנא דבי\u0004 \u0005[לכמו ששנה החכם מבית מדרשו]\u0006 של \u0003ר' ישמעאל!\u0004 ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כך הוא גם כן],\u0006 ומשם הוא לומד את הדברים. ושואלים: \u0003אלא\u0004 הדין \u0003ש\u0004\u0003טרפה חיה מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה מאידך תנא דבי\u0004 \u0005[יוצאת לו מ\u0006דברי \u0005תנא אחר מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל, דתנא דבי\u0004 \u0005[ששנה החכם מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 נאמר \"להבדיל... \u0003בין החיה הנאכלת ובין החיה אשר לא תאכל\"\u0004 (ויקרא יא, טז), \"החיה\" \u0003אלו שמונה עשרה טרפות שנאמרו למשה מסיני,\u0004 שלמרות שהן חיות אסורות הן באכילה, והן המנויות במשנתנו.","ותוהים: \u0003ותו ליכא\u0004 \u0005[ועוד אין]\u0006 טריפות אחרות? \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 טריפות נוספות ששנו חכמים במשנה ובברייתא, שסימנן \u0003בסג\"ר, ו\u0004כן \u0003שב שמעתתא\u0004 \u0005[שבע שמועות]\u0006 שמדברי האמוראים בענין הטריפות!"],["\u0003בשלמא לתנא דידן\u0004 \u0005[נניח ל\u0006שיטת \u0005התנא שלנו],\u0006 יש לומר \u0003דתנא\u0004 — \u0003תנא\u0004 \u0005[\u0006שהטריפות \u0005ששנה\u0006 במשנתנו — \u0005שנה],\u0006 \u0003ודשייר\u0004 \u0005[ו\u0006כל טריפה \u0005ששייר]\u0006 ולא שנה במשנה — \u0003אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 \u0003ב\"זה הכלל:\u0004 כל שאין כמוה חיה טרפה\". \u0003אלא ל\u0004שיטת ה\u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו של\u0005]\u0006 \u0003ר' ישמעאל\u0004 ש\u0003אמר שמונה עשרה טרפות\u0004 בלבד, יש לתמוה: \u0003ותו ליכא\u0004 \u0005[ועוד\u0006 טרפות \u0005אין]?\u0006 \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 ארבע טרפות ששנינו במקומות אחרים, וסימנן בסג\"ר, והראשונה — מה ששנינו במשנה להלן: \u0003בהמה שנחתכו רגליה מן הארכובה\u0004 (פרק הרגל) \u0003ולמעלה\u0004 — הרי היא \u0003טרפה!\u0004 ודוחים: \u0003סבר ליה\u0004 \u0005[סבור הוא]\u0006 תנא דבי ר' ישמעאל, \u0003כ\u0004דעת \u0003ר' שמעון בן אלעזר,\u0004 ש\u0003אמר: יכולה היא ליכוות ולחיות,\u0004 שעל ידי כוייה אפשר לסתום את שתיתת הדם, ולכן אינו מונה אותה כטריפה.","ומקשים: ו\u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003יכולה ליכוות ולחיות\u0004 אין זה אומר שאינה טריפה, שכן \u0003למאן קאמר\u0004 \u0005[ל\u0006דעת \u0005מי הוא אומר,\u0006 מקשה\u0005]\u0006 — \u0003ל\u0004דעת \u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו של\u0005]\u0006 \u0003רבי ישמעאל,\u0004 והלוא \u0003תנא דבי ר' ישמעאל טרפה חיה סבירא ליה\u0004 \u0005[הוא סבור],\u0006 ואין זה מוציא אותה מכלל טריפה! \u0003אלא\u0004 כך הכוונה: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004דעת \u0003ר' שמעון בן אלעזר,\u0004 ש\u0003אמר: כשרה היא,\u0004 ואינה טריפה, אבל לא מטעמו. ועוד מקשים:","\u0003והאיכא\u0004 \u0005[והרי יש]\u0006 סוג טריפה נוסף, \u0003חסרון בשדרה\u0004 שלא שנינו במשנתנו, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 בענין טומאת המת: \u0003כמה חסרון\u0004 יהיה \u0003בשדרה\u0004 של אדם מת, כדי שלא תטמא בטומאת אוהל כמת שלם? \u0003בית שמאי אומרים:\u0004 אם היא חסרה \u0003שתי חוליות, ובית הלל אומרים:\u0004 אם חסרה \u0003חוליא אחת; ואמר רב יהודה אמר שמואל:\u0004 כשם שחלקו לענין טומאת מת \u0003כן\u0004 נחלקו גם \u0003ל\u0004גבי \u0003טרפה,\u0004 שלדעת בית הלל אם חסרה חוליא אחת הריהי טריפה!","ומשיבים: \u0003המסס ובית הכוסות\u0004 שניקבו לחוץ, \u0003דקא חשבת להו בתרתי\u0004 \u0005[שאתה מחשב אותם בתור שתים,\u0006 שתי טריפות שונות\u0005],\u0006 במנין שמונה עשרה הטריפות שבמשנה — \u0003חשבינהו בחדא\u0004 \u0005[חשב אותם ל\u0006טריפה \u0005אחת],\u0006 שסמוכים הם ומחוברים זה לזה, ואם כן \u0003אפיק חדא ועייל חדא\u0004 \u0005[הוצא אחת מן המנין והכנס אחת],\u0006 את החסרון בשדרה.","ומקשים עוד: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003גלודה,\u0004 זו שנתקלף כל עורה מעליה, ששנינו להלן שהיא טריפה! ומשיבים: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 תנא דבי ר' ישמעאל \u0003כ\u0004דעת \u0003ר' מאיר\u0004 ש\u0003מכשיר\u0004 את הגלודה.","ומקשים עוד: \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 \u0003חרותא,\u0004 שנתקשתה הריאה שלה כעץ, ששנינו להלן שהיא טריפה! ומשיבים: ניקבה ה\u0003מרה,\u0004 ששנינו במשנתנו שהיא טריפה, \u0003מאן קתני לה\u0004 \u0005[מיהו זה ששונה אותה]?\u0006 \u0003ר' יוסי בר' יהודה\u0004 הוא; לשיטת תנא דבי ר' ישמעאל, שבשיטתו אנו עוסקים, \u0003אפיק\u0004 \u0005[הוצא]\u0006 \u0003מרה\u0004 שניקבה מן המנין, שדעת יחיד היא, \u0003ועייל\u0004 \u0005[והכנס]\u0006 את ה\u0003חרותא.\u0004","ומקשים עוד: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 עוד \u0003שב שמעתתא\u0004 \u0005[שבע שמועות]\u0006 של אמוראים בענין טריפות שלא נמנו במשנה! ומפרטים: האחת — ש\u0003אמר רב מתנא: האי בוקא דאטמא דשף מדוכתיה\u0004 \u0005[אותו ראש ירך שיצא\u0006 לגמרי \u0005ממקומו]\u0006 בשקע שבעצם האליה — הריהו \u0003טרפה. ו\u0004השניה — ש\u0003אמר\u0004 החכם \u0003רכיש בר פפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: לקתה\u0004 (חלתה) הבהמה אפילו \u0003בכוליא\u0004 (כליה) \u0003אחת\u0004 — \u0003טרפה. ו\u0004השלישית — \u0003תנן\u0004 \u0005[\u0006מה ש\u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ניטל הטחול\u0004 — \u0003כשרה, ו\u0004על כך \u0003אמר רב עוירא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: לא שנו אלא ניטל, אבל\u0004 אם \u0003ניקב\u0004 הטחול — הריהי \u0003טרפה. ו\u0004הרביעית — מה ש","\u0003אמר רבה בר בר חנה אמר שמואל: סימנים\u0004 (קנה וושט) \u0003שנדלדלו,\u0004 נעקרו מחיבורם \u0003ברובן\u0004 — הרי זו \u0003טרפה. ו\u0004החמישית — מה ש\u0003אמר רבה בר רב שילא אמר רב מתנא אמר שמואל:\u0004 אם \u0003נעקרה צלע מעיקרה,\u0004 עם חצי החוליה שהיא יוצאת ממנה — הרי הבהמה \u0003טרפה. ו\u0004השישית — עצם ה\u0003גולגולת שנחבסה\u0004 (נמחצה) \u0003ברובה,\u0004 למרות שלא נחסרה הגולגולת ולא ניקבו קרומי המוח — הרי הבהמה טריפה. \u0003ו\u0004השביעית — \u0003בשר החופה\u0004 (המכסה) \u0003את רוב הכרס,\u0004 שאם נחתך \u0003ברובו\u0004 — הרי הבהמה \u0003טרפה!\u0004","ומשיבים: הלוא הטריפות שעל ידי \u0003נקובי\u0004 \u0005[\u0006איברים \u0005נקובים]\u0006 ששנינו במשנתנו \u0003תמניא הוו\u0004 \u0005[שמונה הם],\u0006 \u0003חשבינהו בחד\u0004 \u0005[חשב אותם כאחד],\u0006 וכך \u0003אפיק שב\u0004\u0005[הוצא שבע]\u0006 טריפות מן המנין שבמשנה \u0003ועייל שב\u0004\u0005[והכנס שבע]\u0006 אחרות שמנינו פה. ומקשים: \u0003אי\u0004","\u0003הכי\u0004 \u0005[אם כך]\u0006 אתה מונה, \u0003פסוקי נמי תרי הוו\u0004 \u0005[\u0006אותם המקרים ש\u0005נפסק,\u0006 נחתך אבר \u0005גם כן שנים הם]\u0006 במשנה, נפסקה הגרגרת ונפסק חוט השדרה, ולפי דרך זו \u0003חשבינהו בחד\u0004 \u0005[חשוב\u0006 גם \u0005אותם כאחד],\u0006 ונמצא ש\u0003בצר להו חדא\u0004 \u0005[חסרות\u0006 הטריפות \u0005אחת]\u0006 כדי להשלים לשמונה עשרה! \u0003ועוד\u0004 יש להקשות: אם אתה מונה את כל הנקובים כטריפה אחת, זו שמנה \u0003רב עוירא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא,\u0004 שניקב הטחול, \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003נקובה היא,\u0004 ואם כן צריך היה למנות אותה יחד עם הנקובים, ונמצא שחסרות שתים למנין הטריפות!"],["\u0003אלא\u0004 אם מפרשים בדרך זו צריך לומר ש\u0003הנך תרתי דאפקת\u0004 \u0005[אותן שתי\u0006 טריפות \u0005שהוצאת]\u0006 בתחילה, בהמה שנחתכו רגליה וגלודה, \u0003לא תיפוק\u0004 \u0005[אל תוציא],\u0006 ואז יהיה שוב החשבון מדוייק.","\u0003אמר עולא, שמונה מיני טרפות נאמרו לו למשה בסיני\u0004 וכל הטריפות שמנו חכמים במשנתנו ובשאר מקומות כלולות בשמונה אלה: \u0003נקובה, ופסוקה\u0004 (חתוכה), \u0003נטולה,\u0004 שאיבר מסויים ניטל ממנה, \u0003וחסורה\u0004 חלק מאיבר, \u0003קרועה, ודרוסה\u0004 על ידי חיה, \u0003נפולה\u0004 ממקום גבוה, \u0003ושבורה.\u0004 וכלל זה של עולא בא \u0003לאפוקי לקותא\u0004 \u0005[להוציא מהליקוי]\u0006 שאמר \u0003רכיש בר פפא\u0004 בכליה (לעיל מב,ב), שלדעת עולא אינו בכלל אותן טריפות.","\u0003אמר חייא בר רבא, שמונה טרפות יש בנקובה:\u0004 הוושט, קרום של מח, הלב, הריאה, הקיבה, הדקין, הכרס הפנימית, וכן המסס ובית הכוסות שניקבו לחוץ; \u0003אם תאמר: תשע\u0004 יש, שהרי שנינו במשנתנו גם מרה שניקבה — על כך יש להשיב כי \u0003מרה ר' יוסי ברבי יהודה קתני לה\u0004 \u0005[שונה אותה],\u0006 ודעת יחיד היא, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003ניקבה הקיבה\u0004 או \u0003ניקבו הדקים\u0004 — הרי זו \u0003טרפה, ר' יוסי בר' יהודה אומר: אף ניקבה המרה.\u0004","\u0003(הלכות חבר כזית מרה וקורקבן\u0004 — \u0003סימן\u0004 לדברים שאמר ר' יצחק בר יוסף בשם ר' יוחנן) ובניגוד לדברי חייא בר רבא,","\u0003אמר ר' יצחק בר' יוסף אמר ר' יוחנן: הלכה כר' יוסי בר' יהודה,\u0004 שאם ניקבה המרה — טריפה.","\u0003ואמר ר' יצחק בר' יוסף אמר ר' יוחנן: מאי אהדרו ליה חבריה\u0004 \u0005[מה השיבו לו חביריו]\u0006 \u0003לר' יוסי בר' יהודה\u0004 כנגד שיטתו? — אמרו לו: הרי איוב אומר \u0003\"ישפוך לארץ מררתי\"\u0004 (איוב טז, יג) \u0003ועדיין איוב קיים,\u0004 משמע שנקב במרה אינו ממית! \u0003אמר להם\u0004 ר' יוסי: אצל איוב נס היה זה, שהתקיים למרות חולייו, \u0003ו\u0004\u0003אין מזכירין מעשה נסים,\u0004 להביא מהם ראיה. \u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך],\u0006 מה שאמר: \u0003\"יפלח כליותי ולא יחמול\"\u0004 (שם), \u0003מי קא חיי\u0004 \u0005[האם יכול לחיות]\u0006 אדם שכלייתו מבוקעת? \u0003אלא ניסא שאני\u0004 \u0005[נס שונה],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 שאמר ה' לשטן: \u0003\"רק את נפשו שמור\"\u0004 (שם ב, ו), ומכאן שבאופן טבעי צריך היה למות, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 ביחס למרה יש לומר כי \u0003ניסא שאני\u0004 \u0005[\u0006\u0005נס שונה],\u0006 ואין ללמוד משם.","\u0003ו\u0004עוד \u0003אמר ר' יצחק בר' יוסף אמר ר' יוחנן\u0004 בדיני טריפות: \u0003הלכה כדברי האומר\u0004 בכבד שניטל, שאם נשתייר בו \u0003כזית\u0004 — כשרה.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0005רבה בר בר חנה אמר ר' יוחנן:\u0006 \u0003הלכה כסתם משנה\u0004 בכל מקום, \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנתנו\u0005]:\u0006 \u0003ניטלה הכבד ולא נשתייר הימנה\u0004 (ממנה) \u0003כלום\u0004 טריפה היא, ומכאן נדייק: \u0003הא\u0004 \u0005[אבל]\u0006 אם \u0003נשתייר\u0004 משהו — \u0003כשרה, אף על גב דלא הוי\u0004 \u0005[אף על פי שאיננו]\u0006 בשיעור \u0003כזית!\u0004 ומשיבים: \u0003אמוראי נינהו ואליבא\u0004 \u0005[\u0006מחלוקת \u0005אמוראים היא ו\u0006שניהם \u0005לפי שיטתו]\u0006 של \u0003ר' יוחנן,\u0004 האם תמיד הלכה כסתם משנה.","עוד מביאים מה ש\u0003אמר ר' יצחק בר' יוסף אמר ר' יוחנן: מרה שניקבה,\u0004 שהיא טריפה (לשיטתו), אם היה הנקב במקום בו היא מחוברת לכבד, \u0003ו\u0004היה ה\u0003כבד סותמתה\u0004 — \u0003כשרה.\u0004","\u0003ואמר ר' יצחק בר' יוסף אמר ר' יוחנן:\u0004 ביחס למה ששנינו להלן (נו,א) שאם ניקב קורקבן של עוף הריהו טריפה, אם \u0003ניקב\u0004 בשר \u0003הקורקבן\u0004 של עוף, \u0003ו\u0004ה\u0003כיס,\u0004 העור הפנימי \u0003שלו קיים\u0004 — \u0003כשר.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 אם \u0003ניקב הכיס\u0004 הפנימי של הקורקבן, \u0003ו\u0004בשר ה\u0003קורקבן קיים, מאי\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006 ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ש\u0003אמר רב נחמן\u0004 בענין הוושט, שיש לו שני עורות (שכבות), פנימי וחיצוני, שרק אם ניקבו שניהם הריהי טריפה, אבל אם \u0003ניקב זה בלא זה\u0004 — הרי זה \u0003כשר.\u0004 וכן \u0003אמר רבא: שני עורות יש לו לוושט, חיצון\u0004 שצבעו \u0003אדום, ופנימי לבן,\u0004 אם \u0003ניקב זה בלא זה\u0004 — \u0003כשר.\u0004 ושואלים: \u0003למה לי\u0004 לפרש ו\u0003למימר\u0004 \u0005[לומר]\u0006 שה\u0003חיצון אדום ופנימי לבן?\u0004 הרי רואים אנו שכך הוא! ומשיבים: לומר \u0003דאי חליף\u0004 \u0005[שאם נתחלף],\u0006 ונעשה החיצון","לבן והפנימי אדום — הרי הוא \u0003טרפה. אבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 אם \u0003ניקבו שניהם,\u0004 החיצון והפנימי, אבל הנקבים היו \u0003זה שלא כנגד זה, מהו\u0004 הדין? \u0003אמר מר זוטרא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב פפא:\u0004 אם היה זה \u0003בוושט\u0004 — \u0003כשר, בקורקבן\u0004 — \u0003פסול. מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי: אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005]\u0006 היה צריך רב פפא לומר, \u0003וושט דאכלה ביה ופעיא ביה רווח\u0004 \u0005[שהיא אוכלת בו וצועקת בו,\u0006 והוא \u0005מרווח,\u0006 גמיש\u0005],\u0006 הריהי \u0003גמדא ליה ופשטה ליה\u0004 \u0005[מכווצת אותו ופושטת אותו],\u0006 שכיון ששני העורות אינם דבוקים, אלא מחוברים בצורה רופפת, הרי גם אם אין הנקבים מכוונים זה כנגד זה, \u0003זמנין דמיהנדזין בהדי הדדי\u0004 \u0005[פעמים ש\u0006הם \u0005מזדמנים בשווה זה כנגד זה],\u0006 והרי זה כנקב מפולש. אבל \u0003קורקבן דמינח נייח\u0004 \u0005[ש\u0006הוא \u0005נח במקומו],\u0006 \u0003כדקאי קאי\u0004 \u0005[כמו שהוא עומד הוא עומד],\u0006 ואין חשש שיזדמנו זה כנגד זה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף לרב אשי: הכי אמרינן משמיה\u0004 \u0005[כך אומרים אנו משמו]\u0006 של \u0003מר זוטרא\u0004 ש\u0003אמר משמיה\u0004 \u0005[שאמר משמו]\u0006 של \u0003רב פפא\u0004 בעל שמועה זו \u0003כוותיך\u0004 \u0005[כשיטתך],\u0006 ולא כמו שנאמר לך בשמו.","\u0003ואמר רבה: קרום שעלה מחמת מכה בוושט,\u0004 כלומר, אם היה נקב בוושט, שעושה אותו טריפה, ונסתם על ידי קרום של גלד — \u0003אינו\u0004 נחשב כ\u0003קרום,\u0004 להוציאו מכלל טריפה. \u0003ואמר רבה: וושט אין לו בדיקה מבחוץ\u0004 לברר אם הבהמה טריפה, משום שהעור החיצון הוא אדום ואין אדמומית הנובעת מפגיעה ניכרת בו, \u0003אלא\u0004 בדיקתו היא רק \u0003בפנים,\u0004 שהעור שם לבן. \u0003למאי נפקא מינה\u0004 \u0005[למה,\u0006 לאיזה מקרה \u0005יוצא מכאן]\u0006 לפסיקת ההלכה?"],["\u0003ל\u0004ענין \u0003ספק דרוסה\u0004 על ידי צפורני חיה טורפת, שצריך לבדוק אם הוושט האדים מחמת הדריסה, שבודקים דווקא מן הצד הפנימי שהוא לבן. מסופר,","\u0003ההיא\u0004 \u0005[אותה]\u0006 \u0003ספק דרוסה דאתאי לקמיה\u0004 \u0005[שבאה לפני]\u0006 \u0003רבה, הוה קא בדיק ליה\u0004 \u0005[היה בודק אותו]\u0006 \u0003רבה לוושט מאבראי\u0004 \u0005[מבחוץ].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והא מר הוא דאמר\u0004 \u0005[והרי אדוני\u0006 עצמו \u0005הוא שאמר]:\u0006 \u0003וושט אין לו בדיקה אלא מבפנים! אפכיה\u0004 \u0005[הפך אותו]\u0006 \u0003רבה\u0004 את הוושט \u0003ובדקיה\u0004 \u0005[ובדק אותו]\u0006 מצידו הפנימי, \u0003ואישתכח עליה תרי קורטי דמא\u0004 \u0005[ונמצאו עליו שתי טיפות דם],\u0006 \u0003וטרפה\u0004 \u0005[והטריף אותה]\u0006 כדין דרוסה. ומעירים: \u0003ורבה נמי לחדודי לאביי הוא דבעי\u0004 \u0005[גם כן לחדד את אביי הוא שרצה],\u0006 לעורר אותו לשאול, ולא משום ששכח או טעה.","\u0003אמר עולא:\u0004 אם \u0003ישב\u0004 (נתחב) \u0003לו,\u0004 לבעל חיים \u0003קוץ בוושט\u0004 מצידו הפנימי, ואין רואים סימן של נקב בעור החיצון — \u0003אין חוששין שמא\u0004 ניקב עד לחוץ ו\u0003הבריא,\u0004 ובאמת טריפה היא, כמבואר לעיל, שקרום שעלה מחמת מכה אינו קרום. אלא מניחים שניקב רק העור הפנימי, והוא כשר.","(\u0003דרס חתיכות בסכין טמאה, סימן\u0004 לשאלות הבאות על עולא).","ושואלים: \u0003ולעולא\u0004 הרי ספק הוא, ו\u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 הדבר \u0003מספק דרוסה,\u0004 שצריכה בדיקה, וכל עוד לא נבדקה הריהי אסורה באכילה? ומשיבים: \u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003עולא\u0004 ש\u0003אין חוששין לספק דרוסה.\u0004","ושואלים: \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 ספק זה \u0003משתי חתיכות\u0004 שהיו לפני אדם, \u0003אחת של חלב\u0004 (שומן אסור באכילה) \u0003ואחת של שומן\u0004 מותר, ואכל אחת מהן ואינו יודע איזו, שצריך להביא קרבן לכפרה שמא אכל איסור. ומכאן שיש להימנע מלאכול ספק איסור! ומשיבים: \u0003התם איתחזק איסורא\u0004 \u0005[שם הוחזק האיסור],\u0006 ברור לנו שיש שם חתיכה אסורה, אבל כאן לא הוחזק כל איסור.","ושואלים: \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 הדבר \u0003מהשוחט בסכין\u0004 שלא נבדקה לפני השחיטה, \u0003ונמצאת פגומה\u0004 לאחר שחיטה, שהבהמה אסורה, שמא היתה הסכין פגומה בשעת השחיטה? ומשיבים: \u0003התם איתייליד לה ריעותא\u0004 \u0005[שם נולדה ריעות,\u0006 פגם\u0005]\u0006 \u0003בסכין,\u0004 שיש לפנינו פגימה שאם היתה בה מתחילה הריהי טריפה, אבל בקוץ התחוב בוושט — הרי אין לפנינו נקב בצד החיצון. ושואלים:","\u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 דין זה \u0003מספק טומאה ברשות היחיד,\u0004 ש\u0003ספקו טמא?\u0004 ודוחים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 שאתה רוצה להשוות דין זה לספק טומאה, \u0003נידמייה\u0004 \u0005[שידמה אותו]\u0006 \u0003לספק טומאה ברשות הרבים,\u0004 ש\u0003ספקו טהור! אלא התם\u0004 \u0005[שם]\u0006 בענייני ספק טומאה \u0003הלכתא גמירי לה\u0004 \u0005[הלכה\u0006 למשה מסיני \u0005אנו לומדים אותה]\u0006 \u0003מ\u0004דין \u0003סוטה,\u0004 ואין למדים ממנה לדינים אחרים.","מסופר, \u0003יתיב ההוא מרבנן קמיה\u0004 \u0005[ישב אחד החכמים לפני]\u0006 \u0003רב כהנא ויתיב וקאמר\u0004 \u0005[ויושב היה ואומר]:\u0006 אם \u0003נמצאת\u0004 קוץ בוושט אבל אינו נעוץ בו, \u0003אתמר\u0004 \u0005[נאמר]\u0006 שאין חוששים שמא היה שם נקב והבריא, \u0003אבל\u0004 אם \u0003ישב\u0004 הקוץ, שהיה נעוץ בתוך דופן הוושט — \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 שמא היה נקב והבריא, והיא אסורה. \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב כהנא: לא תציתו ליה\u0004 \u0005[אל תקשיבו לו],\u0006 אין זו שמועה נכונה, \u0003ישב\u0004 קוץ בוושט \u0003איתמר\u0004 \u0005[נאמר]\u0006 שאין חוששים, \u0003אבל\u0004 במקרה שרק \u0003נמצאת\u0004 בתוך הוושט \u0003לא איצטריך ליה\u0004 \u0005[לא הוצרך לו]\u0006 \u0003לעולא\u0004 לומר שאין חוששים, \u0003דכולהו חיוי ברייתא קוצי אכלן\u0004 \u0005[שכל החיות שבחוץ קוצים\u0006 הן \u0005אוכלות],\u0006 ויש להן קוצים בוושט ואין חוששין בהן לטריפה.","ועוד בדין הוושט, שאם ניקב אפילו משהו הרי זו טריפה, \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בדין \u0003תורבץ הוושט\u0004 (איזור הכניסה לוושט, מכיוון הלוע), \u0003רב אמר:\u0004 אם ניקב \u0003במשהו\u0004 הרי זו טריפה, \u0003ושמואל אמר:\u0004 אם ניקב \u0003ברובו.\u0004 ומסבירים את השיטות: \u0003רב אמר במשהו,\u0004 כי לדעתו תורבץ הוושט \u0003מקום שחיטה הוא,\u0004 ונחשב כחלק מן הוושט. \u0003ושמואל אמר ברובו,\u0004 כי לדעתו \u0003לאו\u0004 \u0005[לא]\u0006 \u0003מקום שחיטה הוא,\u0004 ואין דינו כוושט. ושואלים:","\u0003הי ניהו\u0004 \u0005[איזה הוא]\u0006 \u0003תורבץ הוושט?\u0004 \u0003אמר מרי בר מר עוקבא אמר שמואל: כל\u0004 אותו חלק \u0003שחותכו ומרחיב,\u0004 שאם כשחותכו לרוחבו, מקום החתך מתרחב ונפתח כלפי חוץ — \u0003זה הוא תורבץ הוושט,\u0004 כל ש\u0003חותכו ועומד במקומו,\u0004 (נשאר כמו שהוא) — \u0003זהו וושט עצמו. אמר להו\u0004 \u0005[להם]\u0006 \u0003רב פפי: מר לא אמר הכי\u0004 \u0005[האדון,\u0006 הרב, \u0005לא אמר כך],\u0006 \u0003ומנו\u0004 \u0005[ומיהו]?\u0006 \u0003רב ביבי בר אביי, אלא\u0004 \u0003כל שחותכו ועומד במקומו\u0004 — \u0003זה תורבץ הוושט,\u0004 ולא הוושט. \u0003אלא איזהו\u0004 ה\u0003וושט עצמו? כל שחותכו וכויץ\u0004 \u0005[ומתכווץ],\u0006 שמקום החתך מתכווץ פנימה ונסגר. ואילו החכם \u0003יונה אמר\u0004 בשם ר' \u0003זירא:\u0004 תורבץ הוושט הוא ה\u0003מבלעתא,\u0004 בית הבליעה, סמוך לפתח הוושט ממש. \u0003וכמה\u0004 הוא סמוך לפתח? \u0003אמר רב אויא: פחות משערתא\u0004 \u0005[מ\u0006אורך \u0005שעורה],\u0006 \u0003ועדיף מחיטתא\u0004 \u0005[ויותר מ\u0006אורך \u0005חיטה].\u0006","מסופר, \u0003ההוא תורא דהוה\u0004 \u0005[אותו שור שהיה]\u0006 \u0003לבני רב עוקבא, דאתחיל ביה\u0004 \u0005[שהתחיל בו]\u0006 \u0003שחיטה\u0004 משהו \u0003בתורבץ הוושט וגמר\u0004 רובו \u0003בוושט,\u0004 ובאו לשאול מה דינו, \u0003אמר רבא: רמינא עליה חומרי\u0004 \u0005[מטיל אני עליו את החומרות]\u0006 של \u0003רב, וחומרי\u0004 \u0005[והחומרות]\u0006 של \u0003שמואל, וטריפנא ליה\u0004 \u0005[ומטריף אני אותו].\u0006 כיצד?","מטיל אני עליו את \u0003חומרי\u0004 \u0005[החומרות]\u0006 של \u0003רב\u0004 — ש\u0003אמר רב:\u0004 תורבץ הוושט נקיבתו אוסרת \u0003במשהו;\u0004 ואם תשאל, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב:\u0004 תורבץ הוושט \u0003מקום שחיטה הוא,\u0004 ואם כן אין זה נקב אלא התחלת שחיטה! על כך אני משיב שלענין זה אני פוסק \u0003כ\u0004דעת \u0003שמואל,\u0004 ש\u0003אמר:\u0004 תורבץ הוושט \u0003לאו\u0004 \u0005[לא]\u0006 \u0003מקום שחיטה הוא.\u0004 ואם תשאל: \u0003אי\u0004 \u0005[אם]\u0006 כדעת \u0003שמואל, האמר\u0004 \u0005[הרי אמר]:\u0006 תורבץ הוושט טריפתו רק \u0003ברובו!\u0004 לענין זה אני פוסק \u0003כרב\u0004 ש\u0003אמר:\u0004 תורבץ הוושט דינו \u0003ב\u0004נקב \u0003משהו.\u0004","מסופר, \u0003איגלגל מילתא מטאי לקמיה\u0004 \u0005[התגלגל הדבר,\u0006 הלכה זו שפסק רבא, \u0005והגיעה לפני]\u0006 \u0003ר' אבא, אמר להו\u0004 \u0005[להם]\u0006 לתלמידיו: \u0003תורא\u0004 \u0005[השור\u0006 עצמו\u0005],\u0006 \u0003בין ל\u0004דעת \u0003רב בין לשמואל שרי\u0004 \u0005[מותר],\u0006 שאם תורבץ הוושט מקום שחיטה הוא, כדעת רב — הרי שחט כראוי. ואם אינו מקום שחיטה, וכדעת שמואל — אינו פוסל אלא ברובו, והרי שחט בו רק מקצת, ורובו שחט במקום הראוי, ושחיטה כשרה היא; \u0003זילו אמרו ליה לבריה\u0004 \u0005[לכו אמרו לו לבנו]\u0006 של \u0003רב יוסף בר חמא,\u0004 רבא, \u0003דלשלים דמי תורא למריה\u0004 \u0005[שישלם את דמי השור לבעליו],\u0006 כי הטריף שלא כדין.","וכן \u0003אמר מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא, מותבינא תיובתא כלפי סנאיה\u0004 \u0005[מקשה אני קושיה כלפי שונאיו]\u0006 של \u0003רבא,\u0004 כלומר, כלפי רבא (בלשון נקיה), ממה ששנינו: \u0003לעולם הלכתא\u0004 \u0005[הלכה היא]\u0006 \u0003כדברי בית הלל, והרוצה לעשות כדברי בית שמאי\u0004 — \u0003עושה,\u0004 הרוצה לעשות \u0003כדברי בית הלל\u0004 — \u0003עושה.\u0004 אבל מי שעושה גם \u0003מקולי בית שמאי ומקולי בית הלל\u0004 — הרי אדם כזה הוא \u0003רשע.\u0004"],["\u0003מחומרי בית שמאי ומחומרי בית הלל\u0004 — \u0003עליו הכתוב אומר: \"הכסיל בחושך הולך\"\u0004 (קהלת ב, יד), \u0003אלא אי\u0004 \u0005[או]\u0006 שעושה \u0003כבית שמאי כקוליהן וכחומריהן, אי\u0004 \u0005[או]\u0006 \u0003כבית הלל כקוליהן וכחומריהן.\u0004 ודנים בברייתא זו.","\u0003הא גופא קשיא\u0004 \u0005[היא עצמה קשה],\u0006 שהרי \u0003אמרת\u0004 \u0005[אומר אתה]\u0006 מתחילה: \u0003לעולם הלכה כדברי בית הלל, והדר תני\u0004 \u0005[וחוזר\u0006 אתה \u0005ושונה]:\u0006 \u0003והרוצה לעשות כדברי בית שמאי\u0004 — \u0003יעשה!\u0004","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003כאן\u0004 שכל אחד רשאי לעשות כפי השיטה שהוא בוחר בה, מדובר \u0003קודם\u0004 שיצאה \u0003בת קול\u0004 ואמרה שהלכה כבית הלל, \u0003כאן לאחר בת קול.\u0004","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור],\u0006 \u0003אף לאחר בת קול\u0004 יכול אדם לבחור את השיטה, \u0003ו\u0004דעת \u0003ר' יהושע היא,\u0004 ש\u0003אמר: אין משגיחין בבת קול.\u0004","ומעירים: \u0003מכל מקום קשיא\u0004 \u0005[קשה]\u0006 על רבא, כיצד נהג כשתי שיטות סותרות במי שהחל שחיטה בתורבץ הוושט וגמר בוושט!","\u0003אמר רב טבות: כולה\u0004 \u0005[את הכל]\u0006 \u0003כ\u0004דעת \u0003רב עבדא\u0004 \u0005[עשה],\u0006 \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רמי בר יחזקאל, אמר: לא תציתו להו להני כללי דכייל\u0004 \u0005[אל תקשיבו לאותם כללים שכלל,\u0006 קבע\u0005]\u0006 \u0003יהודה אחי\u0004 (הוא החכם רב יהודה) \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב!\u0004 שלא אמר רב שנקובתו של תורבץ הוושט היא במשהו מפני שהוא מקום שחיטה, אלא \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב: וושט נתנו חכמים שיעור\u0004 עד היכן ראוי הוא לשחיטה, שלא כולו כשר לשחיטה, ו\u0003מכלל\u0004 הדברים אתה לומד ש\u0003תורבץ הוושט\u0004 בוודאי \u0003לאו\u0004 \u0005[לא]\u0006 \u0003מקום שחיטה הוא. ו\u0004מצד אחר \u0003קאמר\u0004 \u0005[הוא אומר]\u0006 שטריפתו היא \u0003במשהו,\u0004 בלא קשר לשאלה האם מדובר במקום שחיטה.","כיון שנזכר שנתנו חכמים שיעור לוושט לענין שחיטה, שואלים למעשה: \u0003למעלה עד כמה?\u0004 עד היכן אפשר לשחוט בוושט בחלקו העליון? \u0003אמר רב נחמן: עד\u0004 שיישאר למעלה \u0003כדי תפיסת יד,\u0004 שניתן לאחוז בוושט. ועוד שואלים: \u0003למטה עד כמה\u0004 ניתן לשחוט בוושט? \u0003אמר רב נחמן, אמר רבה בר אבוה:\u0004 \u0003עד כדי שישעיר,\u0004 עד פתח הכרס, שיש בדפנותיה כעין שערות. ותוהים:","\u0003איני\u0004 \u0005[כן הוא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבינא אמר\u0004 החכם \u0003גניבא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב:\u0004 ה\u0003טפח\u0004 האחרון \u0003בוושט,\u0004 ה\u0003סמוך לכרס\u0004 — \u0003זהו\u0004 הקרוי \u0003כרס הפנימי.\u0004 ואם כן \u0003אמאי\u0004 \u0005[מדוע]\u0006 אמר רב נחמן שיכול לשחוט ממש עד מקום שיער? והרי לדעת רב, \u0003כי קא שחט\u0004 \u0005[כאשר הוא שוחט]\u0006 בטפח האחרון — \u0003בכרס\u0004 עצמה \u0003קא שחיט\u0004 \u0005[הוא שוחט]!\u0006","ומתקנים, \u0003אימא\u0004 \u0005[אמור]\u0006 כך בדברי רב: אותו \u0003טפח בכרס\u0004 שהוא \u0003סמוך לוושט\u0004 — \u0003זהו כרס הפנימי,\u0004 ואינו מקום שחיטה, אבל הוושט עצמו — כולו מקום שחיטה, וכפי שאמר רב נחמן. \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור],\u0006 \u0003כי קאמר\u0004 \u0005[כאשר אומר]\u0006 \u0003רב\u0004 שטפח בוושט סמוך לכרס נחשב ככרס — הרי זה \u0003בתורא\u0004 \u0005[בשור],\u0006 \u0003דמשעיר טפי\u0004 \u0005[ששעיר יותר],\u0006 והשיער מצוי גם ב\u0003וושט עצמו, בטפח האחרון שלו, ושם דינו ככרס, שאינו מקום שחיטה.\u0004","\u0003אמר רב נחמן אמר שמואל: תורבץ הוושט שניטל כולו מלחי\u0004 (הלסת התחתונה) — \u0003כשר; ותנא תונא\u0004 \u0005[ו\u0006כן \u0005שנה החכם שלנו]\u0006 במשנה להלן: \u0003ניטל לחי התחתון\u0004 כולו — \u0003כשר,\u0004 והרי אם ניטל הלחי התחתון נתלשים עמו הקנה והוושט, שהם מחוברים אליו.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא:\u0004 כיצד אמר שמואל שתורבץ הוושט שניטל כולו — כשר? \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 בכך \u0003עיקור סימנים\u0004 ממקומם, עושה טריפה!","ועל כך מקשים: \u0003ולרב פפא קשיא מתניתין\u0004 \u0005[קשה משנתנו],\u0006 ששנינו שאם \u0003ניטל לחי התחתון\u0004 — \u0003כשר!\u0004","ומשיבים: \u0003בשלמא מתניתין\u0004 \u0005[נניח משנתנו]\u0006 \u0003לרב פפא לא קשיא\u0004 \u0005[אינה קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שעיקור סימנים עושה טריפה, הוא במקרה \u0003דאיעקור איעקורי\u0004 \u0005[שנעקרו הסימנים]\u0006 מבשר הלחי; \u0003הא\u0004 \u0005[זה]\u0006 שניטל לחי התחתון, שהוא כשר — \u0003דאיגום איגומי מעילוי סימנים\u0004 \u0005[ש\u0006הלחי התחתון \u0005נחתך מעל\u0006 מקום חיבור \u0005הסימנים],\u0006 והסימנים עצמם נשארו מחוברים לבשר הלחי. \u0003אלא לשמואל קשיא\u0004 \u0005[קשה],\u0006 כיצד תורבץ הוושט שניטל כולו מן הלחי כשר? והרי יש בכך עיקור סימנים!","ומשיבים: \u0003לא תימא\u0004 \u0005[אל תאמר]\u0006 בדברי שמואל תורבץ הוושט שניטל \u0003כולו\u0004 כשר, \u0003אלא אימא\u0004 \u0005[אמור]\u0006 שניטל \u0003רובו,\u0004 ומקשים:","\u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר בר חנה אמר שמואל: סימנים\u0004 (קנה או וושט) \u0003שנדלדלו ברובן\u0004 — \u0003טרפה,\u0004 ואם כן, אפילו ניטל רובו הריהו טריפה! \u0003אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: הא\u0004 \u0005[זה]\u0006 שאמר שמואל שכשר כשניטל רובו, הוא במקרה \u0003דאקפל איקפולי\u0004 \u0005[שהתקפל, נקלף]\u0006 התורבץ מבשר הלחי, ונשאר המיעוט מחובר במקום אחד, שבאופן כזה יכול המקום להבריא. \u0003התם\u0004 \u0005[שם]\u0006 שאמר שמואל שאם נדלדלו סימנים ברובם טריפה, הוא במקרה \u0003דאפרוק אפרוקי\u0004 \u0005[שהתפרק,\u0006 שהוושט נעקר בכח\u0005],\u0006 והמיעוט שנותר מחובר מעט כאן ומעט כאן, ובכגון זה אין המקום יכול להבריא.","שנינו במשנה: \u0003ופסוקת הגרגרת\u0004 שנחתך הקנה לרוחבו — טריפה. ועל כך \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003כמה פסוקת הגרגרת\u0004 שעושה אותה לטריפה? \u0003ברובה. וכמה רובה?\u0004 איך קובעים מהו רובה? \u0003רב אמר:\u0004"],["\u0003רוב עוביה,\u0004 שמחשיבים גם את עובי הקנה עצמו, \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 בשם רב שהכוונה היא ל\u0003רוב חללה\u0004 בלי הקנה עצמו.","מסופר, \u0003ההיא\u0004 \u0005[אותה]\u0006 \u0003פסוקת הגרגרת דאתאי לקמיה\u0004 \u0005[שבאה,\u0006 הביאוה \u0005לפני]\u0006 \u0003רב\u0004 לדון אם כשרה היא, \u0003יתיב וקא בדיק לה\u0004 \u0005[יושב היה ובודק אותה]\u0006 האם נחתכה הגרגרת \u0003ברוב עוביה.\u0004 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003רב כהנא ורב אסי לרב:\u0004 והלא \u0003לימדתנו רבינו\u0004 שפסוקת הגרגרת נמדדת \u0003ברוב חללה! שדריה לקמיה\u0004 \u0005[שלח אותה לפני]\u0006 \u0003רבה בר בר חנה, בדקה\u0004 \u0005[בדק אותה]\u0006 \u0003ברוב חללה ואכשרה\u0004 \u0005[והכשיר אותה],\u0006 \u0003וזבן מינה בתליסר איסתירי פשיטי בישרא\u0004 \u0005[וקנה ממנה, בשלושה עשר איסרים פשוטים, בשר].\u0006","ושואלים: \u0003והיכי עביד הכי\u0004 \u0005[וכיצד עשה כך]\u0006 רבה בר בר חנה, שהתיר מה שרב היה סבור לאסור? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003חכם שטימא\u0004 — \u0003אין חבירו רשאי לטהר, אסר\u0004 — \u0003אין חבירו רשאי להתיר!\u0004 ומשיבים: \u0003שאני הכא\u0004 \u0005[שונה\u0006 המקרה \u0005כאן]\u0006 ש\u0003רב לא אסר מיסר\u0004 \u0005[לא אסר],\u0006 אלא שקל לאסור, ושלחה לרבה בר בר חנה.","ושואלים מצד אחר: \u0003וכיון דאורי\u0004 \u0005[שהורה]\u0006 \u0003בה חכם,\u0004 שנולד בה ספק והובאה לפניו כדי שיורה בה, \u0003היכי אכל מינה\u0004 \u0005[כיצד אכל ממנה]\u0006 רבה בר בר חנה? \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ואומר אהה ה' אלהים הנה נפשי לא מטומאה ונבלה וטרפה לא אכלתי מנעורי ועד עתה ולא בא בפי בשר פגול\"\u0004 (יחזקאל ד, יד), וכך דרשו חכמים את הפסוק:","\u0003\"הנה נפשי לא מטומאה\"\u0004 — כוונתו \u0003שלא הרהרתי\u0004 הרהורי עבירה \u0003ביום לבא\u0004 על ידם \u0003לידי טומאה\u0004 של קרי \u0003בלילה, \"ונבלה וטרפה לא אכלתי\"\u0004 — \u0003שלא אכלתי בשר \"כוס כוס\"\u0004 (שחוט שחוט) \u0003מעולם,\u0004 מבשר בהמה העומדת למות, שאומרים לבעליה לשוחטה מהר קודם שתמות, \u0003\"ולא בא בפי בשר פגול\"\u0004 — \u0003שלא אכלתי מבהמה שהורה בה חכם,\u0004 שנולד בה ספק, אף על פי שלא נאסרה. \u0003משום\u0004 (בשם) \u0003ר' נתן אמרו:\u0004 הכוונה היא \u0003שלא אכלתי מבהמה שלא הורמו מתנותיה,\u0004 זרוע לחיים וקיבה שצריך לתת לכהנים. שאף שהדבר מותר, אין ראוי לעשות כן. ואם כן כיצד אכל רבה בר בר חנה מאותה בהמה? ומשיבים:","\u0003הני מילי\u0004 \u0005[דברים אלה אמורים]\u0006 על \u0003מילתא דתליא בסברא\u0004 \u0005[דבר שתלוי בסברה],\u0006 שראוי לחכם שלא לסמוך על סברתו במקום שיש ספק, ואילו \u0003רבה בר בר חנה אגמריה סמך\u0004 \u0005[על לימודו,\u0006 מסורתו, \u0005סמך],\u0006 על מה שקיבל מרבותיו, ואין בכך צד של איסור.","ושואלים: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 והרי יש כאן טעם אחר שלא לקנות מבשר הבהמה, \u0003משום חשדא\u0004 \u0005[החשד\u0006 שיש בדבר\u0005]!\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 מי ש\u0003דן את הדין, זיכה וחייב, טימא וטיהר,\u0004 או \u0003אסר והתיר, וכן העדים שהעידו\u0004 על דבר — \u0003כולן רשאין ליקח\u0004 (לקנות) מאותו דבר שהתירו אותו, \u0003אבל אמרו חכמים: הרחק מן הכיעור ומן הדומה לו,\u0004 ואם כן לא היה ראוי לרבה בר בר חנה לקחת מדבר שהוא עצמו הכשיר!","ומשיבים: \u0003הני מילי מידי דמזבין משומא\u0004 \u0005[דברים אלה אמורים בדבר שמוכרים אותו באומדן],\u0006 ולא במידה מדוייקת, ולכן יש מקום לחשוד שהדיין מקבל עבור כספו יותר מאחרים, \u0003אבל\u0004 \u0003הכא מתקלא מוכח\u0004 \u0005[כאן המשקל מוכיח],\u0006 שאינו מקבל הנחה, אלא משלם ככל אדם אחר. \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 \u0003דרבה שרא טרפתא וזבן מינה בישרא\u0004 \u0005[שרבה התיר\u0006 ספק \u0005טריפה ו\u0006אחר כך \u0005קנה ממנה בשר],\u0006 \u0003אמרה ליה\u0004 \u0005[לו]\u0006 \u0003בת רב חסדא,\u0004 אשתו: \u0003אבא שרי בוכרא ולא זבן מיניה בישרא\u0004 \u0005[אבי התיר בכור,\u0006 שפסק שיש בו מום, \u0005ולא קנה ממנו בשר],\u0006 ומדוע אוכל אתה מבשר שאתה עצמך הורית בו?","\u0003אמר לה: הני מילי בוכרא דאשומא מזדבן\u0004 \u0005[דברים אלה אמורים בבכור שמוכרים אותו רק באומדן],\u0006 ולא במשקל, ויש חשש של מראית עין, \u0003הכא מתקלא מוכח\u0004 \u0005[כאן המשקל מוכיח],\u0006 שאני משלם את המחיר הקבוע; \u0003מאי איכא\u0004 \u0005[מה\u0006 חשד \u0005יש]\u0006 כאן — \u0003משום אומצא מעלייתא\u0004 \u0005[חתיכת בשר משובחת\u0006 יותר\u0005]\u0006 שנותנים לי? בזה אין מקום לחשד, כי \u0003כל יומא אומצא מעלייתא זבנו לי\u0004 \u0005[כל יום חתיכת בשר מעולה נותנים לי].\u0006","אגב כך מביאים מה ש\u0003אמר רב חסדא: איזהו תלמיד חכם? זה הרואה טרפה לעצמו,\u0004 כלומר, כשיש לו ספק בבהמה של עצמו אוסר אותה, ואינו חס על ממונו. \u0003ואמר רב חסדא: איזהו\u0004 שנאמר בו \u0003\"שונא מתנות יחיה\"\u0004 (משלי טו, כז)? \u0003זה הרואה טרפה לעצמו,\u0004 שנזהר בכל ענין שלא ליהנות ממה שאינו שלו, ושמא בהמה זו אסורה עליו.","\u0003דרש מר זוטרא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב חסדא: כל מי שקורא\u0004 מקרא \u0003ושונה\u0004 משנה, \u0003ורואה טרפה לעצמו, ושימש תלמידי חכמים\u0004 ללמוד דרכי הלימוד וההוראה — \u0003עליו הכתוב אומר: \"יגיע כפיך כי תאכל אשריך וטוב לך\"\u0004 (תהלים קכח, ב). \u0003רב זביד אמר:\u0004 אדם כזה \u0003זוכה ונוחל שני עולמות, העולם הזה והעולם הבא,\u0004 שנאמר \"אשריך וטוב לך\", \u0003\"אשריך\"\u0004 — כוונתו \u0003בעולם הזה, \"וטוב לך\"\u0004 — גם \u0003לעולם הבא.\u0004","ובענין \"שונא מתנות יחיה\" מסופר, \u0003ר' אלעזר כי הוו משדרי ליה מבי נשיאה מידי\u0004 \u0005[כאשר היו שולחים לו מבית הנשיא דבר\u0006 כמתנה\u0005]\u0006 \u0003לא שקיל\u0004 \u0005[לא היה לוקח],\u0006 \u0003וכי הוו מזמני ליה\u0004 \u0005[וכאשר היו מזמינים אותו]\u0006 לאכול אצלם \u0003לא אזיל\u0004 \u0005[לא היה הולך],\u0006 וכך \u0003אמר\u0004 \u0005[היה אומר]\u0006 בהתנצלות: \u0003לא קא בעי מר דאיחי\u0004 \u0005[אין אדוני רוצה שאחיה]?\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]\u0006 \u0003\"ושונא מתנות יחיה\".\u0004 \u0003רבי זירא כי משדרי ליה\u0004 \u0005[כאשר היו שולחים לו\u0006 מתנה\u0005]\u0006 \u0003לא שקיל\u0004 \u0005[לא\u0006 היה \u0005נוטל],\u0006 אבל \u0003כי הוו מזמנין ליה\u0004 \u0005[כאשר היו מזמינים אותו]\u0006 \u0003אזיל\u0004 \u0005[היה\u0006 \u0005הולך],\u0006 ו\u0003אמר\u0004 כהסבר לדבר:"],["\u0003אתייקורי הוא דמתייקרו בי\u0004 \u0005[כבוד הוא שהם מתכבדים בי]\u0006 שאני סועד אצלם, ואין זה כמתנה עבורי, אלא הנאתם היא.","ועוד בענין הגרגרת (הקנה) שנפסקה (נחתכה לרוחבה) ברובה, ששנינו במשנה שהיא טריפה, \u0003אמר רב יהודה אמר רב:\u0004 אם \u0003ניקבה\u0004 הגרגרת סביב היקפה שורה של נקבים קטנים \u0003כ\u0004נקבי \u0003נפה\u0004 — הרי הנקבים הללו \u0003מצטרפים לרובא\u0004 \u0005[לרוב],\u0006 שאם יש בכולם כדי רוב היקפה הריהי טריפה, כאילו נפסקה ברובה.","\u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003רב ירמיה\u0004 מדין נקב בגולגולת, ששנינו שאם היה עגול ושיעורו כמלוא מקדח של רופאים (שהיו משתמשים בו לניתוחי גולגולת) — אינה מטמאה כמת בטומאת אוהל, ועל כן שנינו בברייתא: \u0003ובגולגולת שיש בה נקב אחד ארוך,\u0004 או \u0003אפילו יש בה נקבים הרבה\u0004 — \u0003מצטרפים\u0004 הנקבים (או הנקב הארוך) \u0003ל\u0004שיעור \u0003מלא מקדח.\u0004 \u0003אלמא\u0004 \u0005[מכאן]\u0006 שאנו אומרים: \u0003כיון\u0004 ש\u0003שיעורה\u0004 \u0003מלא מקדח\u0004 — נקבים קטנים \u0003ל\u0004שיעור \u0003מלא מקדח\u0004 \u0003מצטרפין,\u0004 ואין צורך בשיעור גדול יותר, \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 כשניקבה הגרגרת בנקבים דקים כשל נפה, \u0003כיון דשיעוריה\u0004 \u0005[ששיעורו]\u0006 של נקב בגרגרת לעשות טריפה הוא \u0003כ\u0004רוחב מטבע ששמו \u0003איסר\u0004 (להלן נד,א), אם כן הנקבים \u0003ל\u0004שיעור \u0003כאיסר מצטרפין,\u0004 ואין צורך שיצטרפו לרוב!","ומעירים: \u0003אישתמיטתיה\u0004 \u0005[נשמט,\u0006 נשכח \u0005ממנו]\u0006 מרב ירמיה \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר ר' חלבו אמר רב חמא בר גוריא אמר רב: נקבים שיש בהן חסרון,\u0004 כלומר, שנחסר בהם חלק ממשי מגוף הגרגרת — הם ה\u0003מצטרפין ל\u0004שיעור \u0003כאיסר,\u0004 \u0003ו\u0004אולם נקבים \u0003שאין בהן חסרון,\u0004 כגון שהם דקים כשל נפה — \u0003מצטרפין\u0004 דווקא \u0003לרובא\u0004 \u0005[לרוב],\u0006 כדין גרגרת שנפסקה, שאין בה חסרון, אלא הפגם בעצם החתך, ובפחות מרוב אינו טריפה.","כיוצא בו \u0003אמר רבה בר בר חנה אמר ר' יהושע בן לוי: ניטלה הימנה\u0004 (מן הגרגרת) \u0003רצועה\u0004 צרה וארוכה — הרי היא \u0003מצטרפת לכאיסר,\u0004 כאילו היה זה נקב עגול. ועל כך \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' יצחק בר נחמני מר' יהושע בן לוי:\u0004 אם \u0003ניקבה\u0004 הגרגרת \u0003כנפה מהו? אמר ליה\u0004 \u0005[לו],\u0006 \u0003הרי אמרו\u0004 בענין זה: \u0003נקבים שיש בהן חסרון\u0004 — \u0003מצטרפין לכאיסר, ושאין בהן חסרון\u0004 — \u0003מצטרפין לרובא.\u0004","ושואלים: דברים אלה שנקבים קטנים שיש בהם חסרון מצטרפים לכאיסר, אמורים בבהמה, אבל \u0003בעופא\u0004 \u0005[בעוף]\u0006 שניקבה הגרגרת שלו נקבים שיש בהם חסרון, \u0003מאי\u0004 \u0005[מה הדין]?\u0006 לכמה הם מצטרפים לעשות טריפה? שהרי רוחב גרגרת העוף כולו קטן מאיסר.","\u0003אמר ר' יצחק בר נחמני: לדידי מפרשא לי מיניה\u0004 \u0005[לי עצמי נתפרש הדבר ממנו]\u0006 מ\u0003ר' אלעזר:\u0004 חותך את האזור המנוקב \u0003ו\u0004\u0003מקפלו ומניחו על פי הקנה, אם\u0004 הוא \u0003חופה את רוב הקנה\u0004 — \u0003טרפה, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003כשרה. אמר רב פפא: וסימניך\u0004 לענין זה — \u0003נפיא\u0004 \u0005[נפה],\u0006 שאופן הבדיקה של הנקבים הנראים כנפה, הוא כנפה — שמניח את האזור המנוקב על פי הקנה, כעין נפה.","ובענין חסרון בגרגרת כאיסר, מביאים: גרגרת ש\u0003נפחתה כדלת,\u0004 כלומר, נחתכה ממנה חתיכה, ואולם היא מחוברת בצד אחד, כך שניתן לסגור על ידה את הנקב, \u0003אמר רב נחמן:\u0004 שיעורו לעשות טריפה הוא \u0003כדי שיכנס\u0004 שם \u0003מטבע\u0004 \u0003איסר לרחבו,\u0004 שניתן להכניס ולהוציא בו איסר לרוחבו, יותר מגודל איסר כשלעצמו. אם \u0003נסדקה\u0004 הגרגרת לאורכה\u0003,\u0004 \u0003אמר רב: אפילו לא נשתייר בה אלא חוליא אחת\u0004 שלמה \u0003למעלה, וחוליא אחת למטה\u0004 — הרי היא \u0003כשרה.\u0004","\u0003אמרוה קמיה\u0004 \u0005[אמרו את ההלכה הזו לפני]\u0006 \u0003ר' יוחנן, אמר: מה חוליא ומה חוליא,\u0004 מה מקום לענין זה של חוליה \u0003דקאמר\u0004 \u0005[שאומר]\u0006 \u0003רב?\u0004 \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך: \u0003אפילו לא נשתייר בה אלא משהו למעלה ומשהו למטה\u0004 — \u0003כשרה.\u0004","ומסופר, \u0003אמרוה\u0004 בארץ ישראל \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יונתן\u0004 הבבלי \u0003הכי\u0004 \u0005[\u0006ממש \u0005כך],\u0006 שדי שנשתייר בה משהו למעלה ומשהו למטה. \u0003אמר להו\u0004 \u0005[להם]\u0006 בהתפעלות: \u0003ידעין חברין בבלאי לפרושי כי האי טעמא\u0004 \u0005[יודעים חברינו הבבליים לפרש כטעם זה]\u0006 שאמרתי?","\u0003תנא\u0004 \u0005[שנה]\u0006 \u0003ר' חייא בר יוסף קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן: כל הצואר כולו כשר לשחיטה, מטבעת הגדולה\u0004 העליונה של הקנה \u0003עד\u0004 למטה מול \u0003כנפי\u0004 (קצוות) ה\u0003ריאה התחתונה. אמר רבא: תחתונה\u0004 כוונתו — כשתולים את הבהמה ברגליה לצורך הפשטה, וראשה למטה, \u0003שהיא\u0004 באמת ה\u0003עליונה,\u0004 הקצה שלצד הראש. \u0003שאני אומר,\u0004 שמקום השחיטה הוא \u0003כל\u0004 אורך הצוואר בשעה \u0003שפושטת צוארה ורועה\u0004 (אוכלת מן הקרקע) — \u0003ובלבד שלא תאנס,\u0004 שלא ימשכו את הצוואר בכח, שאם שוחט בקצה התחתון של הצוואר — נמצא ששוחט בקנה מתחת למקום הראוי לשחיטה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב חנינא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 ששאל זאת \u0003רב חנניה:\u0004 אם \u0003אנסה עצמה,\u0004 כלומר, הבהמה עצמה התאמצה ומתחה צווארה יותר מן הרגיל, \u0003מהו?\u0004 האם גם זה בכלל מקום שחיטה? \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה, שאין לה פתרון. מסופר, \u0003יתיב\u0004 \u0005[ישבו]\u0006 \u0003ר' יוחנן ור' שמעון בן לקיש, נפק מילתא מבינייהו\u0004 \u0005[יצא דבר מביניהם],\u0006 כלומר, הגיעו שניהם למסקנה הבאה: אם \u0003אנס בסימנים,\u0004 כלומר, משך ומתח בכוח את הקנה והוושט, \u0003ושחט\u0004 בקצה התחתון של הצואר — הרי זו \u0003פסולה.\u0004 אם \u0003ניקב הקנה למטה מן החזה\u0004 — הריהו \u0003נידון כ\u0004נקב ב\u0003ריאה,\u0004 שנקב כלשהו בה עושה טריפה, ולא כנקב בקנה, ששיעורו בכאיסר (להלן נד,א).","כדי להבין הלכה זו מביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003איזהו חזה\u0004 שצריך לתת לכהנים מכל קרבן שלמים (ויקרא ז, לא)? \u0003זה\u0004 החלק \u0003הרואה את הקרקע,\u0004 ולא אזור הצלעות שבצדדים. וגבולותיו לאורך הם: \u0003למטה\u0004 לצד הראש (שהוא למטה כשתולים את הבהמה ברגליה) — \u0003עד הצואר. למעלה,\u0004 לצד הגוף — \u0003עד הכרס.\u0004 וכן \u0003חותך שתי צלעות\u0004 ראשונות (מכיוון הראש) \u0003משתי דפנות אילך ואילך\u0004 (מכאן ומכאן), \u0003וזהו\u0004 \u0003חזה הניתן לכהנים.\u0004","שנינו בין הטריפות: \u0003ניקב קרום של מוח. רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 שני קרומים יש למוח, עליון (עבה יותר) הסמוך יותר לעצם הגולגולת, ותחתון דק, הצמוד למוח, והכוונה היא שניקב \u0003קרמא עילאה\u0004 \u0005[קרום העליון],\u0006 \u0003אף על גב דלא אינקיב תתאה\u0004 \u0005[אף על פי שלא ניקב התחתון].\u0006 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאינו טריפה \u0003עד דאינקיב תתאה\u0004 \u0005[שניקב\u0006 גם \u0005התחתון].\u0006 \u0003אמר ר' שמואל בר נחמני, וסימניך\u0004 לזכור: \u0003חייתא דמתנח ביה מוחא\u0004 \u0005[שק שמונח בו המוח],\u0006 שהוא הקרום התחתון.","\u0003אמר רבה בר בר חנה אמר ר' יהושע בן לוי:\u0004 אף שאין הקרום התחתון ניכר לעצמו, שהוא דק מאד, \u0003כנגדו בביצים\u0004 (באשכים) הוא \u0003ניכר,\u0004 שיש שם הבדל ניכר לעין בין גוף האשך עצמו לקרום התחתון. \u0003אמר ר' שמעון בן פזי אמר ר' יהושע בן לוי משום בר קפרא: מוח\u0004 — \u0003כל מה שבקדירה\u0004 (בגולגולת, הנראית כקדירה הפוכה) \u0003נדון כמוח, התחיל למשוך,\u0004 שנמשך כחוט דרך הנקב שבצידו האחורי — הרי זה \u0003נדון כחוט השדרה. ומהיכן\u0004 הוא המקום שהוא \u0003מתחיל לימשך? אמר ר' יצחק בר נחמני, לדידי מיפרשא לי מיניה\u0004 \u0005[לי עצמי מתפרש הדבר מפיו]\u0006 של \u0003ר' יהושע בן לוי: כמין שני\u0004"],["\u0003פולין\u0004 (בלוטות) \u0003יש\u0004 שהם \u0003מונחין על פי הקדרה,\u0004 בקצה האחורי של הגולגולת, שממנו נמשכת השדרה, \u0003מן הפולין ולפנים\u0004 — דינם \u0003כלפנים,\u0004 כמוח, שנקב כלשהו בקרום שלו עושה טריפה, \u0003מן הפולין ולחוץ\u0004 — \u0003כלחוץ,\u0004 כחוט שידרה, שרק אם נפסק ברובו טריפה. \u0003ו\u0004מקום \u0003פולין עצמן איני יודע\u0004 מה דינו, \u0003ומסתברא\u0004 \u0005[ומסתבר]\u0006 שדינו \u0003כלפנים.\u0004","מסופר, \u0003רבי ירמיה בדק בעופא\u0004 \u0005[בעוף]\u0006 \u0003ואשכח\u0004 \u0005[ומצא]\u0006 בו \u0003כמין שני פולין מונחין על פי הקדרה.\u0004","שנינו במשנה: \u0003ניקב הלב לבית\u0004 (למקום) \u0003חללו\u0004 הרי זו טריפה. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' זירא:\u0004 האם הכוונה היא \u0003לבית חלל\u0004 ה\u0003קטן\u0004 שבו, \u0003או לבית חלל גדול\u0004 שבו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מאי תיבעי לך\u0004 \u0005[מה תישאל לך]?\u0006 מה ספק יש בדבר? \u0003מי לא תנן\u0004 \u0005[האם לא שנינו]\u0006 ביחס לריאה שניקבה, \u0003ר' שמעון אומר: עד שתנקב לבית הסמפונות, ואמר רבה בר תחליפא אמר ר' ירמיה בר אבא אמר רב:\u0004 הכוונה היא \u0003עד שתנקב לסמפון\u0004 ה\u0003גדול.\u0004 ואם כן, גם כאן שנאמר \"לבית\" הכוונה היא לחלל הגדול!","ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003לבית הסמפונות קתני\u0004 \u0005[הוא שונה]\u0006 והכוונה היא \u0003להיכא דשפכי סמפונות כולהו\u0004 \u0005[למקום שאליו נשפכים כל הסמפונות כולם],\u0006 שהוא הסמפון הגדול, \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003לבית חללו קתני\u0004 \u0005[שנה],\u0006 בלשון יחיד, \u0003מה לי חלל גדול מה לי חלל קטן!\u0004","ושואלים: \u0003קנה הלב,\u0004 העורק הראשי היוצא ממנו, מה דינו לענין טריפה? \u0003רב אמר:\u0004 נקיבתו \u0003במשהו\u0004 עושה טריפה, כמו הלב עצמו, \u0003ושמואל אמר: ברובו.\u0004","ושואלים: \u0003הי ניהו\u0004 \u0005[מה הוא]\u0006 \u0003קנה הלב? אמר רבה בר יצחק אמר רב:\u0004 הכוונה היא לקנה הנמצא ב\u0003חלב שעל גבי דפנות.\u0004 ותוהים: \u0003דפנות\u0004 הבהמה \u0003סלקא דעתך\u0004 \u0005[יעלה על דעתך],\u0006 חלב הנמצא על גבי הצלעות? מה עניינו ללב?","\u0003אלא\u0004 הכוונה היא לקנה (עורק) מחופה בחלב \u0003ש\u0004יוצא מן הלב ועובר \u0003על גבי דופני\u0004 ה\u0003ריאה. אמר אמימר משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב נחמן: תלתא קני הוו\u0004 \u0005[שלושה קנים הם]\u0006 סמוכים זה לזה בבית החזה, \u0003חד פריש לליבא\u0004 \u0005[אחד פורש\u0006 ונכנס \u0005ללב],\u0006 \u0003וחד פריש\u0004 \u0005[ואחד פורש]\u0006 ונכנס \u0003לריאה, וחד פריש לכבדא\u0004 \u0005[ואחד פורש\u0006 ונכנס \u0005לכבד],\u0006 הקנה שנכנס ל\u0003ריאה\u0004 — דינו לענין טריפות \u0003כריאה,\u0004 שנקיבתו במשהו, \u0003דכבדא\u0004 \u0005[של הכבד]\u0006 — דינו \u0003ככבדא\u0004 \u0005[ככבד],\u0006 שהוא טריפה רק אם לא נשתייר ממנו כלום (לעיל מב,א), בענין הקנה \u0003דליבא\u0004 \u0005[של הלב]\u0006 — \u0003פליגי\u0004 \u0005[חלוקים]\u0006 רב ושמואל האם דינו במשהו או ברובו, כפי שנאמר לעיל.","ואילו \u0003מר בר חייא מתני איפכא\u0004 \u0005[שונה ההיפך]:\u0006 קנה של \u0003ריאה\u0004 — דינו \u0003ככבדא\u0004 \u0005[ככבד],\u0006 שרק אם ניטל לגמרי הרי זו טריפה, ואילו קנה \u0003דכבדא\u0004 \u0005[של הכבד]\u0006 — דינו \u0003כריאה,\u0004 שנקיבתו במשהו, ובקנה \u0003דליבא\u0004 \u0005[של הלב]\u0006 — \u0003פליגי\u0004 \u0005[חלוקים הם].\u0006","בענין המחלוקת בין רב ושמואל מסופר, \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003ר' חייא בר יוסף אמרה לשמעתא\u0004 \u0005[אמר את הלכתו]\u0006 של \u0003רב קמיה\u0004 \u0005[לפני]\u0006 \u0003שמואל,\u0004 שנקיבתו של קנה הלב במשהו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אמר אבא,\u0004 כלומר, רב, \u0003לא ידע בטרפות ולא כלום.\u0004","שנינו במשנה: \u0003נשבר השדרה\u0004 ונפסק החוט העובר בתוכה — טריפה. ובפרטי ענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חוט השדרה שנפסק\u0004 (נחתך לרוחבו) — רק אם החתך \u0003ברובו\u0004 הריהו טריפה, אלו \u0003דברי רבי; ר' יעקב אומר: אפילו ניקב.\u0004","ומעירים \u0003הורה רבי\u0004 במעשה שבא לידו \u0003כר' יעקב,\u0004 שדי בנקב כדי לעשות טריפה. \u0003אמר רב הונא: אין הלכה כר' יעקב.\u0004","ושואלים: \u0003וכמה רובו\u0004 של חוט השדרה? \u0003רב אמר: רוב עורו,\u0004 רוב היקפו של הקרום העוטף את מוח השדרה. \u0003ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003רוב מוחו,\u0004 אם המוח שבתוך החוט נפסק במקום אחד ברובו, למרות שהעור שמסביב שלם.","ומעירים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שאם נפסק \u0003רוב מוחו\u0004 טריפה — \u0003כל שכן\u0004 שהוא טריפה כשנפסק \u0003רוב עורו\u0004 לבד, מפני שאם נחתך העור ברובו גם למוח אין קיום, שסופו לצאת ממקומו. אולם \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003רוב עורו,\u0004 רב, אם נפסק \u0003רוב מוחו מאי\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ממה ש\u0003אמר\u0004 החכם \u0003ניולי אמר רב הונא: רובו שאמרו\u0004 שאם נפסק עושה טריפה — הוא \u0003רוב עורו,\u0004 אבל \u0003מוח זה\u0004 שבשדרה — \u0003לא מעלה ולא מוריד.\u0004","מסופר, \u0003רב נתן בר אבין הוה יתיב קמיה\u0004 \u0005[היה יושב לפני]\u0006 \u0003רב, בדק\u0004 תחילה \u0003ברוב עורו,\u0004 וראה שרובו קיים, \u0003וקא בדיק\u0004 \u0005[והיה בודק]\u0006 \u0003ברוב מוחו\u0004 לראות אם לא נפסק רובו, \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003אם רוב עורו קיים, מוח זה אינו מעלה ואינו מוריד.\u0004","\u0003אמר רבה בר בר חנה אמר ר' יהושע בן לוי:\u0004 אם \u0003נתמרך\u0004 חוט השדרה, שמוחו נעשה רך — הרי זה \u0003פסול,\u0004 ואפילו אם רק \u0003נתמסמס\u0004 — \u0003פסול,\u0004 והבהמה טריפה. \u0003איזוהי המרכה ואיזוהי המסמסה? המרכה\u0004 היא \u0003כל\u0004 שהמוח נעשה נוזלי עד \u0003שנשפך כקיתון,\u0004 שאם עושים נקב בעור הוא נשפך. ה\u0003מסמסה\u0004 היא \u0003כל\u0004 שנתרכך עד \u0003שאינו יכול לעמוד\u0004 בעצמו, אלא מתקפל כשמחזיקים אותו.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004 אם \u0003אינו יכול לעמוד\u0004 רק \u0003מפני כבדו,\u0004 שנעשה כבד מן הרגיל, ולא משום שנעשה רך יותר, \u0003מאי\u0004 \u0005[מה דינו]?\u0006 האם הוא טריפה? דבר זה לא נמצא לו פתרון, ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה. \u0003בי רב אמרי\u0004 \u0005[בבית\u0006 מדרשו של \u0005רב היו אומרים]:\u0006 אם \u0003נתמסמס\u0004 — \u0003פסול,\u0004 אבל אם \u0003נתמזמז\u0004 (נתרוקן) מקצת המוח — \u0003כשר. מיתיבי\u0004 \u0005[מקשים על כך],\u0006 ממה ששנינו בברייתא, \u0003ר' שמעון בן אלעזר אומר: בהמה שנתמזמז מוחה\u0004 — \u0003טרפה!\u0004 ודוחים: בברייתא \u0003ההיא נתמסמס איתמר\u0004 \u0005[נאמר],\u0006 שנעשה המוח רך.","ושואלים: \u0003איני\u0004 \u0005[\u0006וכי \u0005כן הוא]\u0006 שנתמזמז מוחה כשרה? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לוי הוה יתיב בי מסותא\u0004 \u0005[היה יושב בבית המרחץ],\u0006 \u0003חזייא לההוא גברא דטרייה לרישיה\u0004 \u0005[ראה אדם אחד שהטיח את ראשו\u0006 בקיר\u0005],\u0006 \u0003אמר: נתמזמז מוחיה דדין\u0004 \u0005[מוחו של זה],\u0006 \u0003לאו דלא חיי\u0004 \u0005[האם אין הכוונה ש\u0006שוב \u0005אינו חי]?\u0006 ואם כן משמע שבמזמוז טריפה הוא! \u0003אמר אביי: לא,\u0004 הכוונה היא \u0003לומר שאינו מוליד\u0004 עוד, שפגיעה בראש עלולה לגרום לעקרות.","ושואלים: \u0003עד היכן חוט השדרה\u0004 למטה, שאם נפסק שם הרי זו טריפה? \u0003אמר רב יהודה אמר שמואל: עד בין הפרשות\u0004 (הפיצולים) של חוט השדרה, לעבר הירכיים.","מסופר, \u0003רב דימי בר יצחק הוה קא בעי למיזל\u0004 \u0005[היה רוצה ללכת]\u0006 \u0003לבי חוזאי,\u0004 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' יהודה, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ליחוי לי מר\u0004 \u0005[יראה לי אדוני]\u0006 \u0003בין הפרשות\u0004 שאמר שמואל \u0003היכא\u0004 \u0005[היכן הוא]\u0006 בדיוק? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל אייתי\u0004 \u0005[בוא הבא]\u0006 \u0003לי גדי ואחוי\u0004 \u0005[ואראה]\u0006 \u0003לך. אייתי ליה\u0004 \u0005[הביא לו]\u0006 \u0003גדי שמינה\u0004 \u0005[שמן],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בליעה טפי ולא ידיע\u0004 \u0005[בלוע הרבה\u0006 בבשר, \u0005ואינו ניכר]\u0006 לעין החוט המתפצל מחוט השדרה. \u0003אייתי ליה\u0004 \u0005[הביא לו]\u0006 גדי \u0003כחוש, אמר לו: בליטן טפי ולא ידיע\u0004 \u0005[בולטות הן הרבה\u0006 העצמות \u0005ואינו ניכר].\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תא אגמרך גמרא\u0004 \u0005[בוא ואלמד אותך\u0006 \u0005מסורת]\u0006 בענין זה, בלי להראות לך, \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל:\u0004 שלושה פיצולים (פרשות) יוצאים מאותה עצם, זה במרחק מה מזה, והרווח שביניהם קרוי \"בין הפרשות\". \u0003עד אחת,\u0004 אם נפסק חוט השדרה עד בין הפרשות הראשונה, כלומר, בין הפיצול הראשון לשני — הרי זו \u0003טרפה,\u0004 אם נפסק \u0003ב\u0004\u0003שלישית,\u0004 לאחר הפיצול השלישי — \u0003כשרה,\u0004 נפסק בבין הפרשות ה\u0003שניה,\u0004 בין הפיצול השני לשלישי — \u0003איני יודע\u0004 מה דינו.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004"],["האם כשאמר שמואל \"עד אחת טריפה\", אומרים אנו ש\u0003\"עד\" ו\u0004גם \u0003\"עד\" בכלל\u0004 זה, שגם אם נפסק חוט השדרה בבין הפרשות הראשונה (בין הפיצול הראשון לשני) טריפה היא, כמו אם נפסק למעלה משם. \u0003או דלמא\u0004 \u0005[שמא]\u0006 הכוונה היא: \u0003עד\u0004 בין הפרשות הראשונה טריפה, \u0003ולא עד בכלל,\u0004 ואם נפסק שם הרי זה בכלל \"איני יודע\"?","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא: אם תמצי\u0004 \u0005[תמצא]\u0006 \u0003לומר,\u0004 אם אתה מניח ש\u0003עד ולא עד בכלל,\u0004 ואם נפסק בבין הפרשות הראשונה הוא בכלל \"איני יודע\", נפסק החוט ב\u0003פי פרשה\u0004 ראשונה, במקום הפיצול הראשון עצמו, \u0003מהו?\u0004 האם נחשב פי הפרשה כחלק מ\"בין הפרשות\" והוא בכלל \"איני יודע\", או האם נחשב כ\"עד בין הפרשות הראשונה\", וטריפה היא?","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבי ירמיה\u0004 באופן אחר: \u0003אם תמצי\u0004 \u0005[תמצא]\u0006 \u0003לומר עד ועד בכלל,\u0004 ואם נפסק חוט השדרה בבין הפרשות הראשונה טריפה היא, נפסקה \u0003פרשה עצמה,\u0004 החוט המתפצל מחוט השדרה, \u0003מהו?\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003הפרשה\u0004 שנפסקה \u0003תידון כבשר\u0004 סתם, ולא כחוט השדרה. \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה אפילו ל\u0003פרשה ראשונה ושניה,\u0004 שאם נפסקו החוט המתפצל מחוט השדרה — כשרה, למרות שאם נפסק חוט השדרה עצמו באותו מקום — טריפה היא (או \"איני יודע\")? ודוחים: \u0003לא,\u0004 הכוונה היא לפרשה \u0003שלישית,\u0004 אבל הפרשה הראשונה והשניה שנפסקו דינן כאילו נפסק חוט השדרה באותו מקום.","ונחלקו חכמים עד היכן ייפסק חוט השדרה \u0003בעופא\u0004 \u0005[בעוף]\u0006 וייעשה טריפה, \u0003ר' ינאי אומר:\u0004 עד \u0003למטה מן\u0004 המקום שמגיעות \u0003האגפים\u0004 (הכנפים), \u0003וריש לקיש אמר: עד בין אגפים,\u0004 ולא למטה משם.","\u0003אמר עולא: הוה קאימנא קמיה\u0004 \u0005[הייתי עומד לפני]\u0006 ר' שמעון \u0003בן פזי, ואייתו לקמיה עופא\u0004 \u0005[והביאו לפניו עוף]\u0006 שהיה בו חשש לפסיקה של חוט השדרה, \u0003ובדק עד בין אגפים. ו\u0004בתוך כך \u0003שלח ליה דבי נשיאה וקם ואזל\u0004 \u0005[שלחו לו מבית הנשיא\u0006 שיבוא \u0005ועמד והלך],\u0006 \u0003ולא ידענא אי\u0004 \u0005[ואין אני יודע אם]\u0006 קם והלך \u0003משום\u0004 ש\u0003לא צריך למבדק טפי\u0004 \u0005[לבדוק יותר],\u0006 \u0003אי\u0004 \u0005[או]\u0006 \u0003משום כבוד נשיאה\u0004 \u0005[הנשיא]\u0006 ולא גמר את הבדיקה\u0003.\u0004","\u0003ניטלה הכבד\u0004 ולא נשתייר ממנה כלום — טריפה. ומדייקים: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003נשתייר הימנה\u0004 (ממנה) \u0003כלום\u0004 (משהו) — \u0003כשרה, אף על גב\u0004 \u0005[אף על פי]\u0006 \u0003דלא הוי\u0004 \u0005[שלא היה]\u0006 במה שנשתייר \u0003כזית? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 להלן (נד,א); \u0003ניטל הכבד ונשתייר הימנה כזית\u0004 — \u0003כשרה,\u0004 ומשמע: ולא פחות מכזית!","\u0003אמר רב יוסף: לא קשיא\u0004 \u0005[אין זה קשה],\u0006 כי יש פה חילופי שיטות, \u0003הא\u0004 \u0005[זו]\u0006 שיטת \u0003ר' חייא, הא\u0004 \u0005[זו]\u0006 שיטת ר' שמעון בר רבי, \u0003כי הא\u0004 \u0005[כפי\u0006 שמסופר על \u0005זו]\u0006 שנשתייר מן הכבד שלה פחות מכזית, ש\u0003ר' חייא זריק לה\u0004 \u0005[היה זורק אותה],\u0006 שהיה סבור שהיא טריפה, \u0003ור' שמעון בר רבי מטביל לה\u0004 \u0005[היה מטביל אותה],\u0006 כלומר, אוכל אותה בטיבול, שסבר שכשירה היא. \u0003וסימניך\u0004 \u0005[והסימן שיש לך]\u0006 לזכור מה כל אחד מהם: \u0003עשירין מקמצין,\u0004 שר' שמעון בר רבי שהיה עשיר, הוא זה שקימץ ולא זרק.","מסופר, \u0003ההוא פולמוסא דאתא\u0004 \u0005[\u0006מעשה ב\u0005חיל המלך שנכנס]\u0006 \u0003לפומבדיתא, ערקו\u0004 \u0005[ברחו משם]\u0006 \u0003רבה ורב יוסף, פגע בהו\u0004 \u0005[פגש בהם]\u0006 \u0003ר' זירא, אמר להו\u0004 \u0005[להם]:\u0006 \u0003ערוקאי\u0004 \u0005[בורחים],\u0006 לימדו ממני הלכה זו: \u0003כזית שאמרו\u0004 שאם נשתייר בכבד כשרה היא — כוונתו שנשאר כזית \u0003במקום\u0004 חיבור הכבד ל\u0003מרה.\u0004 ואילו \u0003רב אדא בר אהבה אמר:\u0004 כזית שאמרו הוא \u0003במקום שהיא חיה,\u0004 כלומר, במקום בו הוא תלוי, מתחת לכליה הימנית. \u0003אמר רב פפא: הלכך\u0004 \u0005[משום כך],\u0006 כיון שנאמרו שתי שיטות ואין בידינו להכריע, \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיה גם \u0003כזית במקום מרה, ובעינן\u0004 \u0005[וצריכים אנו]\u0006 שיהיה גם \u0003כזית במקום שהיא חיה,\u0004 ואם לא — טריפה היא.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004 אם אותו כזית שנשתייר לא היה גוש אחד אלא \u0003מתלקט\u0004 מחתיכות מפוזרות, \u0003מהו?\u0004 וכן אם היה נראה \u0003כרצועה,\u0004 צר וארוך, \u0003מהו?\u0004 וכן \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי: כזית\u0004 שהוא \u0003מרודד,\u0004 שטוח לגמרי, \u0003מהו\u0004 דינו? לכל השאלות הללו לא נמצאה תשובה, אלא \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ר' זריקא מר' אמי:\u0004 אם \u0003נדלדלה\u0004 ה\u0003כבד,\u0004 נעקרה במקומות הרבה, \u0003ומעורה בטרפשיה\u0004 \u0005[ומחוברת בקרומים שלה]\u0006 העוטפים אותה, וכל הכבד קיים, \u0003מהו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דלדול זה\u0004 שאתה אומר \u0003איני יודע מהו,\u0004 כלומר, איני יודע מה משמעות יש לדבר הזה לענין הלכה, כי \u0003אי למאן דאמר\u0004 \u0005[אם לדעת מי שאומר]\u0006 שצריך שישתייר \u0003במקום מרה\u0004 — \u0003הא איכא\u0004 \u0005[הרי יש],\u0006 \u0003אי למאן דאמר\u0004 \u0005[אם לדעת מי שאומר]\u0006 \u0003במקום שהיא חיה\u0004 — \u0003הא איכא\u0004 \u0005[הרי יש]\u0006 ואם כן, בוודאי כשירה היא.","שנינו במשנה: \u0003הריאה שניקבה\u0004 הריהי טריפה. \u0003רב ושמואל ורב אסי דאמרי\u0004 \u0005[שאמרו]\u0006 כולם: הכוונה ל\u0003קרמא עילאה\u0004 \u0005[קרום העליון]\u0006 הסמוך לריאה, שניקב. \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהמדובר דווקא ב\u0003קרמא תתאה\u0004 \u0005[קרום תחתון].\u0006 \u0003אמר רב יוסף בר מניומי אמר רב נחמן, וסימניך\u0004 \u0005[וסימנך]:\u0006 \u0003כיתונא דורדא דמנחא ביה\u0004 \u0005[כותונת אדומה שמונחת בה]\u0006 ה\u0003ריאה,\u0004 שהיא הקרום התחתון, שהוא אדום (שהקרום העליון הוא לבן).","ואומרים: \u0003פשיטא\u0004 \u0005[פשוט]:\u0006 \u0003אי אינקיב עילאה ולא אינקיב תתאה\u0004 \u0005[אם ניקב הקרום העליון ולא ניקב התחתון]\u0006 — \u0003תתאה מגין\u0004 \u0005[הקרום התחתון מגן]\u0006 על הריאה, והרי היא כשירה, ו\u0003כ\u0004דברי \u0003רבה.\u0004 ש\u0003אמר רבה: האי ריאה דאגליד\u0004 \u0005[ריאה זו שנקלפה],\u0006 שנקלף ממנה הקרום העליון,"],["ונראית \u0003כאהינא סומקא\u0004 \u0005[כתמרה אדומה]\u0006 — הרי זו \u0003כשרה,\u0004 וכל שכן אם רק ניקב הקרום העליון. אולם אם \u0003אינקיב תתאה ולא אינקיב עילאה\u0004 \u0005[ניקב\u0006 הקרום \u0005התחתון ולא ניקב העליון],\u0006 האם הקרום העליון \u0003מגין,\u0004 ואינה טריפה, \u0003או לא מגין?\u0004","\u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה\u0004 בשאלה זו \u0003רב אחא ורבינא, חד\u0004 \u0005[אחד מהם]\u0006 \u0003אמר: לא מגין, וחד\u0004 \u0005[ואחד מהם]\u0006 \u0003אמר: מגין. והלכתא\u0004 \u0005[וההלכה היא]:\u0006 \u0003מגין,\u0004 ו\u0003כ\u0004דברי \u0003רב יוסף.\u0004 ש\u0003אמר רב יוסף: האי ריאה דאוושא\u0004 \u0005[ריאה זו שמשמיעה קול]\u0006 כשמנפחים אותה, \u0003אי ידעינן היכא אוושא\u0004 \u0005[אם יודעים אנו מהיכן\u0006 היא \u0005משמיעה קול]\u0006 — \u0003מותבינן עלה גדפא\u0004 \u0005[מניחים עליה\u0006 באותו מקום \u0005נוצה],\u0006 \u0003או רוקא\u0004 \u0005[רוק],\u0006 \u0003או גילא\u0004 \u0005[קש],\u0006 \u0003אי מבצבצא\u0004 \u0005[אם מעלה\u0006 הרוק \u0005בועות]\u0006 בזמן הנשיפה — \u0003טרפה,\u0004 שברור שיש שם חור מפולש, והאויר יוצא מן הריאה דרך שני הקרומים, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 אין יוצא משם — \u0003כשרה. ואי לא ידעינן היכא אוושא\u0004 \u0005[ואם אין אנו יודעים מהיכן היא משמיעה קול]\u0006 — \u0003מייתינן מתיכלתא דמיא פשורי\u0004 \u0005[מביאים אנו גיגית של מים פושרים],\u0006 \u0003ומותבינן לה בגוה\u0004 \u0005[ומניחים\u0006 את הריאה \u0005בתוכה].\u0006","ומעירים: \u0003בחמימי\u0004 \u0005[במים חמים]\u0006 \u0003לא\u0004 מניחים את הריאה — מפני \u0003דכווצי\u0004 \u0005[שמכווצים]\u0006 את הריאה, והנקב נסתם, \u0003בקרירי\u0004 \u0005[במים קרים]\u0006 \u0003לא\u0004 — מפני \u0003דמטרשי\u0004 \u0005[שמקשים\u0006 אותה\u0005],\u0006 ובשל כך עלול להיווצר קרע שלא היה שם מתחילה. \u0003אלא מותבינן בפשורי\u0004 \u0005[ומניחים אנו\u0006 אותה במים \u0005פושרים],\u0006 \u0003ונפחינא לה\u0004 \u0005[ומנפחים אנו אותה],\u0006 \u0003אי מבצבצא\u0004 \u0005[אם היא מבצבצת,\u0006 מעלה בועות\u0005]\u0006 — הרי היא \u0003טרפה,\u0004 שהאויר יוצא דרך שני הקרומים. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003כשרה,\u0004 ומדוע? שאנו אומרים \u0003תתאה אינקיב\u0004 \u0005[\u0006הקרום \u0005התחתון ניקב],\u0006 \u0003עילאה לא אינקיב\u0004 \u0005[העליון לא ניקב],\u0006 \u0003והאי דאוושא\u0004 \u0005[וזה ש\u0006היא \u0005משמיעה קול]\u0006 — \u0003זיקא דביני ביני הוא\u0004 \u0005[\u0006מחמת \u0005הרוח ש\u0006יוצאת \u0005בין זה לזה\u0006 בין קרום עליון לתחתון \u0005הוא].\u0006 הרי שלדברי רב יוסף, \u0003ניקב קרום תחתון ולא ניקב העליון — כשרה.\u0004","\u0003(אהיני סומקא דיבש גילדי, סימן\u0004 למימרות המובאות בשם רבא בענין ריאה","\u0003). גופא\u0004 \u0005[\u0006ושבים \u0005לגופה]\u0006 של הלכה \u0003ש\u0004\u0003אמר רבא\u0004 לעיל: \u0003האי ריאה דאיגליד\u0004 \u0005[ריאה זו שנקלף]\u0006 הקרום העליון שלה, ומראיה \u0003כאהינא סומקא\u0004 \u0005[כתמרה אדומה]\u0006 — \u0003כשרה.\u0004 ומוסיפים הלכות נוספות שאמר בעניינים אלו. \u0003ואמר רבא: ריאה שהאדימה,\u0004 שהקרום העליון שלה, שהוא לבן בדרך כלל, נעשה אדום מדם שהצטבר תחתיו, אם האדימה \u0003מקצתה\u0004 — הרי היא \u0003כשרה,\u0004 אם \u0003כולה\u0004 — \u0003טרפה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרבא: מקצתה מאי טעמא\u0004 \u0005[מה טעם]\u0006 אותה אתה מכשיר? משום \u0003דהדרא בריא\u0004 \u0005[ש\u0006באופן כזה \u0005היא חוזרת ומבריאה],\u0006 והרי אם האדימה \u0003כולה נמי הדרא בריא\u0004 \u0005[גם כן היא חוזרת ומבריאה]!\u0006 \u0003מי לא תניא\u0004 \u0005[האם לא שנויה\u0006 ברייתא\u0005]\u0006 בענין שמונה השרצים הטמאים, שאם עשה בהם חבורה בשבת — חייב: \u0003ושאר שקצים ורמשים\u0004 שחבל בהם, אינו חייב \u0003עד שיצא מהם דם,\u0004 ואם לא יצא הדם לחוץ — גם אם האדים העור פטור, כיון שהדם חוזר ונבלע בגופם!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003לשמונה שרצים מדמינן לה\u0004 \u0005[מדמים אנו אותה]\u0006 את הריאה, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 לגבי שמונה שרצים: אם \u0003נצרר\u0004 (התאסף) \u0003הדם,\u0004 מתחת העור, \u0003אף על פי שלא יצא\u0004 — חייב, מפני שהדם אינו חוזר ונבלע בהם. והוא הדין לריאה, שאם האדימה אין הדם חוזר ונבלע. \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אפילו מקצתה\u0004 האדימה \u0003נמי\u0004 \u0005[גם כן]\u0006 תהיה טריפה! \u0003אלא, לא שנא\u0004 \u0005[אינו שונה],\u0006 אין לחלק בין מקצתה לכולה.","\u0003ואמר רבא\u0004 עוד בהלכות אלה: \u0003ריאה שיבשה מקצתה\u0004 — \u0003טרפה.\u0004 ושואלים: \u0003וכמה\u0004 הוא שתיבש ותהא טריפה? \u0003אמר רב פפי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: כדי שתפרך,\u0004 שאפשר יהיה לפורר אותה \u0003בצפורן,\u0004 וזה סימן שהתייבשה לגמרי, ואין לה תקנה.","ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי\u0006 אמר זאת\u0005],\u0006 האם \u0003כ\u0004דעת היחיד \u0003רבי יוסי בן המשולם? דתניא\u0004 \u0005[ששנויה\u0006 משנה\u0005],\u0006 בענין בכור בהמה טהורה, שאם יבשה אוזנו הרי זה מום המתיר לשוחטו מחוץ למקדש: \u0003איזו היא יבשה\u0004 — כל \u0003שאם תינקב ואינה מוציאה טיפת דם; ר' יוסי בן המשולם אומר:\u0004 צריך שתהא \u0003יבשה\u0004 יותר מכך, \u0003כדי שתהא נפרכת בצפורן?\u0004","ודוחים: \u0003אפילו תימא רבנן\u0004 \u0005[תאמר\u0006 כדברי \u0005חכמים],\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003אוזן בכור, דקא שליט ביה זיקא\u0004 \u0005[ששולטת בה הרוח],\u0006 שהרי היא גלויה — \u0003לא הדרא בריא\u0004 \u0005[אינה חוזרת ומבריאה],\u0006 \u0003אבל ריאה דלא קא שליט ביה אוירא\u0004 \u0005[שאין האויר שולט בה]\u0006 — \u0003הדרא בריא\u0004 \u0005[חוזרת ומבריאה]\u0006 כאשר היא מתייבשת, ואם כן אין להוכיח מכאן. \u0003ואמר רבא: האי ריאה דקיימא גילדי גילדי\u0004 \u0005[ריאה זו שעומדת\u0006 לפנינו כשהיא \u0005מכוסה גלדים גלדים],\u0006 או \u0003אוכמי אוכמי\u0004 \u0005[\u0006כתמים \u0005שחורים]\u0006 או \u0003חזותא חזותא\u0004 \u0005[מראות,\u0006 צבעים \u0005שונים]\u0006 — עדיין היא \u0003כשרה.\u0004","\u0003אמר אמימר משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: אין מקיפין\u0004 \u0005[מקרבים,\u0006 משווים\u0005]\u0006 \u0003בבועי\u0004 \u0005[בבועות\u0006 שעל גבי הריאה\u0005],\u0006 שאם נמצא נקב בבועה, ואין ידוע אם היה בה קודם שחיטה והיא טריפה, או לאחר שחיטה והיא כשרה — אין עושים נקב בבועה אחרת, כדי להשוות אותן.","\u0003ו\u0004עוד \u0003אמר רבא: הני תרתי אוני דסריכן להדדי\u0004 \u0005[שתי אונות\u0006 של הריאה, \u0005שדבוקות\u0006 בסירכא \u0005זו לזו],\u0006 שמחוברות במעין חוטים ריריים שהתעבו — \u0003לית להו\u0004 \u0005[אין להם]\u0006 צורך ב\u0003בדיקה,\u0004 שוודאי טריפה היא, שסירכא זו מחמת נקב היא באה. ומוסיפים, \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא שלא כסדרן,\u0004 כלומר, באונות שאינן סמוכות זו לזו, \u0003אבל\u0004 אם הם היו \u0003כסדרן\u0004 — \u0003היינו רביתייהו\u0004 \u0005[זהו דרך גידולן],\u0006 ואינה טריפה."],["\u0003ואמר רבא: הני תרתי בועי דסמיכי להדדי\u0004 \u0005[שתי בועות\u0006 מלאות נוזל \u0005הסמוכות זו לזו]\u0006 על גבי הריאה — \u0003לית להו בדיקותא\u0004 \u0005[אין\u0006 מועילה \u0005להן בדיקה],\u0006 שטריפה היא, שמורה הדבר על נקב בריאה שהעלה בועות אלו סביביו. אבל אם היתה \u0003חדא ומתחזיא כתרתי\u0004 \u0005[\u0006בועה \u0005אחת שנראית כשתים],\u0006 שיש שקע באמצעה — \u0003מייתינן סילוא ובזעינן לה\u0004 \u0005[מביאים אנו קוץ ומנקבים אותה]\u0006 כדי שיצא הנוזל שבתוכה, \u0003אי שפכן להדדי\u0004 \u0005[אם הן שופכות\u0006 נוזל \u0005מזו לזו],\u0006 שהנוזל שבשתיהן יוצא דרך אותו נקב — \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003היא\u0004 הבועה, \u0003וכשרה, ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 שופכות מזו לזו — \u0003תרתי נינהו\u0004 \u0005[שתים הן]\u0006 \u0003וטרפה.\u0004","\u0003ואמר רבא: חמש אוני אית לה\u0004 \u0005[חמש אונות יש לה]\u0006 \u0003לריאה,\u0004 וכשתולים אותה ברגליה לאחר שחיטה כאשר \u0003אפה כלפי גברא\u0004 \u0005[פניה כלפי האדם]\u0006 הבודק — הריהן \u0003תלתא מימינא ותרתי משמאלא\u0004 \u0005[שלוש מימין\u0006 הבודק \u0005ושתים משמאל].\u0006 אם היה \u0003חסיר\u0004 \u0005[חסר]\u0006 אונא, \u0003או יתיר\u0004 \u0005[יתר],\u0006 \u0003או חליף\u0004 \u0005[מוחלף\u0006 בסדר\u0005]\u0006 שתים מימין ושלוש משמאל — הרי זו \u0003טרפה.\u0004","מסופר, \u0003ההוא יתירתא דאתאי לקמיה\u0004 \u0005[אותה\u0006 ריאה שהיתה בה אונה \u0005יתירה שבאה לפני]\u0006 \u0003מרימר, הוה יתיב\u0004 \u0005[היה יושב]\u0006 \u0003רב אחא אבבא\u0004 \u0005[על פתח]\u0006 בית מרימר. כשיצא השואל, \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אחא: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003אמר לך\u0004 מרימר? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אכשרה ניהלה\u0004 \u0005[הכשיר אותה לי].\u0006 תמה על כך רב אחא, שהרי רבא אמר שהיא טריפה, ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 לאותו איש: \u0003הדר עיילה קמיה\u0004 \u0005[חזור והכנס אותה לפניו]!\u0006 ועשה כן. \u0003אמר ליה\u0004 \u0005[לו]\u0006 מרימר, שידע מדוע הוא חוזר ומביא לפניו אותה שאלה: \u0003זיל אימא ליה למאן דיתיב אבבא\u0004 \u0005[לך אמור לו למי שיושב על הפתח]:\u0006 \u0003לית הלכתא כוותיה\u0004 \u0005[אין הלכה כשיטתו]\u0006 של \u0003רבא ביתרת,\u0004 באונה יתירה.","ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 שאין היתרת טריפה במקרה \u0003דקיימא בדרא דאוני\u0004 \u0005[שעומדת,\u0006 נמצאת \u0005בשורה של\u0006 שאר \u0005האונות],\u0006 מימין או משמאל, \u0003אבל\u0004 אם היתה נמצאת \u0003ביני ביני\u0004 \u0005[בין לבין,\u0006 באמצע\u0005]\u0006 — \u0003טרפה\u0004 היא.","מסופר, \u0003ההוא ביני ביני\u0004 \u0005[אותה\u0006 ריאה שהיתה בה אונה נוספת \u0005בין לבין]\u0006 \u0003דאתא לקמיה\u0004 \u0005[שבאה לפני]\u0006 \u0003רב אשי, סבר רב אשי למיטרפה\u0004 \u0005[להטריף אותה]\u0006 כפי שאמרנו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא מר בר אויא: כל הני חיוי ברייתא הכי אית להו\u0004 \u0005[אותן חיות,\u0006 בהמות, \u0005הרועות בשדה כך יש להן],\u0006 אונה יתירה כזו, \u0003וקרו לה טבחי\u0004 \u0005[וקוראים לה הטבחים]\u0006 לאונה היתירה הזו \u0003\"עינוניתא דוורדא\"\u0004 \u0005[אונת הוורד הקטנה].\u0006 ומוסיפים, \u0003והני מילי מגואי\u0004 \u0005[ודברים אלה אמורים מבפנים],\u0006 בצד הפנימי של הריאה, הפונה לכיוון הלב."],["\u0003אבל\u0004 אם היתה האונה היתירה הזו \u0003אגבה\u0004 \u0005[על גבה],\u0006 מצידה האחורי של הריאה, \u0003אפילו\u0004 היתה קטנה \u0003כטרפא דאסא\u0004 \u0005[כעלה של הדס]\u0006 — הרי זו \u0003טרפה.\u0004","ועוד בעניני טריפות הריאה \u0003אמר רפרם: האי ריאה דדמיא לאופתא\u0004 \u0005[ריאה זו שדומה לבקעת,\u0006 חתיכת עץ\u0005]\u0006 — \u0003טרפה\u0004 היא. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שהדמיון הוא \u0003בחזותא\u0004 \u0005[במראה],\u0006 שנעשית לבנה כבקעת עץ, \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003בגישתא\u0004 \u0005[במישוש],\u0006 שלפי המישוש היא קשה כעץ. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003דנפיחה\u0004 \u0005[ש\u0006היא נפוחה\u0005],\u0006 \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003דפחיזא\u0004 \u0005[ש\u0006היא \u0005קלה],\u0006 \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003דשיעא\u0004 \u0005[ש\u0006היא \u0005חלקה לגמרי],\u0006 \u0003דלית לה חיתוכא דאוני\u0004 \u0005[שאין לה חיתוך של אונות].\u0006","\u0003אמר רבא:\u0004 ריאה שציבעה \u0003ככוחלא\u0004 \u0005[כמו\u0006 \u0005כחול],\u0006 צבע שכוחלים בו את העין — \u0003כשרה,\u0004 שחורה \u0003כדיותא\u0004 \u0005[כדיו]\u0006 — \u0003טרפה,\u0004 שכן \u0003אמר ר' חנינא\u0004 בענין הנדה: הדם ה\u0003שחור אדום הוא, אלא שלקה\u0004 (התקלקל), ואם כן צבע שחור מורה על פגם. ועוד אומרים: היתה הריאה","\u0003ירוקה\u0004 — \u0003כשרה,\u0004 וכפי שנלמד \u0003מ\u0004דברי \u0003ר' נתן.\u0004 וכן אם היתה \u0003אדומה\u0004 ביותר, מלאה דם — גם אז \u0003כשרה\u0004 היא, כפי שנלמד \u0003מ\u0004דברי \u0003ר' נתן.\u0004 ומהם דברי ר' נתן אלה? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' נתן אומר: פעם אחת הלכתי לכרכי הים\u0004 (ערים הגדולות שמעבר לים הגדול), \u0003באתה\u0004 (באה) \u0003אשה אחת לפני\u0004 לשאול שאלה, \u0003שמלה\u0004 את \u0003בנה\u0004 ה\u0003ראשון ומת,\u0004 וכן מלה את ה\u0003שני ומת, שלישי\u0004 — \u0003הביאתו\u0004 \u0005[הביאה אותו]\u0006 \u0003לפני. ראיתיו\u0004 את התינוק \u0003שהיה אדום, אמרתי לה: בתי, המתיני לו עד שיבלע בו דמו\u0004 ויהיה צבע עורו רגיל. \u0003המתינה לו\u0004 עד שנבלע דמו \u0003ומלה אותו, וחיה\u0004 אותו תינוק, \u0003והיו קורין אותו\u0004 את הילד שנשאר בחיים \u0003\"נתן הבבלי\" על שמי.\u0004 ומכאן יש ללמוד גם לענין ריאה, שאף שהיא אדומה — הריהי חוזרת ומבריאה.","עוד סיפר ר' נתן: \u0003ושוב פעם אחת הלכתי למדינת קפוטקיא\u0004 שבאסיא הקטנה, \u0003באתה אשה לפני\u0004 לשאול שאלה, \u0003שמלה\u0004 את \u0003בנה\u0004 ה\u0003ראשון ומת, שני ומת, שלישי\u0004 — \u0003הביאתו לפני, ראיתיו שהיה ירוק\u0004 (צהבהב, חיור), \u0003הצצתי\u0004 (התבוננתי) \u0003בו\u0004 \u0003ולא היה בו\u0004 די דם כדי שיצא ממנו \u0003דם ברית,\u0004 \u0003אמרתי לה\u0004 לאם הילד: \u0003בתי, המתיני לו\u0004 לתינוק \u0003עד שיפול\u0004 (שייכנס) \u0003בו דמו! המתינה לו\u0004 כדי הזמן הזה, \u0003ו\u0004אחר כך \u0003מלה אותו וחיה, והיו קורין אותו \"נתן הבבלי\" על שמי.\u0004 ומכאן יש ללמוד גם לענין ריאה, שאם היתה ירוקה — כשרה היא. ועוד בענין מראות הריאה.","\u0003אמר רב כהנא:\u0004 ריאה שנראית \u0003ככבדא\u0004 \u0005[ככבד]\u0006 — \u0003כשרה,\u0004 נראית \u0003כבשרא\u0004 \u0005[כבשר]\u0006 — \u0003טרפה. וסימניך\u0004 שלא תחליף: \u0003\"ובשר בשדה טרפה\u0004 לא תאכלו\" (שמות כב, ל), שאם הריאה נראית כבשר — הרי היא טריפה ואין אוכלים אותה.","\u0003אמר רב סמא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא: האי ריאה דדמיא ככשותא\u0004 \u0005[ריאה זו שנראית ככשות]\u0006 שהוא צהבהב, או \u0003כמוריקא\u0004 \u0005[ככרכום]\u0006 שהוא כתום, \u0003וכגון ביעתא\u0004 \u0005[\u0006חלמון של \u0005ביצה]\u0006 — בכל המראות האלה היא \u0003טרפה.\u0004 ושואלים: אם כן, \u0003אלא ירוקה\u0004 שאמרנו ש\u0003כשרה היכי דמיא\u0004 \u0005[כיצד היא בדיוק]?\u0006 ומשיבים: שהיה לה צבע \u0003ככרתי,\u0004 שהוא צבע ירוק נוטה לכחול.","\u0003אמר רבינא:\u0004 אם היה מקום \u0003אטום בריאה,\u0004 שלא נכנס בו אויר, \u0003מייתינן סכינא וקרעינן לה\u0004 \u0005[מביאים אנו סכין וקורעים אנו אותה],\u0006 \u0003אי אית\u0004 \u0005[אם יש]\u0006 \u0003בה מוגלא\u0004 באותו מקום — \u0003ודאי מחמת מוגלא הוא\u0004 שנעשה האוטם הזה, שמנעה את כניסת האויר, \u0003וכשרה\u0004 הבהמה. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 מצאנו בה מוגלה — \u0003מותבינן עלה גדפא או רוקא\u0004 \u0005[מושיבים אנו עליה\u0006 באותו מקום \u0005נוצה או רוק],\u0006 ונושפים בריאה, \u0003אי מבצבצא\u0004 \u0005[אם מבצבץ,\u0006 מתנועע\u0005]\u0006 העלה או הרוק — \u0003כשרה,\u0004 שסימן הוא לכך שאויר מגיע לאותו מקום, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 יוצא אויר משם — לקות היא בריאה עצמה, ו\u0003טרפה.\u0004","\u0003אמר רב יוסף: קרום שעלה מחמת מכה\u0004 (פצע) \u0003בריאה\u0004 — \u0003אינו קרום,\u0004 משום שאינו מתקיים שם לאורך זמן. \u0003ואמר רב יוסף: האי ריאה דאוושא\u0004 \u0005[ריאה זו שמשמיעה קול]\u0006 כשנושפים לתוכה, \u0003אי ידעינן היכא אוושא\u0004 \u0005[אם יודעים אנו היכן היא משמיעה קול]\u0006 — \u0003מנחינן עלה גדפא או רוקא\u0004 \u0005[מניחים אנו עליה\u0006 באותו מקום \u0005נוצה או קש או רוק],\u0006 ונושפים, \u0003אי מבצבצא\u0004 \u0005[אם\u0006 הוא \u0005מבצבץ,\u0006 מתנועע\u0005]\u0006 — \u0003טרפה,\u0004 שיש שם נקב, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003כשרה. ואי לא ידעינן לה\u0004 \u0005[ואם אין יודעים]\u0006 מהיכן יוצא הקול, \u0003מייתי משיכותא דמיא פשורי\u0004 \u0005[מביאים גיגית של מים פושרים],\u0006 \u0003ומותבינן לה בגוה\u0004 \u0005[ומניחים אותה,\u0006 את הריאה, \u0005בתוכה].\u0006","ומעירים: ודווקא במים פושרים, אבל \u0003בחמימי\u0004 \u0005[במים חמים]\u0006 \u0003לא\u0004 — משום \u0003דכווצי\u0004 \u0005[ש\u0006הם \u0005מכווצים]\u0006 את הריאה, \u0003בקרירי\u0004 \u0005[ב\u0006מים \u0005קרים]\u0006 \u0003לא\u0004 — משום \u0003דמטרשי\u0004 \u0005[ש\u0006הם \u0005מקשים]\u0006 אותה, \u0003אלא בדקינן לה בפשורי\u0004 \u0005[בודקים אנו אותה ב\u0006מים \u0005פושרים],\u0006 שנושפים בריאה כשהיא בתוך המים, ורואים \u0003אי מבצבצא\u0004 \u0005[אם היא מבצבצת\u0006 מעלה בועות\u0005]\u0006 — \u0003טרפה, ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003כשרה,\u0004 שאנו אומרים: \u0003תתאה אינקיב, עילאה לא אינקיב\u0004 \u0005[\u0006הקרום \u0005התחתון ניקב, העליון לא ניקב],\u0006 \u0003והאי דאוושא\u0004 \u0005[וזה משמיעה קול]\u0006 — \u0003זיקא דביני וביני הוא\u0004 \u0005[הרוח שנכנס בין\u0006 קרום \u0005זה לזה הוא].\u0006","\u0003אמר עולא אמר ר' יוחנן: ריאה שנשפכה כקיתון,\u0004 שבשר הריאה נשפך כמים בתוך הקרומים שלה — \u0003כשרה.\u0004 ומעירים: \u0003אלמא קסבר\u0004 \u0005[מכאן שהוא סבור]:\u0006 \u0003חסרון מבפנים\u0004 בתוך אבר \u0003לא שמיה\u0004 \u0005[אין שמו,\u0006 דינו\u0005]\u0006 כ\u0003חסרון,\u0004 אלא דווקא אם נחסר מצידו החיצון.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' אבא לעולא\u0004 ממה ששנינו במשנתנו: \u0003הריאה שניקבה או שחסרה\u0004 — טריפה. ויש לשאול: \u0003מאי\u0004 \u0005[מה פירוש]\u0006 \u0003חסרה? אילימא\u0004 \u0005[אם תאמר]\u0006 שחסרה \u0003מבחוץ\u0004 — \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003ניקבה,\u0004 שהרי לא יתכן חסרון מבחוץ שאינו נוקב את קרום הריאה! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 צריך לומר שניקבה — מבחוץ, וחסרה — \u0003מבפנים,\u0004 \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 ש\u0003חסרון מבפנים שמיה\u0004 \u0005[שמו]\u0006 \u0003חסרון!\u0004","ודוחים: \u0003לא, לעולם\u0004 תאמר שחסרה ששנינו הוא גם כן \u0003מבחוץ, ודקא אמרת\u0004 \u0005[ו\u0006מה \u0005שאתה אומר]\u0006 \u0003היינו\u0004 \u0005[\u0006והרי \u0005זהו]\u0006 \u0003ניקבה!\u0004 על כך יש להשיב כי \u0003לא צריכא\u0004 \u0005[לא נצרכה]\u0006 הלכה זו שחסרה עושה טריפה אלא \u0003ל\u0004דעת \u0003ר' שמעון,\u0004 ש\u0003אמר\u0004 במשנתנו שאינה טריפה \u0003עד שתנקב\u0004 הריאה \u0003לבית הסמפונות\u0004 (הסמפון הראשי), ולא די שניקבו הקרומים, ועל כך נאמר כי \u0003הני מילי נקב דלית ביה\u0004 \u0005[דברים אלה\u0006 אמורים דווקא \u0005בנקב שאין בו]\u0006 \u0003חסרון, אבל\u0004 ב\u0003נקב דאית ביה\u0004 \u0005[שיש בו]\u0006 \u0003חסרון\u0004 — \u0003אפילו ר' שמעון מודה\u0004 שהוא טריפה.","ובענין ריאה שנשפכה כקיתון מסופר, \u0003ר' חנניה חלש\u0004 \u0005[חלה],\u0006 \u0003על לגביה\u0004 \u0005[נכנס לפניו]\u0006 \u0003ר' נתן וכל גדולי הדור\u0004 לבקרו, בתוך כך \u0003אייתו קמיה\u0004 \u0005[הביאו לפניו]\u0006 \u0003ריאה שנשפכה כקיתון, ואכשרה\u0004 \u0005[והכשיר אותה].\u0006","\u0003אמר רבא: והוא\u0004 דווקא במקרה \u0003דקיימי\u0004 \u0005[ש\u0006עדיין \u0005קיימים]\u0006 ה\u0003סמפונות\u0004 של הריאה, הצנורות הקטנים המסתעפים מן הסמפון הראשי לתוך האונות, ושם חוזרים ומסתעפים. ורק בשר הריאה נימוח. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: מנא ידעינן\u0004 \u0005[מנין יודעים אנו]\u0006 אם קיימים הסמפונות? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מייתינן צעא דקוניא\u0004 \u0005[מביאים אנו כלי של חרס\u0006 מצופה\u0005],\u0006 שאין בו סדקים, ואפשר לראות כל מה שניתן לתוכו, \u0003ושפכינן לה בגויה\u0004 \u0005[ושופכים אותה,\u0006 את תוכן הריאה \u0005בתוכו],\u0006 \u0003אי אית בה שורייקי חיורי\u0004 \u0005[אם יש בה כעין חוטים לבנים]\u0006 — \u0003טרפה,\u0004 שמן הסתם הם סמפונות שנרקבו ונשפכו לאותו כלי יחד עם בשר הריאה, \u0003ואי לאו\u0004 \u0005[ואם אין\u0006 בה\u0005]\u0006 חוטים לבנים — \u0003כשרה,\u0004 שרק בשר הריאה נימוח.","\u0003אמר רב נחמן: ריאה שנימוקה\u0004 ונתרוקנה בחלקה, ורק חלק מן הבשר נשאר, \u0003וקרום שלה\u0004 עדיין \u0003קיים\u0004 — \u0003כשרה.\u0004 ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003ריאה שנימוקה, וקרום שלה\u0004 עדיין \u0003קיים, אפילו\u0004 החלל שנוצר בתוך הקרום \u0003מחזקת\u0004 נפח של \u0003רביעית\u0004 הלוג — \u0003כשרה. ניטלה\u0004"],["\u0003שלפוחית\u0004 (הרחם) \u0003שלה\u0004 — \u0003כשרה.\u0004 אם \u0003התליע כבד שלה\u0004 של הבהמה, שנמצאו בו תולעים — \u0003זה היה מעשה\u0004 שאירע, \u0003ועלו עליה בני עסיא\u0004 (א סיא הקטנה) \u0003שלושה רגלים ל\u0004בית הדין הגדול ב\u0003יבנה\u0004 לשאול מה דינה, שכל פעם באו לשאול, ופעמיים לא השיבו להם מה דינה, \u0003לרגל שלישי\u0004 אחרי שדנו בדבר — \u0003התירוה להם.\u0004","\u0003אמר רב יוסף בר מניומי אמר רב נחמן: ריאה הסמוכה\u0004 ודבוקה \u0003לדופן\u0004 הבהמה, לצלעות — \u0003אין חוששין לה\u0004 שמא ניקבה, ומחמת הקרום שעלה במקום הנקב נדבקה לדופן, אלא יש להניח שהוא מחמת פצע שהיה בדופן. אם \u0003העלתה\u0004 הריאה עצמה \u0003צמחים\u0004 (אבעבועות מלאות מוגלה) באזור ההידבקות — \u0003חוששין לה\u0004 לנקב שהיה בריאה וסביבו עלו הבועות, שרגלים לדבר. \u0003מר יהודה משמיה\u0004 \u0005[משמו]\u0006 של \u0003אבימי אמר: אחד זה ואחד זה,\u0004 בין אם היו שם צמחים ובין אם לא, כיון שיש בה בועות — \u0003חוששין לה.\u0004 ושואלים: \u0003היכי עבדינן\u0004 \u0005[כיצד אנו עושים],\u0006 לבדוק אם הפגם היה בדופן הבהמה או בריאה עצמה?","\u0003אמר רבא, רבין בר שבא אסברה\u0004 \u0005[הסביר]\u0006 \u0003לי: מייתינן סכינא דחליש פומיה ומפרקינן לה\u0004 \u0005[מביאים סכין שפיה,\u0006 שפתה, \u0005דקה וחדה, ומפרקים אנו אותה\u0006 את הריאה מהדופן\u0005];\u0006 \u0003אי איכא ריעותא\u0004 \u0005[אם יש ריעות,\u0006 פגם\u0005]\u0006 חולי או פצע \u0003בדופן\u0004 — \u0003תלינן בתר\u0004 \u0005[תולים אנו\u0006 את ההידבקות \u0005אחר]\u0006 ה\u0003דופן,\u0004 בסיבתה. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 מצאנו פצע בדופן — \u0003מחמת ריאה היא, וטרפה, ואף על גב דלא קא מפקא זיקא\u0004 \u0005[ואף על פי שאינה מוציאה רוח]\u0006 כשמנפחים אותה. שאנו מניחים שהיה בה נקב ועלה עליו קרום, וקרום זה אין בו כדי להוציא מידי טריפה.","מסופר ש\u0003רב נחמיה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף בדיק לה\u0004 \u0005[היה בודק אותה]\u0006 ריאה כזו \u0003בפשורי\u0004 \u0005[במים פושרים],\u0006 שהיה מניח אותה בגיגית עם מים פושרים, ומנפח אותה ורואה אם עולות בועות באותו מקום. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב פפי לרבינא: הא\u0004 \u0005[בדיקה\u0006 זו\u0005]\u0006 של \u0003רב נחמיה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף, אתון אהא מתניתו לה\u0004 \u0005[אתם על זה שונים אתם אותה],\u0006 על ריאה הסמוכה לדופן. \u0003אנן\u0004 \u0005[אנו]\u0006 על דברי \u0003רבא מתנינן לה\u0004 \u0005[שונים אותה],\u0006 ש\u0003אמר רבא, הני תרתי אוני דריאה דסריכן להדדי\u0004 \u0005[אותן שתי אונות שבריאה שהן סרוכות,\u0006 דבוקות בסירכה \u0005זו לזו]\u0006 — \u0003לית להו בדיקותא לאכשורי\u0004 \u0005[אין להם בדיקה להכשיר\u0006 אותן\u0005];\u0006 ועל כך מסופר ש\u0003רב נחמיה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף בדיק לה בפשורי\u0004 \u0005[היה בודק אותה ב\u0006גיגית \u0005מים פושרים],\u0006 ואם לא יצא ממנה אויר על ידי ניפוח — הכשירה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי: האי מאי\u0004 \u0005[זה מהו]?\u0006 כלומר, כיצד יכול אתה לומר דבר זה? \u0003בשלמא הכא\u0004 \u0005[נניח כאן]\u0006 בריאה הסמוכה לדופן — \u0003תלינן\u0004 \u0005[תולים אנו]\u0006 את הדבר בפצע ש\u0003בדופן, וכשרה. אבל התם\u0004 \u0005[שם],\u0006 בשתי אונות הסרוכות זו לזו, הרי סירכא שביניהן מחמת נקב היא באה, \u0003אי האי נקיב\u0004 \u0005[אם זו יש בה נקב]\u0006 — \u0003טרפה\u0004 היא, \u0003ואי האי נקיב\u0004 \u0005[ואם זו ניקבה]\u0006 — \u0003טרפה\u0004 היא, וגם אם נסתם הנקב בקרום — אין זה מוציא אותה מידי טריפה! ושבים לדברי רב נחמן, שריאה הסמוכה לדופן, אם העלתה הריאה צמחים — חוששים שניקבה, וטריפה היא.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רב נחמן הכי\u0004 \u0005[כך]\u0006 שאם יש בה נקב הריהי טריפה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יוסף בר מניומי אמר רב נחמן: ריאה שנקבה ודופן סותמתה\u0004 — \u0003כשרה!\u0004 ודוחים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003במקום רביתא\u0004 \u0005[גידולה],\u0006 במקום שהריאה גדלה בצמוד לדופן, וכשהנקב נסתם אין חשש שיחזור וייפתח, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 מדובר שנדבקה \u0003שלא במקום רביתא\u0004 \u0005[גידולה].\u0006","ושואלים: \u0003והיכא\u0004 \u0005[והיכן]\u0006 \u0003מקום רביתא\u0004 \u0005[גידולה]?\u0006 ומשיבים: \u0003חיתוכי דאוני\u0004 \u0005[מקום חיתוך האונות זו מזו],\u0006 כלומר, בחלק הקדמי של הריאה, ששם האונות מצויות, שהוא סמוך לדפנות בית החזה מכל צידיו.","ודנים \u0003גופא\u0004 \u0005[לגופה]\u0006 של ההלכה שהזכרנו, \u0003אמר רב יוסף בר מניומי אמר רב נחמן: ריאה שנקבה ודופן סותמתה\u0004 — \u0003כשרה. אמר רבינא: והוא דסביך בבשרא\u0004 \u0005[שהריאה מסובכת\u0006 באותו מקום \u0005בבשר]\u0006 שבין הצלעות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף לרבינא: ואי לא סביך מאי\u0004 \u0005[ואם אינה סבוכה\u0006 בבשר \u0005מהי]\u0006 — \u0003טרפה, אלמא אמרינן\u0004 \u0005[מכאן שאומרים אנו,\u0006 מניחים\u0005]\u0006 ש\u0003נקובה היא.\u0004 ואולם \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003כי סביך נמי\u0004 \u0005[כאשר היא סבוכה גם כן]\u0006 בבשר נאמר שהיא נקובה וטריפה!","\u0003דהא תניא\u0004 \u0005[שהרי שנינו\u0006 בברייתא\u0005]:\u0006 אם \u0003ניקב\u0004 אבר הזכרות של אדם — הריהו \u0003פסול\u0004 לבוא בקהל, משום איסור \"כרות שפכה\" (דברים כג, יב), \u0003מפני ש\u0004באופן זה \u0003הוא שותת\u0004 הזרע, ואינו פולטו בכח כדי שיוכל להוליד. אבל אם \u0003נסתם\u0004 הנקב — \u0003כשר, מפני שהוא מוליד, וזהו פסול שחוזר להכשירו.\u0004 ויש לשאול: הדגש \u0003\"וזהו\" למעוטי מאי\u0004 \u0005[למעט מה]?\u0006 \u0003לאו למעוטי כהאי גוונא\u0004 \u0005[האם לא למעט כגון זה],\u0006 של ריאה שניקבה ודופן סותמתה, שהיא טריפה למרות שהיא סבוכה בבשר?","ועונים: \u0003לא,\u0004 בא הדבר \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003קרום שעלה מחמת מכה\u0004 \u0003בריאה\u0004 עצמה — ש\u0003אינו קרום,\u0004 שאין סתימה זו מתקיימת. אבל כאשר מקום הנקב מסובך בבשר הדופן — הרי זה כשר, שסתימה ראויה היא.","על עיקר הדברים, שדופן מועילה לסתום נקב בריאה, ולהוציאה מכלל טריפה, \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב עוקבא בר חמא: אילו אינקיב\u0004 \u0003בדופן להדה מאי\u0004 \u0005[אילו\u0006 נעשה לאחר זמן \u0005נקב בדופן מול\u0006 הנקב שבריאה \u0005מהו],\u0006 מה היה הדין? הרי היתה הבהמה נעשית \u0003טרפה\u0004 בכך. נמצא איפוא, שיש דין טריפה שתלוי בנקב בדופן, ואם כן \u0003ליתני\u0004 \u0005[שישנה]\u0006 בין הטרפות שבמשנתנו גם \u0003נקובת הדופן!\u0004","ומקשים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 הלכה \u0003הא\u0004 \u0005[זו]\u0006 ששנינו במשנה (מב,א) שאם ניקבה המרה טריפה, ועל כך \u0003אמר רב יצחק בר יוסף אמר ר' יוחנן: מרה שניקבה ו\u0004ה\u0003כבד\u0004 שהוא סמוך לה \u0003סותמתה\u0004 — \u0003כשרה,\u0004 הרי \u0003אילו אינקיב כבד להדה\u0004 \u0005[אילו\u0006 לאחר זמן \u0005ניקב הכבד כנגדה],\u0006 מול הנקב שבמרה, \u0003מאי\u0004 \u0005[מה\u0006 היה הדין\u0005]?\u0006 הריהי נעשית בכך \u0003טרפה,\u0004 אם כן \u0003ליתני\u0004 \u0005[שישנה]\u0006 במשנתנו גם \u0003נקובת הכבד!\u0004","\u0003אלא\u0004 יש לומר, \u0003כי ניקבה דלאו מיניה מיטרפא\u0004 \u0005[\u0006ש\u0005כאשר ניקב\u0006 אבר \u0005שלא ממנו\u0006 היא \u0005נעשית טריפה]\u0006 — המשנה \u0003לא קתני\u0004 \u0005[שונה]\u0006 את הדבר כטריפה בפני עצמה, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 בענייננו, \u0003כיון דלאו מיניה מיטרפא\u0004 \u0005[שלא ממנו\u0006 מן הדופן \u0005היא נטרפת]\u0006 אלא מחמת הריאה — \u0003לא קתני\u0004 \u0005[אינו שונה].\u0006","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבה בר בר חנה משמואל:\u0004 אם \u0003העלתה\u0004 הריאה \u0003צמחין\u0004 (אבעבועות מלאות מוגלה), \u0003מהו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כשרה\u0004 היא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה בר בר חנה: \u0003אף אני אומר כן, אלא שהתלמידים מזדנזין\u0004 (מפקפקים ותוהים) \u0003בדבר\u0004 זה. ש\u0003אמר רב מתנא: מליא מוגלא\u0004 \u0005[\u0006אם האבעבועה \u0005מלאה מוגלה]\u0006 — הרי היא \u0003טרפה,\u0004 אם היא מלאה ב\u0003מים זכים\u0004 — \u0003כשרה. אמר ליה\u0004 \u0005[לו]\u0006 שמואל: ההלכה \u0003ההיא\u0004 שאמר רב מתנא \u0003בכוליא אתמר\u0004 \u0005[\u0006בבועה ש\u0005בכליה נאמרה]\u0006 ולא לגבי בועה בריאה.","מסופר, \u0003רבי יצחק בר יוסף הוה קאזיל בתריה\u0004 \u0005[היה הולך אחרי]\u0006 \u0003ר' ירמיה בשוקא דטבחי\u0004 \u0005[בשוק הקצבים],\u0006 \u0003חזנהו להנך דקיימין צמחי צמחי\u0004 \u0005[ראה את הריאות תלויות שם שהיו מלאות צמחים צמחים],\u0006 רצה לברר מה דעתו בענין כשרותן, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא בעי מר אומצא\u0004 \u0005[וכי אין אדוני רוצה חתיכת בשר]?\u0006 ואם כן אפשר יהיה לקחת מאחת הבהמות הללו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' ירמיה: \u0003לית לי פריטי\u0004 \u0005[אין לי מעות].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אקפן אנא\u0004 \u0005[אני אקנה עבורך בהקפה].\u0006 כיון שראה ר' ירמיה שלא היתה לו דרך להשתמט, \u0003אמר ליה\u0004 \u0005[לו]\u0006 לרב יצחק בר יפת: \u0003מה אעביד\u0004 \u0005[אעשה]\u0006 \u0003לך! דכי אתו לקמיה\u0004 \u0005[שכאשר היו באים לפני]\u0006 \u0003ר' יוחנן\u0004 עם ריאה שיש בה צמחים, \u0003משדר להו לקמיה\u0004 \u0005[היה שולח אותם,\u0006 את השואלים, \u0005לפני]\u0006 \u0003ר' יהודה בר' שמעון, דמורי בה משמיה\u0004 \u0005[שהיה מורה בה משמו]\u0006 של \u0003ר' אלעזר בר' שמעון להיתירא\u0004 \u0005[להיתר],\u0006 \u0003וליה לא סבירא ליה\u0004 \u0005[והוא עצמו,\u0006 ר' יוחנן, \u0005לא היה סבור כן],\u0006 ולכן לא התיר בעצמו, ולשיטת ר' יוחנן אני חושש ומחמיר.","\u0003אמר רבא: כי הוה מסגינן בתריה\u0004 \u0005[כאשר היינו הולכים אחרי]\u0006 \u0003רב נחמן בשוקא\u0004 \u0005[בשוק]\u0006"],["\u0003דגלדאי\u0004 \u0005[של הרצענים],\u0006 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003בשוקא דרבנן\u0004 \u0005[בשוק החכמים],\u0006 \u0003חזי הנך דקיימן כנדי כנדי\u0004 \u0005[ראה\u0006 ריאות שיש עליהן \u0005כדים כדים,\u0006 אבעבועות גדולות (צמחים) מלאות נוזלים\u0005]\u0006 \u0003ולא אמר להו ולא מידי\u0004 \u0005[ולא אמר להם דבר\u0006 לטבחים\u0005],\u0006 משמע שהוא סבור שזה כשר. וכן מסופר,","\u0003ר' אמי ור' אסי הוו חלפי בשוקא\u0004 \u0005[היו עוברים בשוק של]\u0006 \u0003טבריא, חזי הנך דקיימי טינרי טינרי\u0004 \u0005[ראו אותן ריאות\u0006 שיש עליהן \u0005סלעים סלעים],\u0006 גושים גדולים וקשים, \u0003ולא אמרי להו ולא מידי\u0004 \u0005[ולא אמרו להם דבר],\u0006 משמע שהם סבורים שזה כשר.","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים ביחס ל\u0003מחט שנמצאת בריאה\u0004 של בהמה שנשחטה, \u0003ר' יוחנן ור' אלעזר ור' חנינא מכשרי\u0004 \u0005[מכשירים]\u0006 את הבהמה הזו, ואילו \u0003ר' שמעון בן לקיש ור' מני בר פטיש ור' שמעון בן אליקים טרפי\u0004 \u0005[מטריפים]\u0006 אותה.","ומציעים: \u0003לימא בהא קמיפלגי\u0004 \u0005[האם לומר\u0006 ש\u0005ב\u0006נושא \u0005זה הם חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 האוסרים, \u0005סבור]:\u0006 \u0003חסרון מבפנים\u0004 שהמחט עושה בבשר הריאה, אף על פי שאינו ניכר מבחוץ — \u0003שמיה\u0004 \u0005[שמו]\u0006 \u0003חסרון,\u0004 והרי זו טריפה. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 המתירים, \u0005סבור]:\u0006 \u0003לא שמיה\u0004 \u0005[אין שמו]\u0006 \u0003חסרון?\u0004 ודוחים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003חסרון מבפנים לא שמיה\u0004 \u0005[אין שמו]\u0006 \u0003חסרון, והכא בהא קמיפלגי\u0004 \u0005[וכאן\u0006 בענין המחט \u0005בזה הם חלוקים],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 המכשירים, \u0005סבור]:\u0006 \u0003סמפונא נקט ואתאי\u0004 \u0005[\u0006מ\u0005הסמפון,\u0006 דרך הקנה, נכנסה המחט, ומשם \u0005באה\u0006 לתוך הריאה\u0005],\u0006 ולא עשתה נקב בקרום הריאה. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 המטריפים, \u0005סבור]:\u0006 \u0003נקובי נקיב ואתאי\u0004 \u0005[\u0006המחט \u0005הלכה וניקבה\u0006 את המעיים, \u0005ו\u0006משם \u0005באה\u0006 וניקבה את דופן הריאה\u0005],\u0006","\u0005מסופר,\u0006 \u0003ההיא מחטא דאשתכח בחיתוכא\u0004 \u0005[אותה מחט שנמצאה בחתיכה של]\u0006 \u0003ריאה,\u0004 לאחר שנחתכה לחתיכות, \u0003אייתוה לקמיה\u0004 \u0005[הביאו אותה לפני]\u0006 \u0003ר' אמי, סבר לאכשורה\u0004 \u0005[סבור\u0006 היה \u0005להכשיר אותה].\u0006 \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' ירמיה, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003ר' זריקא\u0004 ממה ששנינו במשנתנו: \u0003הריאה שניקבה או שחסרה\u0004 — טריפה. ויש לשאול: \u0003מאי\u0004 \u0005[מהו\u0006 פירוש\u0005]\u0006 \u0003חסרה? אילימא\u0004 \u0005[אם תאמר]\u0006 שחסרה \u0003מבחוץ\u0004 — \u0003היינו\u0004 \u0005[זהו\u0006 מה ששנינו\u0005]\u0006 \u0003ניקבה,\u0004 שהרי כל חסרון מבחוץ הוא נקב בקרום הריאה! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005אין]\u0006 הכוונה שחסרה \u0003מבפנים, ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 שה\u0003חסרון\u0004 שהוא \u0003מבפנים\u0004 — \u0003שמיה\u0004 \u0005[שמא]\u0006 \u0003חסרון,\u0004 ומחט זו בודאי עשתה חסרון בבשר הריאה!","ר' אמי לא החליט בדבר, ולכן \u0003הדר שדרוה לקמיה\u0004 \u0005[חזרו ושלחו אותה,\u0006 את הריאה הזו, \u0005לפני]\u0006 \u0003ר' יצחק נפחא. סבר לאכשורה\u0004 \u0005[סבור היה\u0006 ר' יצחק \u0005להכשירה],\u0006 \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' ירמיה, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003ר' זריקה,\u0004 ממה ששנינו: \u0003הריאה שניקבה או שחסרה\u0004 — טריפה, ויש לשאול: \u0003מאי\u0004 \u0005[מה פירוש]\u0006 \u0003חסרה? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003מבחוץ\u0004 — \u0003היינו\u0004 \u0005[זהו\u0006 מה ששנינו\u0005]\u0006 \u0003ניקבה! אלא לאו\u0004 \u0005[\u0006האם \u0005אין]\u0006 הכוונה \u0003מבפנים, ושמע מינה\u0004 \u0005[ונלמד מכאן]\u0006 ש\u0003חסרון מבפנים שמיה\u0004 \u0005[שמו,\u0006 נחשב\u0005]\u0006 \u0003חסרון!\u0004","\u0003הדר שדרוה לקמיה\u0004 \u0005[חזרו ושלחו אותה לפני]\u0006 \u0003ר' אמי וטרפה\u0004 \u0005[והטריף אותה].\u0006 \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003והא רבנן מכשרי\u0004 \u0005[והרי חכמים מכשירים],\u0006 כפי שנאמר לעיל בשם ר' יוחנן ור' אלעזר ור' חנינא! \u0003אמר להן: הן הכשירו\u0004 — אחר \u0003שיודעים\u0004 היו \u0003מאיזה טעם הכשירו,\u0004 שבאה לפניהם ריאה שלימה, וראו שאין בה נקב, אבל \u0003אנן\u0004 \u0005[אנו]\u0006 \u0003מאיזה טעם נכשיר\u0004 בחתיכת ריאה שהובאה לפנינו? \u0003דלמא אי הוה\u0004 \u0005[שמא אם היתה]\u0006 ה\u0003ריאה\u0004 כולה \u0003קמן\u0004 \u0005[לפנינו]\u0006 היינו רואים שהיא \u0003מינקבה\u0004 \u0005[מנוקבת]\u0006 מצידה החיצוני!","ומתקשים בדבר: מדברים אלו יש לדייק כי \u0003טעמא דליתא\u0004 \u0005[הטעם\u0006 שהטריף הוא דווקא מפני שהריאה כולה \u0005איננה\u0006 לפניו\u0005]\u0006 \u0003הא איתא ולא מינקבה\u0004 \u0005[אבל אם היא נמצאת\u0006 לפנינו \u0005ואינה נקובה]\u0006 — \u0003כשרה? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב נחמן: האי סמפונא דריאה דאינקיב\u0004 \u0005[אחד מסמפונות הריאה שניקב]\u0006 — \u0003טרפה,\u0004 למרות שלא ניקב קרום הריאה מבחוץ! ומשיבים: \u0003ההוא\u0004 \u0005[אותו\u0006 דבר\u0005]\u0006 בסמפון שניקב \u0003לחבירו\u0004 (לסמפון אחר) שסמוך לו \u0003אתמר\u0004 \u0005[נאמר],\u0006 שכיון שקשים הם — אין הם סותמים זה את זה, אבל במחט שחודרת מסמפון אל בשר הריאה — בשר הריאה שצמוד לסמפון סותם את הנקב שבסמפון.","ומקשים, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב נחמן: האי הדורא דכנתא דאינקיב להדי חבריה\u0004 — \u0003מגין עליה\u0004 \u0005[המעיים המסובבים שיש חלב ביניהם, שניקב מעי כנגד חבירו\u0006 — חבירו סותם אותו ו\u0005מגן עליו],\u0006 מדוע אין אומרים כאן שהסמפונות מגינים זה על זה? \u0003אמר רב אשי: טרפות קא מדמי להדדי\u0004 \u0005[אתה מדמה זו לזו]?\u0006 \u0003אין אומרין בטרפות זו דומה לזו, שהרי\u0004 בבהמה יכול שיהא \u0003חותכה מכאן,\u0004 במקום אחד — \u0003ומתה, חותכה מכאן\u0004 במקום אחר \u0003וחיה!\u0004","\u0003מסופר,\u0004 \u0003ההיא מחטא דאישתכח בסמפונא רבה דריאה\u0004 \u0005[אותה מחט שנמצאה בסמפון הגדול\u0006 הראשי \u0005של הריאה],\u0006 \u0003אתיוה לקמיה דרבנן טרופאי\u0004 \u0005[הביאו אותה לפני החכמים המטריפים]\u0006 במחט שנמצאת בריאה, ר' שמעון בן לקיש ור' מני בר פטיש ור' שמעון בן אליקים, \u0003ו\u0004\u0003לא אמרו בה לא איסור ולא היתר.\u0004 ומסבירים: \u0003היתר לא אמרי\u0004 \u0005[אמרו]\u0006 \u0003בה\u0004 — \u0003כשמעתייהו\u0004 \u0005[כשמועתם,\u0006 כהלכתם\u0005]\u0006 שהם אוסרים בזה, \u0003איסור נמי לא אמרי\u0004 \u0005[גם כן לא אמרו]\u0006 \u0003בה\u0004 — \u0003כיון דבסמפונא רבה אישתכח\u0004 \u0005[שבסמפון הגדול נמצאה],\u0006 \u0003אימא סמפונא נקט ואתאי\u0004 \u0005[אמור ש\u0006דרך \u0005הסמפון\u0006 באה\u0005],\u0006 שהדברים נראים שבאה דרך הקנה (ולא דרך \u0003הוושט), שניקבה אותו ועברה לחלל הגוף, ומשם עברה וניקבה את הריאה, ומשם הגיעה לסמפון הגדול.\u0004","\u0003ההיא מחטא דאישתכח בחתיכה דכבדא\u0004 \u0005[אותה מחט שנמצאה בתוך חתיכה של כבד]\u0006 בהמה, \u0003סבר\u0004 \u0005[סבור\u0006 היה\u0005]\u0006 \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף למיטרפה\u0004 \u0005[להטריף אותה],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי: אילו אשתכח בבשרא כהאי גוונא\u0004 \u0005[אם היית מוצא\u0006 מחט \u0005בבשר\u0006 הבהמה \u0005כגון זה]\u0006 \u0003הוה טריף מר\u0004 \u0005[היה אדוני מטריף]?\u0006 והרי נקב בכבד הוא כנקב בבשר, שנקב בכבד אינו בכלל הטריפות ששנינו במשנתנו! \u0003אלא אמר רב אשי: חזינא\u0004 \u0005[רואים אנו],\u0006 \u0003אי קופא לבר\u0004 \u0005[אם הקוף,\u0006 הצד המחורר, העבה של המחט \u0005נמצא מבחוץ],\u0006 לצד חלל הבטן, וחוד המחט פונה לכבד — יש להניח ש\u0003נקובי נקיב ואתאי\u0004 \u0005[ניקבה המחט\u0006 את הוושט ויצאה לחלל הגוף עד \u0005שבאה\u0006 לכבד\u0005],\u0006 ולכן טריפה היא, וכדין נקובת הוושט. \u0003אי קופא לגיו\u0004 \u0005[אם הקוף\u0006 פונה \u0005לפנים\u0006 הכבד\u0005],\u0006 וחוד המחט פונה מן הכבד החוצה לחלל הגוף, יש להניח ש\u0003סמפונא נקט ואתאי\u0004 \u0005[\u0006דרך \u0005סמפון,\u0006 כלי דם, \u0005של הכבד באה]\u0006 לכבד דרך מערכת הדם, ולא נקבה את הוושט והגיעה לכבד דרך חלל הגוף, ולכן היא כשרה.","ומוסיפים: \u0003והני מילי באלימתא\u0004 \u0005[ודברים אלה אמורים ב\u0006מחט \u0005גסה,\u0006 גדולה\u0005],\u0006 שאין הקוף שלה יכול לעשות נקב בבשר, ולכן יש להניח שהגיעה דרך הסמפון, \u0003אבל קטינתא\u0004 \u0005[\u0006במחט \u0005דקה],\u0006 \u0003לא שנא קופא לגיו לא שנא קופא לבר\u0004 \u0005[אינו שונה אם הקוף לפנים, אינו שונה אם הקוף לחוץ],\u0006 יש לחשוש ש\u0003נקובי נקיב ואתאי\u0004 \u0005[נקבה\u0006 את הוושט, ומחלל הגוף \u0005באה\u0006 לכבד\u0005].\u0006","ושואלים: \u0003ומאי שנא\u0004 \u0005[ומה שונה הדבר]\u0006 \u0003ממחט שנמצאת\u0004"],["תחובה \u0003בעובי\u0004 דופן \u0003בית הכוסות\u0004 (אחת מקיבות הבהמה), אם היא נראית רק \u0003מצד אחד\u0004 של הדופן, בצד הפנימי — \u0003כשרה,\u0004 אם היא נראית \u0003משני צדדין\u0004 — \u0003טרפה, ולא אמרינן\u0004 \u0005[ואין אנו אומרים]\u0006 במקרה שהיא נראית רק מצד אחד: \u0003ליחזי אי קופא לבר אי קופא לגיו\u0004 \u0005[נראה אם קוף\u0006 המחט פונה \u0005לחוץ,\u0006 לחלל הבטן, או \u0005אם קוף\u0006 המחט פונה \u0005לפנים]?\u0006 שאם קוף המחט פונה לחלל הבטן, וחודה לתוך בית הכוסות — סימן שהמחט נקבה את הוושט או הכרס ויצאה לחלל הבטן, ומשם חזרה ונכנסה לבית הכוסות, ובמקרה זה, אפילו אם היא נמצאת רק בצד הפנימי — טריפה היא. ורק אם קוף המחט פונה פנימה — סימן שהגיעה ישירות דרך הוושט לחלל בית הכוסות, והחלה לנקוב את הדופן ועדיין לא ניקבה אותו מצד לצד?","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003התם\u0004 \u0005[שם],\u0006 \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 בתוך בית הכוסות \u0003אוכלים ומשקים\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003אוכלים ומשקים דחקוה\u0004 \u0005[דחקו אותה]\u0006 את המחט, וגם אם קוף המחט נעוץ בדופן, אין זה מוכיח שבאה מן החוץ.","מסופר, \u0003ההוא מחטא דאישתכח בסמפונא רבה דכבדא\u0004 \u0005[אותה מחט שנמצאה בסמפון הגדול של הכבד],\u0006 \u0003הונא מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי טריף\u0004 \u0005[הטריף],\u0006 \u0003רב אדא בר מניומי מכשר\u0004 \u0005[הכשיר].\u0006 \u0003אתו שיילוה\u0004 \u0005[באו שאלו]\u0006 את \u0003רבינא\u0004 בענין זה, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003שקילו גלימא דטרופאי\u0004 \u0005[טלו את גלימתם של המטריפים],\u0006 שישלמו מכיסם על שהטריפוה בחינם והשליכוה לכלבים.","ועוד מסופר: \u0003ההיא קשיתא דאישתכח\u0004 \u0005[אותו גרעין\u0006 של תמרה \u0005שנמצא]\u0006 \u0003במרה. אמר רב אשי, כי הוינן בי\u0004 \u0005[כאשר היינו בבית]\u0006 \u0003רב כהנא\u0004 כתלמידיו, \u0003אמר\u0004 במקרה זה: \u0003הא\u0004 \u0005[זו]\u0006 \u0003ודאי סימפונא נקט ואתאי\u0004 \u0005[\u0006דרך \u0005הסמפון\u0006 שבין הכבד למרה \u0005באה],\u0006 ומשם נכנסה למרה, ולא ייתכן שעשתה נקב במרה, מפני שאינה חדה דיה כדי לעשות כן. ומוסיפים: \u0003אף על גב דלא קא נפקא\u0004 \u0005[אף על פי שאינה יוצאת]\u0006 אם מנסים להעביר אותה בסמפון, יש לומר כי נענוע גופה של הבהמה \u0003מירבל הוא דרביל ליה\u0004 \u0005[מנענע אותה כמו בכברה],\u0006 ובמשך הזמן היא נדחקת פנימה. ומעירים: \u0003והני מילי דדיקלא\u0004 \u0005[ודברים אלה אמורים\u0006 בגרעין \u0005של דקל,\u0006 תמר\u0005],\u0006 \u0003אבל\u0004 גרעין \u0003דזיתא\u0004 \u0005[של זית]\u0006 שיש לו קצוות מחודדים — ודאי \u0003מיבזע בזע\u0004 \u0005[מנקב],\u0006 וטריפה היא.","ושבים לדון בריאה. ומביאים מה ש\u0003אמר ר' יוחנן: למה נקרא שמה ריאה?\u0004 מפני \u0003שמאירה את העינים\u0004 של האוכל אותה. \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 שאלה לחכמים: האם הכוונה היא \u0003לאכילה\u0004 כמו שהיא, \u0003או\u0004 דווקא \u0003על ידי\u0004 עיבוד ב\u0003סמנין\u0004 (חומרים שונים)?","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ש\u0003אמר רב הונא בר יהודה: אווזא בזוזא\u0004 \u0005[אווז\u0006 שלם קונים \u0005בזוז],\u0006 \u0003וריאה דידה\u0004 \u0005[שלו]\u0006 \u0003בארבעה\u0004 זוזים, \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 שמה שנאמר הוא \u0003לאכילה\u0004 בפני עצמה — \u0003לינקט בזוזא וליכול\u0004 \u0005[שיקח,\u0006 יקנה אווז שלם \u0005בזוז ויאכל\u0006 גם את הריאה\u0005]!\u0006 \u0003אלא,\u0004 ודאי הכוונה היא שריאה זו מאירה עיניים \u0003על ידי סמנין,\u0004 והעיבוד בסמנים הוא שמייקר את מחירה.","ושבים לענין ריאה שניקבה, ששנינו במשנתנו שהיא טריפה. ושואלים: אם \u0003אינקבה\u0004 \u0005[ניקבה]\u0006 ה\u0003ריאה היכא דממשמשא ידיה דטבחא\u0004 \u0005[במקום שממשמשת יד הטבח],\u0006 כשהוא עוסק בבהמה לאחר השחיטה, האם \u0003תלינן\u0004 \u0005[תולים אנו]\u0006 בטבח, ואומרים שעל ידי משמוש ידיו נוצר הנקב, \u0003או לא תלינן\u0004 \u0005[תולים אנו]?\u0006 \u0003רב אדא בר נתן אמר: תלינן\u0004 \u0005[תולים אנו],\u0006 \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מרי אמר: לא תלינן\u0004 \u0005[לא תולים אנו].\u0006 ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]:\u0006 \u0003תלינן\u0004 \u0005[תולים אנו].\u0006","\u0003אמר רב שמואל בריה\u0004 \u0005[בנו]\u0006 של \u0003רבי אבהו: אבא מרישי כלי\u0004 \u0005[אבי מראשי הכלה]\u0006 של \u0003רפרם הוה\u0004 \u0005[היה],\u0006 מן הדרשנים, שהיו משמיעים את דבריו לעם כשהיה דורש ברבים, \u0003ו\u0004הוא \u0003אמר: תלינן\u0004 \u0005[תולים אנו].\u0006 \u0003אמרוה קמיה להא\u0004 \u0005[אמרו לפניו\u0006 את ההלכה \u0005הזו]\u0006 של \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מרי\u0004 שאמר שאין תולים, \u0003ולא קבלה.\u0004","\u0003אמר רב משרשיא:\u0004 \u0003כוותיה דאבוה דאבא מסתברא\u0004 \u0005[כשיטתו של אביו של אבא,\u0006 רב אדא בר נתן, \u0005מסתבר],\u0006 \u0003דהא תלינן\u0004 \u0005[שהרי תולים אנו]\u0006 \u0003בזאב\u0004 שלקח את בני המעיים והחזירם מנוקבים, שהוא שניקבם, ולא שהיו נקובים מתחילה.","כאשר נעשה נקב בריאה על ידי \u0003מורנא\u0004 \u0005[תולעת],\u0006 \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה רב יוסף בר דוסאי ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003חד\u0004 \u0005[אחד מהם]\u0006 \u0003אמר: קודם שחיטה פריש\u0004 \u0005[פרשה]\u0006 התולעת מתוך הריאה, וניקבה את הריאה, וטריפה היא. \u0003וחד\u0004 \u0005[ואחד מהם]\u0006 \u0003אמר: לאחר שחיטה פריש\u0004 \u0005[פרשה],\u0006 ונקב זה לא היה בחייה. \u0003והלכתא\u0004 \u0005[והלכה]:\u0006 \u0003לאחר שחיטה פריש\u0004 \u0005[פרשה],\u0006 ואין זו \u0003טריפה.\u0004","שנינו במשנה: \u0003ר' שמעון אומר\u0004 ריאה שניקבה אינה עושה טריפה \u0003עד שתינקב\u0004 לבית הסמפונות. ומהו בית הסמפונות? \u0003אמר רבה בר תחליפא אמר ר' ירמיה בר אבא: עד שתינקב לסמפון גדול,\u0004 הקנה הגדול שממנו מתפצלים הסמפונות של הריאה.","מסופר, \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב אחא בר אבא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב הונא, ויתיב וקאמר\u0004 \u0005[וישב ואמר],\u0006 \u0003אמר רבי מלוך אמר ר' יהושע בן לוי: הלכה כר' שמעון. אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: \u0003מלוך ערבאה קאמרת\u0004 \u0005[\u0006בשמו של \u0005מלוך הערבי אמרת]?\u0006 \u0003אין הלכה כר' שמעון קאמר\u0004 \u0005[הוא אומר]!\u0006","עוד מסופר, \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003רבי זירא\u0004 לארץ ישראל, \u0003אשכחיה\u0004 \u0005[מצא]\u0006 את \u0003רב ביבי דיתיב וקאמר\u0004 \u0005[שיושב ואומר],\u0006 \u0003אמר ר' מלוך אמר ר' יהושע בן לוי: הלכה כר' שמעון. אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא: \u0003חיי דמר\u0004 \u0005[חיי אדוני],\u0006 \u0003דאנא\u0004 \u0005[שאני]\u0006 \u0003ור' חייא בר אבא ורב אסי איקלעינן לאתריה\u0004 \u0005[נזדמננו למקומו]\u0006 של \u0003רבי מלוך, ואמרי ליה\u0004 \u0005[ואמרנו לו]:\u0006 \u0003אי אמר מר\u0004 \u0005[האם אמר אדוני]\u0006 ש\u0003הלכה כר' שמעון? ואמר לן\u0004 \u0005[לנו]:\u0006 \u0003אין הלכה כר' שמעון אמרי\u0004 \u0005[אמרתי].\u0006 שאל אותו רב ביבי: \u0003ואת\u0004 \u0005[ואתה]\u0006 \u0003מה\u0004 עוד יש \u0003בידך\u0004 בענין זה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא, \u0003הכי\u0004 \u0005[כך]\u0006 \u0005אמר ר' יצחק בר אמי אמר ר' יהושע בן לוי: הלכה כר' שמעון.\u0006","\u0003ו\u0004מסכמים: \u0003ואין הלכה כר' שמעון,\u0004 אלא כל שניקבו קרומי הריאה הרי זו טריפה.","שנינו במשנה: \u0003ניקבה הקבה\u0004 הרי זו טריפה. ובענין הנוגע לדין זה, \u0003אמר ר' יצחק בר נחמני אמר ר' אושעיא: חלב\u0004 (שומן) \u0003שעל גבי קבה\u0004 — \u0003כהנים,\u0004 המקבלים את הקיבה של בהמת חולין, \u0003נהגו בו היתר, כ\u0004דעת \u0003ר' ישמעאל שאמר משום\u0004 (בשם) \u0003אבותיו. ו\u0004הואיל ויש מחלוקת בענין זה, כמבואר להלן, \u0003סימניך\u0004 לזכור מי התיר את הדבר, ביטוי שהיו רגילים לומר: \u0003ישמעאל כהנא\u0004 \u0005[הכהן]\u0006 \u0003מסייע כהני\u0004 \u0005[לכהנים].\u0006","ומבררים: \u0003מאי היא\u0004 \u0005[מהו]?\u0006 על מה נאמר שהוא מסייע לכהנים? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 בענין ברכת כהנים: \u0003\"כה תברכו את בני ישראל\" וכו'\u0004 (במדבר ו, כד), \u0003ר' ישמעאל אומר: למדנו\u0004 מכאן שיש \u0003ברכה לישראל מפי כהנים,\u0004 ואילו \u0003לכהנים עצמן לא למדנו\u0004 שיש ברכה, אלא \u0003כשהוא אומר\u0004 בסוף הברכה: \"ושמו את שמי על בני ישראל \u0003ואני אברכם\"\u0004 (שם כז) — \u0003הוי אומר: כהנים מברכין לישראל, והקדוש ברוך הוא מברך לכהנים,\u0004 שעל הכהנים נאמר \"ואני אברכם\".","ואילו \u0003ר' עקיבא אומר\u0004 שיש לפרש את הפסוק אחרת: \u0003למדנו ברכה לישראל מפי כהנים,\u0004 ואולם ברכה לישראל \u0003מפי גבורה\u0004 (הקדוש ברוך הוא) \u0003לא למדנו, כשהוא אומר \"ואני אברכם\"\u0004 — \u0003הוי אומר כהנים מברכין לישראל, והקדוש ברוך הוא מסכים על ידם,\u0004 ש\"אברכם\" נאמר על ישראל.","ושואלים: \u0003אלא ר' עקיבא, ברכה לכהנים מנא ליה\u0004 \u0005[מנין לו]?\u0006 \u0003אמר רב נחמן בר יצחק: מ\u0004מה שנאמר לאברהם \u0003\"ואברכה מברכיך\"\u0004 (בראשית יב, ג), שכל המברך את ישראל הוא עצמו מתברך.","ושואלים: הואיל וגם ר' עקיבא סבור שה' מברך את הכהנים, \u0003ומאי מסייע כהני\u0004 \u0005[ומה סיוע\u0006 מיוחד ל\u0005כהנים]\u0006 יש בדברי ר' ישמעאל? ומשיבים: משום \u0003דמוקי לה\u0004 \u0005[שהוא מעמיד לה]\u0006 \u0003לברכת\u0004 ה' ל\u0003כהנים במקום\u0004 ה\u0003ברכה\u0004 של \u0003ישראל,\u0004 באותו כתוב עצמו, לומר שגם הכהנים מתברכים באותה ברכה.","ומבררים: ומה שאמרנו, שחלב שעל גבי הקיבה כהנים נהגו בו היתר כ\u0003ר' ישמעאל שאמר משום אבותיו, מאי\u0004 \u0005[מה]\u0006 \u0003היא?\u0004 היכן מצאנו שאמר כן ר' ישמעאל? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"את כל החלב אשר על הקרב\",\u0004"],["הרי זה \u0003להביא\u0004 (לרבות) לאיסור \u0003חלב שעל גבי הדקין\u0004 (המעיים הדקים) הנמשכים מן הקיבה, אלו \u0003דברי ר' ישמעאל. ר' עקיבא אומר:\u0004 הרי זה בא \u0003להביא חלב שעל גבי הקבה.\u0004 ואילו ר' ישמעאל מתיר חלב שעל הקיבה, והוא מה שנאמר לעיל שהכהנים נהגו בו היתר כשיטתו.","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא: נאמר באיסור חלב \"החלב המכסה את הקרב ו\u0003את\u0004 כל \u0003החלב אשר על הקרב\"\u0004 (ויקרא ג, ג), \u0003ר' שמעון\u0004 (ישמעאל) \u0003אומר: מה חלב המכסה את הקרב\u0004 שאסר הכתוב, יש עליו \u0003קרום,\u0004 והקרום \u0003נקלף\u0004 בקלות מן החלב — \u0003אף כל\u0004 חלב שיש לו \u0003קרום, ו\u0004הקרום \u0003נקלף\u0004 בקלות מן החלב — הרי זה אסור, ואף חלב שעל גבי הקיבה בכלל זה. \u0003ר' עקיבא אומר: מה חלב המכסה את הקרב,\u0004 הוא \u0003תותב,\u0004 פרוש כשמלה על הבשר ואינו מהודק, וגם יש לו \u0003קרום ו\u0004הוא \u0003נקלף\u0004 — \u0003אף כל\u0004 חלב שהוא \u0003תותב\u0004 ויש לו \u0003קרום ונקלף,\u0004 כגון חלב שעל גבי הדקין — אסור. אבל אם אינו תותב, אלא דבוק בבשר, וכגון חלב שעל גבי הקיבה — אינו חלב אסור, אלא שומן מותר. ונמצא שלפי ברייתא זו, ר' ישמעאל הוא האוסר חלב שעל גבי הקיבה!","\u0003שלח רבין משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן:\u0004 כפי ששנינו בברייתא זו — \u0003כך היא הצעה של משנה,\u0004 כלומר, כך צריך לומר, \u0003ואיפוך קמייתא\u0004 \u0005[והפוך את\u0006 שיטות התנאים בברייתא \u0005הראשונה],\u0006 ואמור ש\"כל החלב אשר על הקרב\" בא לרבות לאיסור חלב שעל הדקין לדברי ר' עקיבא, ולדעת ר' ישמעאל הוא בא לרבות לאיסור גם חלב שעל הקיבה.","ושואלים: \u0003מאי חזית דאפכת קמייתא\u0004 \u0005[מה רואה אתה שאתה הופך את\u0006 הברייתא \u0005הראשונה]?\u0006 \u0003איפוך בתרייתא\u0004 \u0005[הפוך את האחרונה]!\u0006 ומשיבים: \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 בברייתא השניה, \u0003כיון דקתני\u0004 \u0005[שהוא שונה]\u0006 בלשון \u0003\"מה\u0004 חלב המכסה את הקרב\" וכו', שהוא מדקדק בלשון הכתוב, מה בדיוק למדים מ\"המכסה את הקרב\" — הרי זה סימן שהיא \u0003דווקא\u0004 \u0005[\u0006נאמרה \u0005בדיוק].\u0006","\u0005ומקשים:\u0006 \u0003אי הכי\u0004 \u0005[אם כך],\u0006 מה שנאמר בעמוד הקודם, שחלב שעל גבי הקיבה כהנים נהגו בו היתר \u0003כ\u0004דעת \u0003ר' ישמעאל\u0004 שאמר משום אבותיו, הלא \u0003כ\u0004דעת \u0003ר' עקיבא היא! אמר רב נחמן בר יצחק,\u0004 כך צריך לפרש: אלה דברי ר' ישמעאל \u0003שאמר משום אבותיו, וליה לא סבירא ליה\u0004 \u0005[ו\u0006אולם \u0005הוא\u0006 עצמו \u0005אינו סבור כן],\u0006 ולדעתו הוא אסור.","ובקשר שבין החלב האסור והמותר לבין דיני טריפות, \u0003אמר רב: חלב טהור\u0004 (מותר), אם היה תחתיו נקב שעושה טריפה — הרי הוא \u0003סותם\u0004 אותו, ואינה טריפה, ואילו חלב \u0003טמא\u0004 — \u0003אינו סותם.\u0004 \u0003ורב ששת אומר: אחד זה ואחד זה סותם.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' זירא:\u0004 לדברי רב, שחלב טמא אינו סותם, \u0003חלב חיה,\u0004 שכולו מותר, \u0003מאי\u0004 \u0005[מה]\u0006 דינו לענין זה? האם ב\u0003דוקא אמר\u0004 רב ש\u0003חלב טהור סותם, והאי נמי\u0004 \u0005[וזה,\u0006 חלב חיה, \u0005גם כן]\u0006 \u0003טהור הוא,\u0004 שאין בחיה איסור חלב בכלל, ואם כן, גם חלב שבבהמה אינו סותם, כגון החלב המכסה את הקרב — בחיה הוא סותם, ואינה טריפה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 לא נאמר שחלב טהור בבהמה סותם אלא \u0003משום דמהדק\u0004 \u0005[ש\u0006החלב הטהור \u0005מהודק],\u0006 \u0003והאי לא מהדק\u0004 \u0005[וזה,\u0006 החלב המכסה את הקרב, בחיה \u0005אינו מהודק],\u0006 ולכן אינו סותם?","\u0003אמר אביי: מאי תיבעי ליה\u0004 \u0005[מה נסתפק לו]\u0006 לר' זירא? כלומר, פשוט הדבר, \u0003נהי דשרי\u0004 \u0005[גם אם אמנם מותר\u0006 חלב זה\u0005]\u0006 \u0003באכילה,\u0004 מכל מקום \u0003אהדוקי לא מהדק\u0004 \u0005[אינו מהודק],\u0006 ואינו סותם!","מסופר, \u0003ההוא נקב דסתמה\u0004 \u0005[אותו נקב\u0006 שנמצא בבהמה \u0005שסתם אותו]\u0006 \u0003חלב טמא, דאתא לקמיה\u0004 \u0005[שבא לפני]\u0006 \u0003רבא,\u0004 \u0003אמר רבא: למאי ניחוש לה\u0004 \u0005[למה נחשוש בזה]?\u0006 \u0003חדא\u0004 \u0005[אחת]\u0006 — \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר רב ששת: חלב טמא נמי\u0004 \u0005[גם כן]\u0006 \u0003סותם. ועוד, התורה חסה על ממונם של ישראל,\u0004 ולכן יש להקל. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא:\u0004 יש בדבר זה שיטת \u0003רב\u0004 שאוסר, \u0003ו\u0004יש בזה גם \u0003איסורא דאורייתא\u0004 \u0005[איסור מן התורה],\u0006 \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 ומשתמש בנימוק ש\u0003התורה חסה על ממונן של ישראל?!\u0004","כיוצא בזה מסופר, \u0003מניומין כנדוקא\u0004 \u0005[עושה הכדים]\u0006 \u0003איגלי ליה בסתקא דדובשא\u0004 \u0005[נתגלה לו כלי מלא דבש],\u0006 והיה חשש שמא אכל ממנו נחש והטיל בו ארס, \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רבא\u0004 לשאול מה דינו, \u0003אמר רבא: למאי ניחוש לה\u0004 \u0005[למה נחשוש בכך]?\u0006 \u0003חדא\u0004 \u0005[אחת]\u0006 — \u0003דתנן\u0004 \u0005[ששנינו]:\u0006 \u0003שלשה משקים אסורים משום גילוי\u0004 — \u0003היין, והמים והחלב, ושאר כל המשקים מותרים,\u0004 ואם כן, אין הדבש בכלל האיסור. \u0003ועוד, התורה חסה על ממונם של ישראל. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר יצחק לרבא:\u0004 הרי עומדת לפנינו שיטת \u0003ר' שמעון,\u0004 שסבור שגם דבש הוא בכלל המשקים האסורים משום גילוי, \u0003ו\u0004יש כאן חשש של \u0003סכנת נפשות, ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 \u0003התורה חסה על ממונם של ישראל?\u0004","ומבררים: שיטת \u0003ר' שמעון\u0004 בענין זה \u0003מאי היא\u0004 \u0005[מה הוא]?\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003חמשה\u0004 משקים \u0003אין בהם משום גילוי,\u0004 שהנחשים אינם טועמים מהם: \u0003ציר\u0004 היוצא מן הדגים, \u0003וחומץ, שמן, ודבש, ומורייס\u0004 (ציר עשוי משומן דגים ומלח), \u0003ר' שמעון אומר: אף הן יש בהן משום גילוי. ואמר ר' שמעון: אני\u0004 עצמי \u0003ראיתי נחש ששתה ציר בצידן. אמרו לו\u0004 חכמים: \u0003שטיא הוה\u0004 \u0005[שוטה היה]\u0006 אותו נחש, משונה בהתנהגותו, \u0003ואין מביאין ראיה מן השוטים.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לרב נחמן בר יצחק: \u0003אודי לי מיהת\u0004 \u0005[הודה לי על כל פנים]\u0006 \u0003בציר\u0004 שאין בו חשש גילוי, שהרי מוחזק בידינו שאין הלכה כר' שמעון בענין זה, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003כי הוה להו גילויא\u0004 \u0005[כאשר היה להם\u0006 דבר שיש בו \u0005חשש ל\u0006\u0005גילוי]\u0006 \u0003שדו ליה\u0004 \u0005[היו משליכים]\u0006 אותו \u0003בציר,\u0004 שמחמת חריפותו מבטל את הארס. ומן הצד השני \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן בר יצחק לרבא: \u0003אודי לי מיהא\u0004 \u0005[הודה לי על כל פנים]\u0006 \u0003בדבש\u0004 שהוא אסור משום גילוי, שכן \u0003ר' שמעון בן אלעזר קאי כוותיה\u0004 \u0005[הולך כשיטתו]\u0006 של ר' שמעון, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003וכן היה ר' שמעון בן אלעזר אוסר בדבש.\u0004","ושוב לענין העיקרי, \u0003אמר רב נחמן: חלב העשוי ככובע,\u0004 למרות שהוא טהור (מותר באכילה) — \u0003אינו סותם,\u0004 ואם היה נקב באותו מקום הרי זו טריפה. ושואלים: \u0003היכא\u0004 \u0005[היכן]\u0006 נמצא חלב כזה? \u0003אמרי לה\u0004 \u0005[יש אומרים]\u0006 שהוא \u0003חיטי דכרכשא\u0004 \u0005[חיטים,\u0006 מעין פירורים של חלב, \u0005שנמצאות\u0006 על \u0005החלחולת],\u0006 החלק האחרון של המעי, שנקב שבה עושה טריפה. \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שזה \u0003טרפשא דליבא\u0004 \u0005[הקרום שעוטף את הלב],\u0006 שאם ניקב לבית חללו הרי זו טריפה, ואין החלב סותם.","\u0003אמר רבא, שמעית מיניה\u0004 \u0005[שמעתי ממנו]\u0006 מ\u0003רב נחמן\u0004 בענין החלב שעל גבי הקיבה \u0003תרתי\u0004 \u0005[שתים],\u0006 ששני חלבים נמצאים על גבי הקיבה, בשני מקומות שונים, כאשר יפורט להלן, אחד קרוי \u0003חימצא ו\u0004אחד \u0003בר חימצא, חד סתים וחד לא סתים\u0004 \u0005[אחד\u0006 מהם \u0005סותם\u0006 נקב שיש בקיבה כנגדו \u0005ואחד אינו סותם],\u0006 \u0003ולא ידענא הי מינייהו\u0004 \u0005[ואיני יודע\u0006 על \u0005איזה מהם]\u0006 אמר שסותם ועל איזה אמר שאינו סותם. \u0003רב הונא בר חיננא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן אמר: בר חימצא סתים\u0004 \u0005[סותם],\u0006 \u0003חימצא לא סתים\u0004 \u0005[אינו סותם].\u0006 \u0003אמר רב טבות: וסימניך\u0004 כדי שתזכור את הענין — \u0003יפה כח הבן\u0004 (\"בר חימצא\") שהוא סותם \u0003מכח האב\u0004 (\"חימצא\") שאינו סותם.","ושואלים: \u0003הי\u0004 \u0005[איזה הוא]\u0006 \u0003חימצא והי\u0004 \u0005[ואיזה הוא]\u0006 \u0003בר חימצא?\u0004 ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ש\u0003אמר רב נחמן\u0004 בענין זה על אחד מן החלבים שעל הקיבה: הייתכן כי \u0003אינהו\u0004 \u0005[הם,\u0006 בני ארץ ישראל\u0005]\u0006 \u0003מיכל אכלי\u0004 \u0005[אוכלים ממנו],\u0006 משום שסבורים שהוא חלב טהור,"]]};
